/* 자동 생성 — tools/build_data.py. 직접 고치지 마세요. */
(window.TS_DATA = window.TS_DATA || {}).p4 = [{"id":"p4-001","level":1,"topic":"치과 예약 확인 전화","talk_type":"전화 메시지","voice":"female","script":"Hello, this is Karen from Bright Smile Dental Clinic. I'm calling to remind you about your appointment with Dr. Lee tomorrow, Tuesday, at three o'clock in the afternoon. It's a regular checkup, so it should take about thirty minutes. Please arrive ten minutes early to fill out a short form. Also, please remember to bring your insurance card with you. If you need to change the time of your appointment, please call us back at 555-0142 before five o'clock today. Our office is closed in the evening. Thank you, and we'll see you tomorrow.","graphic":null,"questions":[{"q":"Why is the speaker calling?","choices":["To cancel a checkup","To ask for payment of an outstanding bill","To introduce a new dentist","To confirm a scheduled visit"],"answer":3,"type":"주제·목적","explanation":"화자가 \"I'm calling to remind you about your appointment with Dr. Lee tomorrow\"라고 했으므로 예정된 방문(예약)을 확인하려는 전화다. 검진(checkup)을 취소하는 것이 아니다."},{"q":"What should the listener bring?","choices":["A short form","A payment receipt","A photograph","An insurance card"],"answer":3,"type":"세부 사항","explanation":"화자가 \"please remember to bring your insurance card\"라고 했다. 양식(form)은 병원에 와서 작성하는 것이지 가져오는 것이 아니다."},{"q":"Why should the listener call back?","choices":["To get directions","To ask about evening hours","To reschedule an appointment","To order a new card"],"answer":2,"type":"세부 사항","explanation":"화자가 \"If you need to change the time of your appointment, please call us back\"이라고 했으므로 예약 변경을 원할 때 전화하면 된다. change the time을 reschedule로 바꿔 표현했다."}],"translation":"안녕하세요, 브라이트 스마일 치과의 캐런입니다. 내일 화요일 오후 3시 이 선생님과의 예약을 다시 알려 드리려고 전화드렸습니다. 정기 검진이라 30분 정도 걸릴 거예요. 간단한 양식을 작성하셔야 하니 10분 일찍 와 주세요. 그리고 보험 카드를 꼭 가져오세요. 예약 시간을 바꾸셔야 하면 오늘 5시 전에 555-0142로 전화 주세요. 저녁에는 병원 문을 닫습니다. 감사합니다. 내일 뵙겠습니다.","part":4},{"id":"p4-002","level":1,"topic":"슈퍼마켓 폐점 안내","talk_type":"안내 방송","voice":"male","script":"Attention, shoppers. The time is now eight forty-five. Green Valley Supermarket will be closing in fifteen minutes. Please bring your final items to the checkout counters at the front of the store. Tonight, only registers one through four are open. If you have ten items or fewer, please use register one for faster service. When you are finished, please return your shopping carts to the front entrance. Also, don't forget that our weekend sale starts tomorrow morning. All fresh fruit and vegetables will be twenty percent off. We open at seven a.m. Thank you for shopping at Green Valley Supermarket.","graphic":null,"questions":[{"q":"Where is the announcement being made?","choices":["At a bank","At a farm","At a grocery store","At a restaurant on Main Street"],"answer":2,"type":"화자 정보(직업·장소)","explanation":"\"Green Valley Supermarket will be closing\"과 계산대(checkout counters), 과일·채소 세일 내용으로 보아 식료품점이다. 과일·채소라는 말만 듣고 농장을 고르면 안 된다."},{"q":"What are shoppers with only a few items asked to do?","choices":["Come back tomorrow","Go to a specific register","Use a shopping basket","Ask for help"],"answer":1,"type":"요청·제안","explanation":"화자가 \"If you have ten items or fewer, please use register one\"이라고 했으므로 특정 계산대(1번)로 가야 한다."},{"q":"What will happen tomorrow?","choices":["The store will open late.","New registers will be installed.","A sale will begin.","The store will close early."],"answer":2,"type":"세부 사항","explanation":"화자가 \"our weekend sale starts tomorrow morning\"이라고 했으므로 내일 세일이 시작된다. 오전 7시에 여는 것은 평소대로이며 늦게 연다는 말은 없다."}],"translation":"쇼핑객 여러분께 알려 드립니다. 지금 시각은 8시 45분입니다. 그린 밸리 슈퍼마켓은 15분 후에 문을 닫습니다. 마지막 물건을 매장 앞쪽 계산대로 가져와 주십시오. 오늘 밤에는 1번부터 4번 계산대만 운영합니다. 물건이 10개 이하인 분은 더 빠른 계산을 위해 1번 계산대를 이용해 주십시오. 계산을 마치시면 쇼핑 카트를 정문 입구로 돌려놓아 주십시오. 또한 내일 아침부터 주말 세일이 시작된다는 것을 잊지 마세요. 모든 신선 과일과 채소가 20퍼센트 할인됩니다. 저희는 오전 7시에 문을 엽니다. 그린 밸리 슈퍼마켓을 이용해 주셔서 감사합니다.","part":4},{"id":"p4-003","level":1,"topic":"청소 시간 변경 공지","talk_type":"회의 발췌","voice":"female","script":"Good morning, everyone. Before we start today's meeting, I have a quick announcement. Starting next week, the cleaning staff will come in the morning instead of the evening. They'll arrive at seven and finish by nine. So, if you come in early, you may see them working near your desk. Please try to keep your desk clear of papers at the end of each day. That way, they can clean it easily. Also, please put any food in the kitchen trash, not in the trash cans under your desks. Thanks for your help. Now, let's talk about this month's sales.","graphic":null,"questions":[{"q":"What is the announcement mainly about?","choices":["A new sales goal","A change in a cleaning schedule","A kitchen renovation","Earlier meeting times"],"answer":1,"type":"주제·목적","explanation":"화자가 \"the cleaning staff will come in the morning instead of the evening\"이라고 했으므로 청소 시간 변경에 관한 공지다. 매출(sales)은 공지 뒤에 다룰 안건이다."},{"q":"What are listeners asked to do at the end of each day?","choices":["Arrive at seven","Clear their desks","Empty the trash cans","Turn off their computers"],"answer":1,"type":"요청·제안","explanation":"화자가 \"Please try to keep your desk clear of papers at the end of each day.\"라고 했으므로 책상을 정리해야 한다. 7시는 청소 직원이 오는 시각이다."},{"q":"What will the speaker most likely talk about next?","choices":["Sales results","Cleaning tips","Kitchen rules","Staff vacations"],"answer":0,"type":"다음 할 일","explanation":"화자가 마지막에 \"Now, let's talk about this month's sales.\"라고 했으므로 이번 달 매출 이야기를 할 것이다."}],"translation":"좋은 아침입니다, 여러분. 오늘 회의를 시작하기 전에 간단히 공지할 것이 있습니다. 다음 주부터 청소 직원들이 저녁 대신 아침에 옵니다. 7시에 와서 9시까지 끝냅니다. 그래서 일찍 출근하시면 책상 근처에서 일하는 청소 직원을 보실 수도 있습니다. 매일 퇴근할 때 책상 위에 서류를 치워 주세요. 그래야 쉽게 청소할 수 있습니다. 또한 음식물은 책상 밑 휴지통이 아니라 탕비실 쓰레기통에 버려 주세요. 협조해 주셔서 감사합니다. 이제 이번 달 매출에 대해 이야기해 봅시다.","part":4},{"id":"p4-004","level":1,"topic":"가구점 할인 광고","talk_type":"광고","voice":"male","script":"Are you moving into a new home or office? Then come to Hudson Furniture! This month only, all desks and chairs are thirty percent off. We have hundreds of styles for every room. Our friendly staff will help you find the right furniture for your space. And if you spend more than five hundred dollars, we'll deliver your furniture for free. Hudson Furniture is on Main Street, next to the city library. We're open every day from ten a.m. to eight p.m. Visit us today and make your new place feel like home!","graphic":null,"questions":[{"q":"What kind of business is being advertised?","choices":["A moving company","A furniture store","A real estate office","A library"],"answer":1,"type":"주제·목적","explanation":"\"come to Hudson Furniture!\"와 책상·의자 할인 내용으로 보아 가구점 광고다. 이사(moving)와 도서관(library)은 광고 속 단어를 이용한 오답이다."},{"q":"What is offered this month?","choices":["Free installation of all furniture","A gift card","Longer business hours","Discounts on certain items"],"answer":3,"type":"세부 사항","explanation":"화자가 \"This month only, all desks and chairs are thirty percent off.\"라고 했으므로 일부 품목(책상과 의자) 할인이 제공된다."},{"q":"How can customers get free delivery?","choices":["By shopping on weekdays","By ordering online before the end of the month","By living near the library","By spending a certain amount"],"answer":3,"type":"세부 사항","explanation":"화자가 \"if you spend more than five hundred dollars, we'll deliver your furniture for free\"라고 했으므로 일정 금액 이상 구매하면 무료 배달이다."}],"translation":"새집이나 새 사무실로 이사하시나요? 그렇다면 허드슨 가구로 오세요! 이번 달에만 모든 책상과 의자가 30퍼센트 할인됩니다. 모든 방에 맞는 수백 가지 스타일이 있습니다. 친절한 직원이 여러분의 공간에 맞는 가구를 찾도록 도와드립니다. 그리고 500달러 넘게 구매하시면 가구를 무료로 배달해 드립니다. 허드슨 가구는 메인 가, 시립 도서관 옆에 있습니다. 매일 오전 10시부터 오후 8시까지 영업합니다. 오늘 방문하셔서 새 공간을 내 집처럼 만드세요!","part":4},{"id":"p4-005","level":2,"topic":"라디오 교통 정보","talk_type":"방송·뉴스","voice":"female","script":"Good afternoon, this is Carla Diaz with your WKRT traffic update. If you're driving downtown this afternoon, expect delays on Harbor Bridge. One lane has been closed for repairs, and traffic is moving very slowly. The work is expected to continue until six p.m. Drivers heading to the airport should take Route 9 instead. It may be a little longer, but traffic there is moving smoothly right now. Also, remember that the city marathon is this Sunday, so several streets near Central Park will be closed from six a.m. to two p.m. Stay tuned for the weather report after this short break.","graphic":null,"questions":[{"q":"What is causing delays on Harbor Bridge?","choices":["An accident","Bad weather","Repair work","A marathon"],"answer":2,"type":"세부 사항","explanation":"화자가 \"One lane has been closed for repairs\"라고 했으므로 보수 공사 때문이다. 마라톤은 일요일 센트럴 파크 근처 도로 통제의 이유다."},{"q":"What does the speaker recommend for people going to the airport?","choices":["Leaving before six","Crossing Harbor Bridge","Taking a train from the downtown station","Taking a different road"],"answer":3,"type":"요청·제안","explanation":"화자가 \"Drivers heading to the airport should take Route 9 instead.\"라고 했으므로 다른 도로를 이용하라는 권고다. 6시는 공사가 끝나는 시각이다."},{"q":"What will listeners hear after the break?","choices":["A traffic update","An interview with a runner","A weather forecast","News about the airport"],"answer":2,"type":"다음 할 일","explanation":"화자가 마지막에 \"Stay tuned for the weather report after this short break.\"라고 했으므로 날씨 예보가 이어진다."}],"translation":"안녕하세요, WKRT 교통 정보의 칼라 디아스입니다. 오늘 오후 시내로 운전하실 분은 하버 브리지에서 지체를 예상하셔야 합니다. 보수 공사로 차로 하나가 폐쇄되어 차량이 매우 느리게 움직이고 있습니다. 공사는 오후 6시까지 계속될 예정입니다. 공항으로 가시는 운전자분들은 대신 9번 도로를 이용하세요. 조금 더 멀 수 있지만 지금은 그쪽 교통이 원활합니다. 또한 이번 일요일에 시 마라톤이 열려 센트럴 파크 근처 여러 도로가 오전 6시부터 오후 2시까지 통제된다는 점을 기억하세요. 잠시 광고 후 날씨 정보가 이어지니 채널 고정해 주세요.","part":4},{"id":"p4-006","level":2,"topic":"창호 교체 견적 회신","talk_type":"전화 메시지","voice":"male","script":"Hi, Ms. Thompson. This is Victor from Clearview Windows, returning your call about replacing the windows in your office. I've looked at the measurements you sent, and I can give you a price estimate by the end of this week. You mentioned you'd like the work done before the end of the month. Well, we have a lot of jobs right now. But I had a customer cancel yesterday, so we could start on the twenty-second. The whole job should take about three days. Please call me back at 555-0198 to confirm, and I'll hold that date for you until Friday.","graphic":null,"questions":[{"q":"Who most likely is the speaker?","choices":["An office manager at Ms. Thompson's company","An employee of a window company","A real estate agent","A building inspector"],"answer":1,"type":"화자 정보(직업·장소)","explanation":"화자가 \"This is Victor from Clearview Windows\"라고 하며 창문 교체 견적과 작업 일정을 안내하므로 창호 업체 직원이다. 사무실(office)은 청자의 공간이다."},{"q":"Why does the speaker say, \"Well, we have a lot of jobs right now\"?","choices":["To explain why prices have gone up","To ask the listener to recommend his company","To indicate that scheduling could be difficult","To announce that he is hiring workers"],"answer":2,"type":"의도 파악","explanation":"청자가 월말 전 작업을 원한다고 한 말에 이어 이 말을 하고, 바로 \"But I had a customer cancel yesterday\"라며 가능한 날짜를 제시한다. 원래는 일정을 맞추기 어렵다는 뜻이다."},{"q":"What does the speaker ask the listener to do?","choices":["Send some measurements again by e-mail","Cancel an order","Visit his office","Confirm a start date by phone"],"answer":3,"type":"요청·제안","explanation":"화자가 \"Please call me back at 555-0198 to confirm\"이라고 했으므로 전화로 시작 날짜를 확정해 달라는 요청이다. 치수는 이미 보냈다."}],"translation":"안녕하세요, 톰슨 씨. 클리어뷰 윈도우의 빅터입니다. 사무실 창문 교체 건으로 주신 전화에 회신드립니다. 보내 주신 치수를 검토했고, 이번 주말까지 가격 견적을 드릴 수 있습니다. 월말 전에 작업이 끝나길 원하신다고 하셨죠. 그런데 지금 저희가 일이 아주 많습니다. 하지만 어제 한 고객이 취소를 해서 22일에 시작할 수 있습니다. 전체 작업은 3일 정도 걸릴 겁니다. 555-0198로 전화 주셔서 확정해 주시면 금요일까지 그 날짜를 잡아 두겠습니다.","part":4},{"id":"p4-007","level":2,"topic":"기차 승강장 변경 안내","talk_type":"안내 방송","voice":"female","script":"Attention, passengers. This is an announcement for passengers traveling to Easton. Because of a signal problem, the train to Easton will now leave from platform eight, not from the platform shown on the departure board. The departure time has not changed. Please be careful when going to platform eight, as the stairs are being repaired. Please use the elevator near the ticket office instead. Also, passengers traveling to Riverside should note that there is no café car on today's train. Snacks and drinks can be bought at the shop next to platform one. We're sorry for any inconvenience.","graphic":{"title":"Departures — Central Station","rows":[["Train","Destination","Platform","Departs"],["No. 204","Brookfield","3","10:15"],["No. 318","Easton","5","10:30"],["No. 422","Millbrook","2","10:45"],["No. 506","Riverside","7","11:00"]]},"questions":[{"q":"Why has a platform been changed?","choices":["Because some stairs are being repaired","Because of a technical issue","Because a train is running late","Because of bad weather"],"answer":1,"type":"세부 사항","explanation":"화자가 \"Because of a signal problem, the train to Easton will now leave from platform eight\"라고 했으므로 신호 문제, 즉 기술적 문제 때문이다. 계단 보수는 승강장으로 가는 길에 관한 주의 사항이다."},{"q":"Look at the graphic. What time will the train at the new platform leave?","choices":["At 10:15","At 10:45","At 11:00","At 10:30"],"answer":3,"type":"시각 자료 연계","explanation":"승강장이 8번으로 바뀐 열차는 이스턴행이고 \"The departure time has not changed.\"라고 했다. 표에서 이스턴행 열차는 10:30에 출발한다."},{"q":"What does the speaker suggest passengers traveling to Riverside do?","choices":["Use the café car","Buy refreshments at a shop","Take the elevator","Board at platform one"],"answer":1,"type":"요청·제안","explanation":"리버사이드행 열차에 식당칸이 없다고 하면서 \"Snacks and drinks can be bought at the shop next to platform one.\"이라고 했으므로 매점에서 먹을 것을 사라는 것이다. 1번 승강장은 매점 위치일 뿐 탑승 장소가 아니다."}],"translation":"승객 여러분께 알려 드립니다. 이스턴으로 가시는 승객 여러분을 위한 안내입니다. 신호 문제로 인해 이스턴행 열차는 출발 안내판에 표시된 승강장이 아니라 8번 승강장에서 출발합니다. 출발 시각은 변경되지 않았습니다. 계단이 보수 중이니 8번 승강장으로 가실 때 주의해 주십시오. 대신 매표소 근처 엘리베이터를 이용해 주십시오. 또한 리버사이드로 가시는 승객께서는 오늘 열차에 식당칸이 없다는 점에 유의해 주십시오. 간식과 음료는 1번 승강장 옆 매점에서 구입하실 수 있습니다. 불편을 드려 죄송합니다.","part":4},{"id":"p4-008","level":2,"topic":"주스 공장 견학","talk_type":"관광·견학 안내","voice":"male","script":"Welcome to the Sunny Farms juice factory. My name is Leo, and I'll be your guide today. Our tour takes about an hour. First, we'll see where the fruit arrives from local farms and gets washed. Then we'll walk through the area where the juice is made and put into bottles. Please stay behind the yellow lines at all times, because the machines move very quickly. Also, photos are not allowed inside the production area. At the end of the tour, you'll visit our tasting room, where you can try five different juices for free. Now, please put on these hairnets and follow me.","graphic":null,"questions":[{"q":"Where are the listeners?","choices":["At a beverage factory","On a farm that grows fruit","At a supermarket","At a restaurant"],"answer":0,"type":"화자 정보(직업·장소)","explanation":"\"Welcome to the Sunny Farms juice factory.\"라고 했으므로 음료(주스) 공장이다. 농장(farms)은 과일이 오는 곳이고 회사 이름에도 들어 있어 함정이다."},{"q":"What are listeners told not to do?","choices":["Touch the fruit coming from the farms","Take pictures in a certain area","Drink the juice","Talk to the workers"],"answer":1,"type":"세부 사항","explanation":"화자가 \"photos are not allowed inside the production area\"라고 했으므로 특정 구역에서 사진을 찍으면 안 된다. 주스는 마지막에 시음할 수 있다."},{"q":"What will listeners do at the end of the tour?","choices":["Wash some fruit","Buy some bottles","Sample some products","Meet local farmers who supply fruit"],"answer":2,"type":"다음 할 일","explanation":"화자가 \"At the end of the tour, you'll visit our tasting room, where you can try five different juices for free.\"라고 했으므로 제품을 시음할 것이다. try를 sample로 바꿔 표현했다."}],"translation":"서니 팜스 주스 공장에 오신 것을 환영합니다. 저는 레오이고 오늘 여러분의 가이드입니다. 견학은 약 한 시간 걸립니다. 먼저 지역 농장에서 과일이 도착해 세척되는 곳을 보겠습니다. 그다음 주스가 만들어지고 병에 담기는 구역을 걸어서 지나갑니다. 기계가 매우 빠르게 움직이므로 항상 노란 선 뒤에 계셔 주세요. 또한 생산 구역 안에서는 사진 촬영이 허용되지 않습니다. 견학이 끝나면 시음실에 가서 다섯 가지 주스를 무료로 맛보실 수 있습니다. 이제 이 머리망을 쓰시고 저를 따라오세요.","part":4},{"id":"p4-009","level":3,"topic":"퇴임 축하 연설","talk_type":"연설·소개","voice":"female","script":"Good evening, everyone, and thank you for coming to celebrate Robert Kim's retirement. Robert joined Parker Engineering thirty-two years ago as a junior designer, and he went on to lead some of our most important projects, including the Riverside Bridge, which won a national design award. But what most of us will remember about Robert is his patience as a mentor. Many of the engineers in this room, including me, learned the job by working alongside him. Robert has told me he plans to spend his retirement traveling and, believe it or not, taking painting classes. Before we eat, Robert would like to say a few words. So please join me in welcoming him to the stage.","graphic":null,"questions":[{"q":"What is the purpose of the event?","choices":["To celebrate a design award","To welcome new engineers","To honor an employee who is leaving","To open the new Riverside Bridge to traffic"],"answer":2,"type":"주제·목적","explanation":"화자가 \"thank you for coming to celebrate Robert Kim's retirement\"라고 했으므로 퇴임하는 직원을 기리는 자리다. 디자인상은 과거 프로젝트의 성과로 언급되었을 뿐이다."},{"q":"According to the speaker, what do many people value about Robert?","choices":["His painting skills","His guidance of colleagues","His travel stories","His sense of humor"],"answer":1,"type":"세부 사항","explanation":"화자가 \"what most of us will remember about Robert is his patience as a mentor\"라고 하며 많은 엔지니어가 그에게서 일을 배웠다고 했다. 그림은 은퇴 후 배울 계획이다."},{"q":"What will most likely happen next?","choices":["Robert will give a speech.","A meal will be served.","An award will be presented.","A painting will be displayed."],"answer":0,"type":"다음 할 일","explanation":"화자가 \"Before we eat, Robert would like to say a few words.\"라며 그를 무대로 부르므로 다음은 로버트의 연설이다. 식사는 그 뒤에 한다."}],"translation":"안녕하세요, 여러분. 로버트 김의 퇴임을 축하하러 와 주셔서 감사합니다. 로버트는 32년 전 파커 엔지니어링에 신입 설계자로 입사해, 전국 디자인상을 받은 리버사이드 다리를 비롯해 우리 회사의 가장 중요한 프로젝트 여러 개를 이끌었습니다. 하지만 우리 대부분이 로버트에 대해 기억할 것은 멘토로서 보여 준 인내심입니다. 저를 포함해 이 자리에 있는 많은 엔지니어가 그와 함께 일하며 일을 배웠습니다. 로버트는 퇴임 후 여행을 하고, 믿기 어려우시겠지만 그림 수업을 들을 계획이라고 합니다. 식사하기 전에 로버트가 몇 마디 하고 싶어 합니다. 함께 박수로 그를 무대에 맞이해 주십시오.","part":4},{"id":"p4-010","level":3,"topic":"고객 설문 결과 회의","talk_type":"회의 발췌","voice":"male","script":"OK, let's get started. I want to share the results of the customer survey we ran last month. Overall, customers are happy with our products. Eighty-five percent rated them good or excellent. However, a lot of people said it was hard to reach our support team by phone. The average wait time was over twelve minutes. Now, I know what you're thinking. We just hired three new support staff in January. But they're still in training, and they won't be answering calls until April. So for now, I'd like us to try something different. Starting next week, we'll add a live chat option to our Web site. Janet, could you work with the Web team to set that up?","graphic":null,"questions":[{"q":"What is the main topic of the meeting?","choices":["Training for new employees","A Web site redesign","Feedback from customers","The hiring of a manager"],"answer":2,"type":"주제·목적","explanation":"화자가 \"I want to share the results of the customer survey we ran last month.\"라고 했으므로 고객 의견(설문 결과)이 주제다. 신입 직원 교육은 세부 내용으로 잠깐 언급된다."},{"q":"What does the speaker mean when he says, \"Now, I know what you're thinking\"?","choices":["He wants listeners to share their ideas.","He is surprised by the survey results.","He expects listeners to raise a possible objection.","He believes the wait time is acceptable."],"answer":2,"type":"의도 파악","explanation":"이 말 바로 뒤에 \"We just hired three new support staff in January. But they're still in training\"이라고 한다. 청자들이 '직원을 이미 뽑지 않았느냐'고 반문할 것을 예상하고 먼저 답하는 것이다."},{"q":"What is Janet asked to do?","choices":["Train new support staff","Help launch an online service","Conduct another survey","Answer customer calls"],"answer":1,"type":"요청·제안","explanation":"화자가 \"Janet, could you work with the Web team to set that up?\"이라고 했고 that은 웹사이트 실시간 채팅이므로 온라인 서비스 도입을 도와 달라는 것이다."}],"translation":"자, 시작합시다. 지난달 실시한 고객 설문 결과를 공유하려고 합니다. 전반적으로 고객들은 우리 제품에 만족합니다. 85퍼센트가 좋음 또는 매우 좋음으로 평가했습니다. 하지만 많은 사람이 전화로 지원팀과 연결하기 어렵다고 했습니다. 평균 대기 시간이 12분이 넘었습니다. 자, 여러분이 무슨 생각을 하는지 압니다. 1월에 지원 직원을 세 명 새로 뽑았죠. 하지만 그들은 아직 교육 중이고 4월이 되어야 전화를 받을 수 있습니다. 그래서 당분간은 다른 방법을 시도해 보려고 합니다. 다음 주부터 웹사이트에 실시간 채팅 기능을 추가하겠습니다. 재닛, 웹팀과 함께 그걸 준비해 줄 수 있나요?","part":4},{"id":"p4-011","level":3,"topic":"피트니스 센터 개점 광고","talk_type":"광고","voice":"female","script":"Looking to get in shape this spring? Summit Fitness has just opened its newest location on Cedar Avenue, and to celebrate, we're offering something special. Sign up for any membership plan before April thirtieth, and your first month is completely free. Our new location features the latest exercise equipment, over forty group classes each week, and an indoor swimming pool. And for a limited time, anyone who signs up for a plan with pool access will also get three free sessions with a personal trainer. Our trainers will help you set goals and create a program that works for you. Stop by for a tour, or visit summitfitness.com to learn more.","graphic":{"title":"Summit Fitness — Membership Plans","rows":[["Plan","Monthly Fee","Includes"],["Basic","$30","Gym access"],["Plus","$45","Gym + group classes"],["Premium","$60","Gym + classes + pool"],["Family","$90","Premium plan for up to 4 people"]]},"questions":[{"q":"What is Summit Fitness celebrating?","choices":["The opening of a new branch","A company anniversary","A swimming competition","A trainer's award"],"answer":0,"type":"주제·목적","explanation":"화자가 \"Summit Fitness has just opened its newest location on Cedar Avenue, and to celebrate\"라고 했으므로 새 지점 개점을 기념하는 것이다. location을 branch로 바꿔 표현했다."},{"q":"What will customers who join before April 30 receive?","choices":["A free T-shirt","A discount on equipment","Free parking","One month at no cost"],"answer":3,"type":"세부 사항","explanation":"화자가 \"Sign up for any membership plan before April thirtieth, and your first month is completely free.\"라고 했으므로 한 달 무료다."},{"q":"Look at the graphic. What is the lowest monthly fee for a plan that includes the free trainer sessions?","choices":["$30","$45","$60","$90"],"answer":2,"type":"시각 자료 연계","explanation":"트레이너 무료 세션은 \"a plan with pool access\"에 가입하는 사람에게 준다. 표에서 수영장이 포함된 플랜은 Premium($60)과 Family($90)이므로 가장 낮은 월 요금은 $60이다."}],"translation":"이번 봄에 몸매를 가꾸고 싶으신가요? 서밋 피트니스가 시더 가에 최신 지점을 막 열었고, 이를 기념해 특별한 혜택을 드립니다. 4월 30일 전에 어떤 회원권이든 가입하시면 첫 달이 완전히 무료입니다. 새 지점에는 최신 운동 기구, 매주 40개가 넘는 그룹 수업, 그리고 실내 수영장이 있습니다. 그리고 한정 기간 동안 수영장 이용이 포함된 회원권에 가입하시는 분은 누구나 개인 트레이너와의 무료 세션 3회도 받으십니다. 저희 트레이너가 목표를 세우고 여러분에게 맞는 프로그램을 짜 드립니다. 들러서 둘러보시거나 summitfitness.com에서 자세히 알아보세요.","part":4},{"id":"p4-012","level":3,"topic":"배터리 공장 신설 지역 뉴스","talk_type":"방송·뉴스","voice":"male","script":"In local business news, Northfield Electronics announced this morning that it will build a new manufacturing plant just outside the city. The company, which makes batteries for electric vehicles, says the plant will create about six hundred jobs when it opens in two years. Mayor Linda Hayes welcomed the news, saying it would bring much-needed investment to the area. However, some residents living near the site have raised concerns about increased truck traffic on local roads. In response, the company says it will build a new access road connecting the plant directly to the highway. A public meeting to discuss the project will be held at City Hall next Thursday evening. Residents are encouraged to attend and share their opinions.","graphic":null,"questions":[{"q":"What does Northfield Electronics produce?","choices":["Components for vehicles","Home appliances for kitchens","Highway signs","Solar panels"],"answer":0,"type":"세부 사항","explanation":"\"The company, which makes batteries for electric vehicles\"라고 했으므로 차량용 부품을 만든다. batteries for electric vehicles를 components for vehicles로 바꿔 표현했다. 고속도로(highway)는 진입로 이야기에 나온 단어다."},{"q":"What concern have some residents expressed?","choices":["A loss of local jobs","Higher property taxes","More heavy vehicles on local streets","Pollution from the plant"],"answer":2,"type":"세부 사항","explanation":"\"some residents ... have raised concerns about increased truck traffic on local roads\"라고 했으므로 대형 차량 통행 증가가 우려 사항이다. 일자리는 오히려 600개가 생긴다고 했다."},{"q":"What will happen next Thursday?","choices":["The plant will open.","The mayor will visit the site.","A new access road will be completed and opened.","A community meeting will take place."],"answer":3,"type":"세부 사항","explanation":"\"A public meeting to discuss the project will be held at City Hall next Thursday evening.\"이라고 했으므로 주민 회의가 열린다. 공장은 2년 후에 문을 연다."}],"translation":"지역 경제 소식입니다. 노스필드 일렉트로닉스는 오늘 아침 시 외곽에 새 제조 공장을 짓겠다고 발표했습니다. 전기차용 배터리를 만드는 이 회사는 2년 후 공장이 문을 열면 약 600개의 일자리가 생길 것이라고 밝혔습니다. 린다 헤이스 시장은 이 소식을 환영하며, 지역에 꼭 필요한 투자를 가져올 것이라고 말했습니다. 그러나 부지 근처에 사는 일부 주민들은 지역 도로의 트럭 통행 증가에 대한 우려를 제기했습니다. 이에 대해 회사는 공장과 고속도로를 바로 잇는 새 진입로를 건설하겠다고 밝혔습니다. 이 사업을 논의하는 공청회가 다음 주 목요일 저녁 시청에서 열립니다. 주민들의 참석과 의견 제시를 바랍니다.","part":4},{"id":"p4-013","level":4,"topic":"요리책 원고 분량 조정","talk_type":"전화 메시지","voice":"female","script":"Hi, Daniel, it's Monica Reyes from Lighthouse Publishing. I've just finished reading the revised draft of your cookbook, and I have to say, the new chapter on regional breads is a real highlight. The photos are stunning, too. There are a couple of things we still need to sort out, though. The marketing team would like the book to come in under three hundred pages to keep printing costs down, and right now we're sitting at three hundred and forty. I know, that's a lot of recipes to lose. I've marked a few that are pretty similar to one another, so that might be a good place to start. Could we set up a video call sometime this week to go over them? I'm free any afternoon except Wednesday.","graphic":null,"questions":[{"q":"Who most likely is the listener?","choices":["A writer","A photographer","A baker at a restaurant","A marketing director"],"answer":0,"type":"화자 정보(직업·장소)","explanation":"화자가 출판사 사람으로서 \"the revised draft of your cookbook\"이라고 했으므로 청자는 요리책 저자다. 빵(breads)과 사진(photos), 마케팅팀은 메시지 속 단어를 이용한 오답이다."},{"q":"Why does the speaker say, \"I know, that's a lot of recipes to lose\"?","choices":["To complain about the marketing team's decision to limit the page count","To show that she understands the listener's likely reaction","To praise a new chapter","To suggest adding more pages"],"answer":1,"type":"의도 파악","explanation":"340쪽을 300쪽 미만으로 줄여야 한다고 전한 직후 이 말을 하고, 비슷한 레시피를 표시해 두었다며 방법을 제시한다. 청자가 많은 분량을 빼는 것을 아쉬워할 것을 이해한다는 뜻이다."},{"q":"What does the speaker propose?","choices":["Holding an online meeting","Removing the bread chapter","Increasing the printing budget","Meeting on Wednesday"],"answer":0,"type":"요청·제안","explanation":"화자가 \"Could we set up a video call sometime this week to go over them?\"이라고 했으므로 온라인(화상) 회의를 제안한다. 수요일은 안 된다고 했다."}],"translation":"안녕하세요, 다니엘. 라이트하우스 출판사의 모니카 레예스예요. 방금 요리책 수정 원고를 다 읽었는데, 지역별 빵에 관한 새 장이 정말 압권이네요. 사진도 아주 멋져요. 그런데 아직 정리해야 할 것이 몇 가지 있어요. 마케팅팀은 인쇄 비용을 줄이기 위해 책을 300쪽 미만으로 만들고 싶어 하는데, 지금은 340쪽이에요. 알아요, 빼야 할 레시피가 많죠. 서로 꽤 비슷한 레시피 몇 개에 표시를 해 뒀으니 거기서부터 시작하면 좋을 것 같아요. 이번 주 중에 화상 통화로 함께 검토할 수 있을까요? 저는 수요일을 빼고 오후에는 언제든 괜찮아요.","part":4},{"id":"p4-014","level":4,"topic":"기조 강연자 소개","talk_type":"연설·소개","voice":"male","script":"Welcome back from lunch, everyone. I hope you enjoyed the meal. It's my pleasure to introduce our afternoon keynote speaker, Dr. Samira Okafor. Dr. Okafor is the head of research at GreenLeaf Logistics, where she's spent the last decade finding ways to cut fuel use across the company's fleet of delivery trucks. Her team's route-planning software has reduced the company's fuel costs by nearly a quarter, and it's now being licensed to shipping firms around the world. Today she'll be talking about how small, data-driven changes can add up to major savings. After her talk, she'll be signing copies of her new book at the registration table, where a limited number of copies are available for purchase. Please give a warm welcome to Dr. Okafor.","graphic":null,"questions":[{"q":"What is the purpose of the talk?","choices":["To introduce a speaker","To describe a lunch menu","To explain a registration process","To advertise a shipping company"],"answer":0,"type":"주제·목적","explanation":"화자가 \"It's my pleasure to introduce our afternoon keynote speaker, Dr. Samira Okafor.\"라고 했으므로 강연자 소개가 목적이다. 점심(lunch)과 등록(registration)은 담화 속 단어를 이용한 오답이다."},{"q":"What has Dr. Okafor's team achieved?","choices":["It designed a new delivery truck.","It opened offices around the world.","It reduced shipping prices for customers.","It greatly lowered fuel expenses."],"answer":3,"type":"세부 사항","explanation":"\"Her team's route-planning software has reduced the company's fuel costs by nearly a quarter\"라고 했으므로 연료비를 크게 줄였다. 전 세계(around the world)는 소프트웨어 라이선스를 받는 곳이다."},{"q":"According to the speaker, what can listeners do after the talk?","choices":["Get a book signed","Sign up for a workshop","Try some software","Have lunch with the speaker"],"answer":0,"type":"세부 사항","explanation":"화자가 \"After her talk, she'll be signing copies of her new book at the registration table\"이라고 했으므로 책에 사인을 받을 수 있다."}],"translation":"점심 식사 잘하고 오셨습니까, 여러분. 식사가 즐거우셨길 바랍니다. 오후 기조 강연자 사미라 오카포르 박사님을 소개하게 되어 기쁩니다. 오카포르 박사님은 그린리프 로지스틱스의 연구 책임자로, 지난 10년 동안 회사 배송 트럭 전체의 연료 사용을 줄이는 방법을 찾아 왔습니다. 박사님 팀의 경로 계획 소프트웨어는 회사의 연료비를 거의 4분의 1이나 줄였고, 지금은 전 세계 운송 회사에 라이선스로 제공되고 있습니다. 오늘 박사님은 데이터에 기반한 작은 변화가 어떻게 큰 절감으로 이어질 수 있는지 이야기하실 겁니다. 강연 후에는 등록 테이블에서 새 책에 사인을 해 주실 예정이며, 그곳에서 한정 수량의 책을 구입하실 수 있습니다. 오카포르 박사님을 뜨겁게 환영해 주십시오.","part":4},{"id":"p4-015","level":4,"topic":"미술관 하이라이트 투어","talk_type":"관광·견학 안내","voice":"female","script":"Good morning, and welcome to the Hartwell Museum of Art. I'm Julia, and I'll be leading today's highlights tour. We'll spend about ninety minutes together. We'll begin right here on the ground floor with our sculpture collection, and then work our way up. Please note that the gallery just above us is closed this week while we install a new exhibition, so we'll take the elevator straight past it. Don't worry, you won't miss out entirely. The museum shop sells postcards of all the major works from that collection. Our final stop will be the top floor, where our exhibit on coastal cities opened just last week. Along the way, feel free to ask questions, but please keep your voices down, as other visitors may be enjoying the art quietly. Now, if you'll follow me.","graphic":{"title":"Hartwell Museum of Art — Floor Guide","rows":[["Floor","Gallery"],["1","Modern Sculpture"],["2","European Paintings"],["3","Asian Ceramics"],["4","Photography"]]},"questions":[{"q":"Who most likely is the speaker?","choices":["A tour guide","A photographer","A museum shop clerk","A sculptor"],"answer":0,"type":"화자 정보(직업·장소)","explanation":"화자가 \"I'm Julia, and I'll be leading today's highlights tour.\"라고 했으므로 투어 가이드다. 기념품점(museum shop)과 조각(sculpture)은 담화 속 단어를 이용한 오답이다."},{"q":"Look at the graphic. Which gallery is closed this week?","choices":["Modern Sculpture","Asian Ceramics","Photography","European Paintings"],"answer":3,"type":"시각 자료 연계","explanation":"투어는 1층에서 시작하고 \"the gallery just above us is closed this week\"라고 했다. 1층 바로 위는 2층이므로 표에서 European Paintings 전시실이 닫혀 있다. 꼭대기 층(Photography)은 마지막으로 방문하는 곳이다."},{"q":"What are listeners asked to do?","choices":["Speak quietly","Buy some postcards","Take the stairs","Save their questions for the end"],"answer":0,"type":"요청·제안","explanation":"화자가 \"please keep your voices down\"이라고 했으므로 조용히 말해 달라는 요청이다. 질문은 도중에 편하게 하라고 했으므로 마지막까지 참으라는 것은 오답이다."}],"translation":"좋은 아침입니다. 하트웰 미술관에 오신 것을 환영합니다. 저는 줄리아이고 오늘 하이라이트 투어를 진행합니다. 약 90분 동안 함께하겠습니다. 바로 여기 1층의 조각 컬렉션에서 시작해 위층으로 올라가겠습니다. 바로 위층 전시실은 새 전시를 설치하느라 이번 주에 문을 닫았으니, 엘리베이터로 그 층은 곧장 지나가겠습니다. 걱정 마세요, 완전히 놓치시는 건 아닙니다. 미술관 기념품점에서 그 컬렉션의 주요 작품 엽서를 모두 판매합니다. 마지막 장소는 꼭대기 층으로, 바로 지난주에 해안 도시에 관한 전시가 열렸습니다. 도중에 편하게 질문하셔도 되지만, 다른 관람객들이 조용히 작품을 감상하고 있을 수 있으니 목소리를 낮춰 주세요. 자, 저를 따라오세요.","part":4},{"id":"p4-016","level":4,"topic":"이메일 시스템 전환 사내 방송","talk_type":"안내 방송","voice":"male","script":"Attention, all staff. This is Glen from the IT department. As many of you know, we'll be moving our e-mail system to a new platform this weekend. The switchover will begin at eight p.m. on Friday and should be finished by Sunday afternoon. During that time, you won't be able to send or receive messages, either on your computers or on your phones. If you're expecting anything urgent from a client, please let them know to call you instead. When you log in on Monday, you'll be asked to set up a new password, so give yourself a few extra minutes that morning. We've also put together a short video that walks you through the new features. You'll find it on the company intranet. If you run into any trouble, our help desk will open an hour early on Monday, at seven a.m.","graphic":null,"questions":[{"q":"What is the announcement mainly about?","choices":["A change to a communication system","A change in office hours over the weekend","A new mobile phone policy","An upcoming client visit"],"answer":0,"type":"주제·목적","explanation":"화자가 \"we'll be moving our e-mail system to a new platform this weekend\"라고 했으므로 이메일(소통 수단) 시스템 변경에 관한 방송이다."},{"q":"What are listeners advised to do?","choices":["Work from home over the weekend to finish reports","Tell clients to contact them by phone","Change their passwords on Friday","Turn off their computers"],"answer":1,"type":"요청·제안","explanation":"화자가 \"please let them know to call you instead\"라고 했으므로 고객에게 전화로 연락하라고 알리라는 것이다. 비밀번호는 금요일이 아니라 월요일에 설정한다."},{"q":"What will happen on Monday?","choices":["A training session will be held.","Technical support will be available earlier than usual.","Employees will receive new phones.","The intranet will be shut down."],"answer":1,"type":"세부 사항","explanation":"화자가 \"our help desk will open an hour early on Monday, at seven a.m.\"이라고 했으므로 월요일에는 기술 지원이 평소보다 일찍 시작된다. 교육은 영상으로 제공되며 따로 세션이 열리지 않는다."}],"translation":"전 직원 여러분께 알립니다. IT 부서의 글렌입니다. 많은 분이 아시다시피 이번 주말에 이메일 시스템을 새 플랫폼으로 옮깁니다. 전환 작업은 금요일 오후 8시에 시작해 일요일 오후까지 끝날 예정입니다. 그동안에는 컴퓨터나 휴대폰에서 메시지를 주고받을 수 없습니다. 고객에게서 급한 연락을 기다리고 계시다면 대신 전화하라고 알려 두세요. 월요일에 로그인하면 새 비밀번호를 설정하라는 안내가 나오니, 그날 아침에는 시간을 조금 넉넉히 잡으세요. 새 기능을 차근차근 안내하는 짧은 영상도 만들어 두었습니다. 회사 인트라넷에서 보실 수 있습니다. 문제가 생기면 월요일에는 헬프 데스크가 한 시간 이른 오전 7시에 문을 엽니다.","part":4},{"id":"p4-017","level":5,"topic":"브라질 진출 유통 파트너 협상","talk_type":"회의 발췌","voice":"female","script":"Before we wrap up, I want to circle back to the Brazil expansion. As you'll recall, the board gave us the green light last quarter, on the condition that we find a local distribution partner. Well, we've been in talks with three firms, and frankly, only one of them, Norte Distribution, has the warehouse capacity we'd need. The catch is that they're asking for an exclusive five-year contract. Now, I've negotiated a lot of these deals over the years. Five years isn't unheard of, but it'd tie our hands if the market takes off faster than we expect. So what I'd propose is a two-year exclusive with an option to renew, plus a clause that lets us bring in a second distributor if we hit certain sales targets. Raj, since you've worked with their CEO before, I'd like you to sound them out informally before we put anything in writing.","graphic":null,"questions":[{"q":"According to the speaker, what condition did the board set for the expansion?","choices":["Building a new warehouse","Appointing a new CEO","Reaching a sales target first","Finding a regional company to handle distribution"],"answer":3,"type":"세부 사항","explanation":"화자가 \"the board gave us the green light last quarter, on the condition that we find a local distribution partner\"라고 했으므로 현지 유통 파트너 확보가 조건이다. 매출 목표는 두 번째 유통업체 조항에 나오는 내용이다."},{"q":"Why does the speaker say, \"Now, I've negotiated a lot of these deals over the years\"?","choices":["To show that her opinion is based on experience","To indicate that she will retire soon after the deal","To explain why the talks took so long","To suggest that someone else lead the talks"],"answer":0,"type":"의도 파악","explanation":"이 말 뒤에 5년 계약의 위험을 지적하고 2년 독점 계약이라는 대안을 제시한다. 자신의 판단이 오랜 협상 경험에 근거한다는 점을 내세우려는 것이다."},{"q":"What is Raj asked to do?","choices":["Draft a written contract","Inspect a warehouse in Brazil","Informally find out how a company might respond","Present sales targets for Brazil to the board next week"],"answer":2,"type":"요청·제안","explanation":"화자가 \"I'd like you to sound them out informally before we put anything in writing\"이라고 했다. sound out은 '의향을 떠보다'라는 뜻이므로 상대 회사의 반응을 비공식적으로 알아보라는 것이다. 문서 작성은 그 이후의 일이다."}],"translation":"마무리하기 전에 브라질 진출 건을 다시 짚고 싶습니다. 기억하시겠지만 이사회는 지난 분기에 현지 유통 파트너를 찾는다는 조건으로 승인해 주었습니다. 그런데 세 회사와 협의해 왔는데, 솔직히 우리에게 필요한 창고 용량을 갖춘 곳은 노르테 디스트리뷰션 한 곳뿐입니다. 문제는 그들이 5년 독점 계약을 요구한다는 겁니다. 자, 저는 수년간 이런 계약을 많이 협상해 봤습니다. 5년이 드문 일은 아니지만, 시장이 예상보다 빨리 성장하면 우리 손발이 묶이게 됩니다. 그래서 제가 제안하려는 것은 갱신 옵션이 있는 2년 독점 계약에, 일정 매출 목표를 달성하면 두 번째 유통업체를 들일 수 있는 조항을 더하는 것입니다. 라지, 그쪽 CEO와 일해 본 적이 있으니 문서로 무언가를 내밀기 전에 비공식적으로 그쪽 의향을 떠봐 주면 좋겠어요.","part":4},{"id":"p4-018","level":5,"topic":"커피 원두 가격 급등 뉴스","talk_type":"방송·뉴스","voice":"male","script":"And now for the business report. Coffee prices hit a twelve-year high this week after an unusually dry season in several major growing regions cut harvests by as much as thirty percent. Analysts say shoppers can expect to see the effect on supermarket shelves within the next two months. Independent cafés are expected to feel the pinch most, since they lack the purchasing power of large chains, which often lock in prices through long-term contracts. Some café owners we spoke to say they're considering smaller cup sizes rather than raising prices outright, while others are turning to blends that mix in less expensive beans. Meanwhile, tea importers are reporting a spike in orders, as some consumers appear to be switching drinks altogether. We'll have more on this story, including an interview with a coffee farmer in Colombia, after the break.","graphic":null,"questions":[{"q":"What caused coffee prices to rise?","choices":["Transportation costs increased across the region.","Demand grew in new markets.","Weather conditions reduced production.","Large chains bought more beans."],"answer":2,"type":"세부 사항","explanation":"\"an unusually dry season in several major growing regions cut harvests by as much as thirty percent\"라고 했으므로 날씨(건기) 때문에 생산량이 줄었다. 대형 체인은 장기 계약으로 가격을 고정한다는 맥락에서 나왔다."},{"q":"According to the speaker, why will independent cafés be especially affected?","choices":["They have less buying power than big companies.","They use more expensive beans than large chains.","They sell more tea than coffee.","They are located in growing regions."],"answer":0,"type":"세부 사항","explanation":"\"since they lack the purchasing power of large chains\"라고 했으므로 대형 업체보다 구매력이 약하기 때문이다. purchasing power를 buying power로 바꿔 표현했다."},{"q":"What will listeners hear after the break?","choices":["A report on tea prices in Asian markets","An advertisement for a café","The weather forecast","A conversation with a grower"],"answer":3,"type":"다음 할 일","explanation":"\"including an interview with a coffee farmer in Colombia, after the break\"라고 했으므로 커피 재배 농부와의 인터뷰를 듣게 된다. farmer를 grower로 바꿔 표현했다."}],"translation":"이어서 경제 소식입니다. 주요 재배 지역 여러 곳에 이례적인 건기가 닥쳐 수확량이 최대 30퍼센트 줄면서, 이번 주 커피 가격이 12년 만에 최고치를 기록했습니다. 분석가들은 소비자들이 앞으로 두 달 안에 슈퍼마켓 진열대에서 그 영향을 보게 될 것이라고 말합니다. 개인 카페들이 가장 큰 타격을 받을 것으로 예상되는데, 장기 계약으로 가격을 고정하는 경우가 많은 대형 체인만큼의 구매력이 없기 때문입니다. 저희가 이야기를 나눈 일부 카페 주인들은 가격을 대놓고 올리기보다 컵 크기를 줄이는 것을 고려하고 있다고 했고, 다른 이들은 더 저렴한 원두를 섞은 블렌드로 바꾸고 있습니다. 한편 일부 소비자들이 아예 음료를 바꾸는 것으로 보이면서 차 수입업체들은 주문이 급증했다고 전합니다. 광고 후에 콜롬비아 커피 농부와의 인터뷰를 포함해 이 소식을 더 전해 드리겠습니다.","part":4},{"id":"p4-019","level":5,"topic":"행사장 규모 변경 안내 전화","talk_type":"전화 메시지","voice":"female","script":"Hi, Mr. Novak, this is Irene Walsh from the events office at the Lakeview Conference Hotel, calling about your sales training on June twelfth. I got your e-mail saying registrations have come in well above what you'd anticipated, congratulations, by the way, and that you're now expecting around a hundred and twenty people. Unfortunately, that's more than your current room can hold. I've checked availability, and the smallest room that would accommodate your group is open that day, so I've gone ahead and put a tentative hold on it. Just bear in mind that the rate is higher, so you may want to run it by your budget people. Also, a larger crowd means the catering order will need adjusting. Our kitchen needs final numbers no later than ten days before the event. Give me a call back at extension two fourteen once you've had a chance to look things over.","graphic":{"title":"Lakeview Conference Hotel — Event Rooms","rows":[["Room","Capacity","Daily Rate"],["Birch Room","40","$600"],["Maple Room","80","$950"],["Cedar Hall","150","$1,700"],["Grand Ballroom","300","$3,200"]]},"questions":[{"q":"Why is the speaker calling?","choices":["To cancel a reservation","To promote a catering service","To confirm a payment","To respond to an increase in attendance"],"answer":3,"type":"주제·목적","explanation":"화자가 등록 인원이 예상보다 많아져 120명을 예상한다는 이메일을 받았다며(\"registrations have come in well above what you'd anticipated\") 더 큰 방과 케이터링 조정을 안내하므로 참석 인원 증가에 대응하려는 전화다."},{"q":"Look at the graphic. What is the daily rate of the room the speaker has reserved?","choices":["$950","$3,200","$1,700","$600"],"answer":2,"type":"시각 자료 연계","explanation":"화자는 120명을 수용할 수 있는 가장 작은 방(\"the smallest room that would accommodate your group\")을 임시로 잡았다. 표에서 120명 이상 수용 가능한 방 중 가장 작은 것은 수용 인원 150명인 Cedar Hall이고 요금은 $1,700이다. 80명인 Maple Room은 인원이 부족하다."},{"q":"What does the speaker say about the catering order?","choices":["It has already been changed to a larger order.","Final numbers must be provided in advance.","It will cost less than before.","It must be canceled."],"answer":1,"type":"세부 사항","explanation":"화자가 \"Our kitchen needs final numbers no later than ten days before the event.\"라고 했으므로 최종 인원을 미리 알려야 한다. 아직 조정이 필요하다고 했을 뿐 이미 바뀐 것은 아니다."}],"translation":"안녕하세요, 노박 씨. 레이크뷰 컨퍼런스 호텔 행사팀의 아이린 월시입니다. 6월 12일 영업 교육 건으로 전화드렸어요. 등록 인원이 예상보다 훨씬 많아져서, 아 그건 그렇고 축하드려요, 이제 120명 정도를 예상하신다는 이메일을 받았습니다. 안타깝게도 지금 예약하신 방에는 그 인원이 다 들어가지 않아요. 확인해 보니 그 인원을 수용할 수 있는 가장 작은 방이 그날 비어 있어서, 먼저 임시로 잡아 두었습니다. 다만 요금이 더 높으니 예산 담당자분들과 상의해 보시는 게 좋겠어요. 또 인원이 늘면 케이터링 주문도 조정해야 합니다. 저희 주방은 늦어도 행사 열흘 전까지 최종 인원을 알아야 해요. 검토해 보신 후 내선 214번으로 전화 주세요.","part":4},{"id":"p4-020","level":5,"topic":"협업 소프트웨어 광고","talk_type":"광고","voice":"male","script":"Let's face it. Your team's project notes are scattered across e-mails, chat threads, and sticky notes on someone's monitor. Sound familiar? Then it's time to try TaskBridge. TaskBridge pulls every file, message, and deadline into one shared workspace, so nothing falls through the cracks. Its smart timeline even flags tasks that are at risk of running late, before they become a problem. Still skeptical? Over four thousand companies made the switch last year alone, and ninety percent of them renewed. Setting it up takes about fifteen minutes, and our import tool will bring over your existing files automatically. For a limited time, new customers get the full version free for sixty days, no credit card required. And if you sign up before the end of the month, we'll throw in a one-on-one onboarding session with one of our product specialists. Visit taskbridge.com and see what your team has been missing.","graphic":null,"questions":[{"q":"What problem does the speaker mention?","choices":["Employees miss too many team meetings every week.","Work information is spread across many places.","Computers are running slowly.","Office monitors are too small."],"answer":1,"type":"주제·목적","explanation":"화자가 \"Your team's project notes are scattered across e-mails, chat threads, and sticky notes\"라고 했으므로 업무 정보가 여러 곳에 흩어져 있는 것이 문제다. 모니터(monitor)는 메모지가 붙은 곳으로 나온 단어다."},{"q":"Why does the speaker say, \"Over four thousand companies made the switch last year alone\"?","choices":["To announce a price increase","To explain why setup takes about fifteen minutes","To thank long-time customers","To reassure listeners who may have doubts"],"answer":3,"type":"의도 파악","explanation":"바로 앞에서 \"Still skeptical?\"이라고 묻고 이 말을 한 뒤 90퍼센트가 갱신했다고 덧붙인다. 의심하는 청자에게 많은 회사가 쓰는 믿을 만한 제품이라고 안심시키려는 것이다."},{"q":"What is offered only to customers who sign up before the end of the month?","choices":["A personalized training session","A credit card discount","Automatic file backup","Sixty days of free service"],"answer":0,"type":"세부 사항","explanation":"화자가 \"if you sign up before the end of the month, we'll throw in a one-on-one onboarding session\"이라고 했으므로 일대일 맞춤 교육이 추가로 제공된다. 60일 무료는 이번 달 말과 관계없이 모든 신규 고객에게 주는 혜택이라 함정이다."}],"translation":"솔직히 인정합시다. 여러분 팀의 프로젝트 메모는 이메일, 채팅방, 누군가의 모니터에 붙은 메모지에 흩어져 있습니다. 익숙한 이야기인가요? 그렇다면 태스크브리지를 써 볼 때입니다. 태스크브리지는 모든 파일, 메시지, 마감일을 하나의 공유 작업 공간으로 모아 어떤 것도 놓치지 않게 합니다. 스마트 타임라인은 늦어질 위험이 있는 작업을 문제가 되기 전에 미리 표시해 주기까지 합니다. 아직도 의심스러우신가요? 작년 한 해에만 4천 개가 넘는 회사가 태스크브리지로 바꿨고, 그중 90퍼센트가 계약을 갱신했습니다. 설치는 15분 정도면 되고, 가져오기 도구가 기존 파일을 자동으로 옮겨 줍니다. 한정 기간 동안 신규 고객은 신용카드 없이 정식 버전을 60일간 무료로 이용할 수 있습니다. 그리고 이번 달 말 전에 가입하시면 제품 전문가와의 일대일 도입 교육을 덤으로 드립니다. taskbridge.com을 방문해 여러분 팀이 무엇을 놓치고 있었는지 확인하세요.","part":4},{"id":"p4-021","level":1,"topic":"폭설로 인한 서점 조기 폐점","talk_type":"안내 방송","voice":"female","script":"Attention, shoppers. Thank you for visiting Page Turner Books today. Because of the heavy snow, our store will close early today, at five o'clock instead of nine. We want our staff and customers to get home safely. Please bring your items to the front registers in the next thirty minutes. Our café on the second floor is already closed. If you ordered a book and planned to pick it up tonight, don't worry. You can pick it up tomorrow, and we will keep it for you for one week. We will open at the usual time tomorrow morning, at ten o'clock. Thank you, and please drive carefully.","graphic":null,"questions":[{"q":"Why will the store close early?","choices":["Because of a holiday","Because of the weather","Because of repair work","Because of a staff meeting"],"answer":1,"type":"세부 사항","explanation":"화자가 \"Because of the heavy snow, our store will close early today\"라고 했으므로 날씨 때문이다. heavy snow를 weather로 바꿔 표현했다."},{"q":"What is already closed?","choices":["A café","The parking lot","The second entrance","The front registers"],"answer":0,"type":"세부 사항","explanation":"화자가 \"Our café on the second floor is already closed.\"라고 했다. 계산대(registers)는 30분 안에 물건을 가져가라고 한 곳으로 아직 열려 있다."},{"q":"What time will the store open tomorrow?","choices":["At seven o'clock","At nine o'clock","At five o'clock","At ten o'clock"],"answer":3,"type":"세부 사항","explanation":"화자가 \"We will open at the usual time tomorrow morning, at ten o'clock.\"이라고 했다. 5시는 오늘 문을 닫는 시각, 9시는 원래 폐점 시각이다."}],"translation":"쇼핑객 여러분께 알려 드립니다. 오늘 페이지 터너 서점을 찾아 주셔서 감사합니다. 폭설 때문에 저희 매장은 오늘 9시가 아닌 5시에 일찍 문을 닫습니다. 직원과 고객 여러분이 안전하게 귀가하시길 바랍니다. 30분 안에 물건을 앞쪽 계산대로 가져와 주세요. 2층 카페는 이미 문을 닫았습니다. 책을 주문하시고 오늘 밤 찾아가실 계획이었다면 걱정하지 마세요. 내일 찾아가셔도 되며, 일주일 동안 보관해 드립니다. 내일 아침에는 평소대로 10시에 문을 엽니다. 감사합니다. 운전 조심하세요.","part":4},{"id":"p4-022","level":1,"topic":"주방 타일 공사 연기 음성 메시지","talk_type":"전화 메시지","voice":"male","script":"Hi, Ms. Brown. This is Jake from Bright Home Repairs. I'm calling about your kitchen floor. I'm sorry, but the tiles you chose did not arrive today. The store says they will come on Thursday. So we can't start the work tomorrow. Can we start on Friday morning at eight instead? The work will still take two days. Please call me back and let me know if Friday is OK for you. My number is 555-0148. Also, please move the small table out of the kitchen before we start. Thank you, and sorry again.","graphic":null,"questions":[{"q":"What is the message mainly about?","choices":["A delay in a repair job","A new kitchen design","A problem with a payment","A change in price"],"answer":0,"type":"주제·목적","explanation":"타일이 도착하지 않아 \"we can't start the work tomorrow\"라며 금요일로 미루자고 하므로 공사 연기에 관한 메시지다."},{"q":"What does the speaker want to know?","choices":["How big the kitchen is","When the store closes","Whether a new start date is OK","What color the tiles should be"],"answer":2,"type":"세부 사항","explanation":"화자가 \"let me know if Friday is OK for you\"라고 했으므로 새 시작일이 괜찮은지 알고 싶어 한다."},{"q":"What does the speaker ask the listener to do before the work?","choices":["Buy some tiles","Clean the kitchen floor thoroughly","Pay a deposit","Move a piece of furniture"],"answer":3,"type":"요청·제안","explanation":"화자가 \"please move the small table out of the kitchen before we start\"라고 했다. table을 a piece of furniture로 바꿔 표현했다. 타일은 이미 주문한 상태다."}],"translation":"안녕하세요, 브라운 씨. 브라이트 홈 리페어의 제이크입니다. 주방 바닥 건으로 전화드렸어요. 죄송하지만 고르신 타일이 오늘 도착하지 않았어요. 가게에서는 목요일에 온다고 하네요. 그래서 내일 공사를 시작할 수 없어요. 대신 금요일 아침 8시에 시작해도 될까요? 공사는 여전히 이틀 걸립니다. 다시 전화 주셔서 금요일이 괜찮은지 알려 주세요. 제 번호는 555-0148입니다. 그리고 시작하기 전에 작은 탁자를 주방 밖으로 옮겨 주세요. 감사합니다. 다시 한번 죄송합니다.","part":4},{"id":"p4-023","level":1,"topic":"주말 일기 예보와 음식 축제 날짜 변경","talk_type":"방송·뉴스","voice":"female","script":"Good evening. This is Amy Chen with your weather for the weekend. Tomorrow will be sunny and warm, a perfect day for a picnic. On Saturday, it will be cloudy, but there won't be any rain. Then on Sunday, rain will move in, and it will be cooler, so please take an umbrella with you. Many of you are planning to go to the Summer Food Fair at Lake Park. The fair was going to be on Sunday, but because of the rain, the organizers moved it to the day before. The good news is that the sun will come back on Monday. Stay with us. The evening news is next.","graphic":{"title":"Weekend Forecast","rows":[["Day","Weather","High"],["Friday","Sunny","24°C"],["Saturday","Cloudy","21°C"],["Sunday","Rainy","17°C"],["Monday","Sunny","22°C"]]},"questions":[{"q":"What does the speaker say about tomorrow?","choices":["It will be cloudy all day.","It will be a good day for a picnic.","It will be cold.","It will rain in the morning."],"answer":1,"type":"세부 사항","explanation":"화자가 \"Tomorrow will be sunny and warm, a perfect day for a picnic.\"이라고 했다. 흐린 날은 토요일, 비 오는 날은 일요일이다."},{"q":"Look at the graphic. What will the high temperature be on the day of the food fair?","choices":["17°C","24°C","21°C","22°C"],"answer":2,"type":"시각 자료 연계","explanation":"음식 축제는 원래 일요일이었지만 \"moved it to the day before\"라고 했으므로 토요일에 열린다. 표에서 토요일 최고 기온은 21도다. 17도는 원래 날짜였던 일요일 기온이다."},{"q":"What will listeners hear next?","choices":["A music program","The news","A traffic report","An interview"],"answer":1,"type":"다음 할 일","explanation":"화자가 마지막에 \"The evening news is next.\"라고 했으므로 다음은 저녁 뉴스다."}],"translation":"안녕하세요. 주말 날씨를 전해 드리는 에이미 첸입니다. 내일은 맑고 따뜻해서 소풍 가기에 완벽한 날이겠습니다. 토요일은 흐리겠지만 비는 오지 않겠습니다. 그리고 일요일에는 비가 들어오고 기온이 내려가니 우산을 꼭 챙기세요. 많은 분들이 레이크 공원의 여름 음식 축제에 가실 계획이실 텐데요. 축제는 일요일에 열릴 예정이었지만 비 때문에 주최 측이 하루 앞당겼습니다. 좋은 소식은 월요일에 다시 해가 나온다는 것입니다. 채널 고정해 주세요. 이어서 저녁 뉴스입니다.","part":4},{"id":"p4-024","level":1,"topic":"동네 빵집 개업 10주년 광고","talk_type":"광고","voice":"male","script":"Are you looking for fresh bread every morning? Come to Golden Oven Bakery on Main Street! We bake all of our bread right here in the store every day, starting at five a.m. We also have cakes, cookies, and sandwiches for lunch. This month, we are celebrating our tenth birthday. So, every customer gets a free cup of coffee with any purchase. And if you buy two loaves of bread, you get the third one free. Golden Oven Bakery is open from six in the morning until seven at night, every day except Monday. See you soon at Golden Oven Bakery!","graphic":null,"questions":[{"q":"What is being advertised?","choices":["A bakery","A restaurant","A coffee machine","A grocery store"],"answer":0,"type":"주제·목적","explanation":"화자가 \"Come to Golden Oven Bakery\"라며 매일 빵을 굽는다고 소개하므로 빵집 광고다. 커피는 무료로 주는 음료일 뿐이다."},{"q":"Why is the business having a special event?","choices":["It is closing soon.","It has a new owner.","It has moved to a new location.","It is celebrating an anniversary."],"answer":3,"type":"세부 사항","explanation":"화자가 \"we are celebrating our tenth birthday\"라고 했다. 가게의 열 번째 생일, 즉 10주년을 anniversary로 바꿔 표현했다."},{"q":"When is the business closed?","choices":["In the morning","On Sundays","On Mondays","On holidays"],"answer":2,"type":"세부 사항","explanation":"화자가 \"every day except Monday\"라고 했으므로 월요일에 쉰다."}],"translation":"매일 아침 갓 구운 빵을 찾고 계신가요? 메인 스트리트의 골든 오븐 베이커리로 오세요! 저희는 매일 새벽 5시부터 모든 빵을 바로 이 매장에서 굽습니다. 케이크와 쿠키, 점심용 샌드위치도 있습니다. 이번 달 저희는 개업 10주년을 맞았습니다. 그래서 무엇이든 구매하시는 모든 고객께 커피 한 잔을 무료로 드립니다. 그리고 빵 두 덩이를 사시면 세 번째는 무료입니다. 골든 오븐 베이커리는 월요일을 제외한 매일 아침 6시부터 저녁 7시까지 문을 엽니다. 골든 오븐 베이커리에서 곧 만나요!","part":4},{"id":"p4-025","level":1,"topic":"이메일 작성 워크숍 시작 안내","talk_type":"연설·소개","voice":"female","script":"Good morning, everyone, and welcome to today's workshop, Writing Better E-mails. My name is Laura Kim, and I work in the training department. Today's workshop will last three hours. First, we'll talk about how to write a clear subject line. Then, you will practice writing short e-mails in small groups. We'll take a fifteen-minute break at ten thirty. There's coffee and tea at the back of the room. Before we start, please turn off your phones or put them on silent. Now, let me introduce our speaker, Mr. Tom Baker. He has taught business writing for twenty years.","graphic":null,"questions":[{"q":"What is the topic of the workshop?","choices":["How to use a phone","How to give speeches","How to manage time","How to write e-mails"],"answer":3,"type":"주제·목적","explanation":"워크숍 제목이 \"Writing Better E-mails\"이고 제목 줄 쓰는 법과 짧은 이메일 쓰기 연습을 한다고 했으므로 이메일 작성법이다."},{"q":"What will happen at ten thirty?","choices":["Groups will be formed.","A break will start.","The workshop will end.","Lunch will be served."],"answer":1,"type":"세부 사항","explanation":"화자가 \"We'll take a fifteen-minute break at ten thirty.\"라고 했으므로 휴식이 시작된다. 커피와 차가 있다고 했을 뿐 점심 제공은 없다."},{"q":"What are listeners asked to do?","choices":["Silence their phones","Write down their names","Sit in small groups","Get some coffee"],"answer":0,"type":"요청·제안","explanation":"화자가 \"please turn off your phones or put them on silent\"라고 했으므로 휴대전화를 무음으로 해 달라는 요청이다."}],"translation":"좋은 아침입니다, 여러분. 오늘 워크숍 ‘더 나은 이메일 쓰기’에 오신 것을 환영합니다. 제 이름은 로라 김이고 교육부에서 일합니다. 오늘 워크숍은 세 시간 동안 진행됩니다. 먼저 명확한 제목 줄을 쓰는 법을 이야기하겠습니다. 그다음 소그룹으로 짧은 이메일 쓰기를 연습하시게 됩니다. 10시 30분에 15분간 휴식하겠습니다. 방 뒤쪽에 커피와 차가 있습니다. 시작하기 전에 휴대전화를 끄시거나 무음으로 해 주세요. 이제 오늘의 강사 톰 베이커 씨를 소개하겠습니다. 그는 20년 동안 비즈니스 글쓰기를 가르쳐 왔습니다.","part":4},{"id":"p4-026","level":1,"topic":"꽃 농장 견학","talk_type":"관광·견학 안내","voice":"male","script":"Hello, everyone, and welcome to Sunny Hill Flower Farm. I'm Ben, and I'll be your guide today. Our tour will take about one hour. First, we'll walk through the tulip fields. Right now, the tulips are in full bloom, so it's a great time to take pictures. After that, we'll visit our greenhouse, where we grow roses all year. Please don't pick any flowers during the tour. But at the end of the tour, each of you will get a small bunch of tulips to take home. Our gift shop is next to the parking lot. OK, please follow me.","graphic":null,"questions":[{"q":"Where is the tour taking place?","choices":["At a flower shop","At a city park","At a museum","At a farm"],"answer":3,"type":"화자 정보(직업·장소)","explanation":"화자가 \"welcome to Sunny Hill Flower Farm\"이라고 했으므로 농장이다. 꽃이 나온다고 꽃집을 고르면 안 된다."},{"q":"Where will listeners go after the tulip fields?","choices":["To a greenhouse","To a café","To a parking lot","To a gift shop"],"answer":0,"type":"세부 사항","explanation":"화자가 튤립 밭을 걸은 뒤 \"After that, we'll visit our greenhouse\"라고 했다. 기념품점은 주차장 옆에 있다고 위치만 안내했다."},{"q":"What will listeners receive at the end of the tour?","choices":["A photograph","A map","Some flowers","A discount coupon"],"answer":2,"type":"세부 사항","explanation":"화자가 \"each of you will get a small bunch of tulips to take home\"이라고 했으므로 꽃을 받는다. 투어 중에 꽃을 꺾지 말라는 말과 헷갈리지 않도록 한다."}],"translation":"안녕하세요, 여러분. 서니 힐 꽃 농장에 오신 것을 환영합니다. 저는 벤이고 오늘 여러분의 가이드입니다. 투어는 한 시간 정도 걸립니다. 먼저 튤립 밭을 걸어 보겠습니다. 지금 튤립이 활짝 피어 있어서 사진 찍기에 아주 좋은 때입니다. 그다음 일 년 내내 장미를 키우는 온실에 가 보겠습니다. 투어 중에는 꽃을 꺾지 말아 주세요. 대신 투어가 끝나면 모두 집에 가져가실 작은 튤립 다발을 받으실 겁니다. 기념품점은 주차장 옆에 있습니다. 자, 저를 따라오세요.","part":4},{"id":"p4-027","level":2,"topic":"출근길 라디오 교통 정보","talk_type":"방송·뉴스","voice":"male","script":"You're listening to WKRT Radio, and it's time for the morning traffic report. If you're driving downtown this morning, expect delays on Highway 9. A truck broke down in the right lane near the Pine Street exit, and traffic is backed up for about three kilometers. Tow trucks are on the way, but it could take an hour to clear. We suggest using Oak Avenue instead. Also, remember that the Central Bridge is closed all week for painting, so you'll need to take the Harbor Bridge. And if you're taking the train, good news: all trains are running on time. I'll be back with another update in twenty minutes.","graphic":null,"questions":[{"q":"What is causing the delay on Highway 9?","choices":["Road construction","A vehicle that stopped working","Bad weather","A parade"],"answer":1,"type":"세부 사항","explanation":"화자가 \"A truck broke down in the right lane\"이라고 했으므로 고장 난 차량 때문이다. broke down을 stopped working으로 바꿔 표현했다."},{"q":"What does the speaker suggest?","choices":["Leaving home later","Taking a different road","Using the Central Bridge","Taking the train"],"answer":1,"type":"요청·제안","explanation":"화자가 \"We suggest using Oak Avenue instead.\"라고 했으므로 다른 길로 가라는 제안이다. 기차가 정시 운행한다는 것은 정보일 뿐 권유가 아니며, 센트럴 다리는 폐쇄됐다."},{"q":"Why is the Central Bridge closed?","choices":["It is too crowded.","It is being repaired after an accident.","A truck is blocking it.","It is being painted."],"answer":3,"type":"세부 사항","explanation":"화자가 \"the Central Bridge is closed all week for painting\"이라고 했으므로 페인트칠 때문이다. 트럭은 9번 고속도로의 문제다."}],"translation":"WKRT 라디오를 듣고 계십니다. 아침 교통 정보 시간입니다. 오늘 아침 시내로 운전하신다면 9번 고속도로에서 지체를 예상하셔야 합니다. 파인 스트리트 출구 근처 오른쪽 차로에서 트럭 한 대가 고장 나 차량이 약 3킬로미터 밀려 있습니다. 견인차가 가고 있지만 정리되기까지 한 시간이 걸릴 수 있습니다. 대신 오크 애비뉴를 이용하시길 권합니다. 또한 센트럴 다리가 페인트 작업으로 이번 주 내내 폐쇄되니 하버 다리를 이용하셔야 한다는 점 기억하세요. 기차를 타신다면 좋은 소식이 있습니다. 모든 열차가 정시에 운행 중입니다. 20분 뒤에 새로운 소식으로 돌아오겠습니다.","part":4},{"id":"p4-028","level":2,"topic":"여객선 출발 지연과 탑승구 변경","talk_type":"안내 방송","voice":"female","script":"Good morning, passengers. This is an announcement for passengers traveling to Port Allen. Because of strong winds this morning, your ferry will leave thirty minutes later than scheduled. We're sorry for the inconvenience. Also, please note that boarding will now take place at Gate 1 instead of the gate shown on your ticket, since your usual gate is being cleaned. The ferry to Green Island will leave on time. While you wait, you can enjoy a free coffee at the café on the second floor. Just show your ticket. Thank you for your patience, and have a pleasant trip.","graphic":{"title":"Pier 3 Ferry Terminal — Departures","rows":[["Destination","Departure","Gate"],["Green Island","10:15","Gate 1"],["Bay City","10:45","Gate 2"],["Port Allen","11:20","Gate 3"],["Rock Harbor","11:50","Gate 4"]]},"questions":[{"q":"What has caused the delay?","choices":["Weather conditions","Cleaning of the ferry","A mechanical problem","A late crew member"],"answer":0,"type":"세부 사항","explanation":"화자가 \"Because of strong winds this morning\"이라고 했으므로 날씨 때문이다. 청소는 탑승구가 바뀐 이유이지 지연의 이유가 아니다."},{"q":"Look at the graphic. What time will the ferry to Port Allen now depart?","choices":["10:45","10:15","11:50","11:20"],"answer":2,"type":"시각 자료 연계","explanation":"표에서 포트 앨런행은 원래 11시 20분 출발인데 \"thirty minutes later than scheduled\"라고 했으므로 11시 50분에 떠난다. 11시 20분은 원래 시각이다."},{"q":"What can listeners get for free?","choices":["A snack","A ticket refund","A beverage","A seat upgrade"],"answer":2,"type":"세부 사항","explanation":"화자가 \"you can enjoy a free coffee at the café\"라고 했다. coffee를 beverage로 바꿔 표현했다."}],"translation":"승객 여러분, 안녕하십니까. 포트 앨런으로 가시는 승객께 안내 말씀 드립니다. 오늘 아침 강풍으로 인해 여러분의 여객선은 예정보다 30분 늦게 출발합니다. 불편을 드려 죄송합니다. 또한 원래 탑승구를 청소하고 있어 승선은 표에 적힌 탑승구가 아닌 1번 탑승구에서 진행됩니다. 그린 아일랜드행 여객선은 정시에 출발합니다. 기다리시는 동안 2층 카페에서 무료 커피를 즐기실 수 있습니다. 표만 보여 주시면 됩니다. 기다려 주셔서 감사드리며 즐거운 여행 되십시오.","part":4},{"id":"p4-029","level":2,"topic":"자동차 정비소 점검 결과 전화","talk_type":"전화 메시지","voice":"male","script":"Hello, this is Mark calling from City Auto Service for Ms. Patel. We finished checking your car this morning. The good news is that the engine noise was just a loose part, and we've already fixed it. However, we also noticed that your front tires are almost worn out. We recommend replacing them soon, especially before winter. We have the right tires in stock, and we could replace them today for three hundred and twenty dollars. If you'd like us to do that, please call me back before three o'clock. Otherwise, your car will be ready to pick up at four. Thanks.","graphic":null,"questions":[{"q":"Why is the speaker calling?","choices":["To ask for an overdue payment","To give an update on a car repair","To sell a new car","To schedule an appointment"],"answer":1,"type":"주제·목적","explanation":"화자가 \"We finished checking your car this morning.\"이라며 점검 결과와 수리 내용을 알리고 있다."},{"q":"What does the speaker recommend?","choices":["Renting a car","Fixing the engine","Getting a car wash","Replacing some tires"],"answer":3,"type":"요청·제안","explanation":"화자가 앞 타이어가 거의 닳았다며 \"We recommend replacing them soon\"이라고 했다. 엔진 소음은 이미 고쳤으므로 오답이다."},{"q":"What should the listener do before three o'clock?","choices":["Call the shop to approve more work","Pick up her car","Bring her car to the shop","Pay her bill"],"answer":0,"type":"요청·제안","explanation":"화자가 타이어 교체를 원하면 \"please call me back before three o'clock\"이라고 했다. 추가 작업을 원하면 3시 전에 연락해야 한다. 차를 찾는 시각은 4시다."}],"translation":"안녕하세요, 시티 오토 서비스의 마크입니다. 파텔 씨께 전화드렸어요. 오늘 아침에 차 점검을 마쳤습니다. 좋은 소식은 엔진 소음이 헐거운 부품 하나 때문이었고, 이미 고쳤다는 거예요. 다만 앞 타이어가 거의 닳은 것도 발견했어요. 특히 겨울이 오기 전에 곧 교체하시길 권합니다. 맞는 타이어가 재고로 있어서 오늘 320달러에 교체해 드릴 수 있어요. 그렇게 하길 원하시면 3시 전에 다시 전화 주세요. 아니면 차는 4시에 찾아가실 수 있게 준비해 둘게요. 감사합니다.","part":4},{"id":"p4-030","level":2,"topic":"온라인 경비 정산 제도 도입","talk_type":"회의 발췌","voice":"female","script":"Before we finish today's meeting, I want to talk about the new expense report system. Starting next month, all travel expenses must be submitted online instead of on paper forms. You'll need to take a photo of each receipt and upload it with your report. The good news is that you'll get your money back much faster, usually within five business days. I know some of you aren't comfortable with new software. Well, the accounting team is holding a thirty-minute training session this Thursday at two. I'd like everyone who travels for work to attend. I'll send the details by e-mail after this meeting.","graphic":null,"questions":[{"q":"What will change next month?","choices":["The weekly meeting schedule","How expense reports are submitted","The location of the accounting team","The size of the travel budget"],"answer":1,"type":"주제·목적","explanation":"화자가 \"all travel expenses must be submitted online instead of on paper forms\"라고 했으므로 경비 보고서 제출 방식이 바뀐다."},{"q":"Why does the speaker say, \"I know some of you aren't comfortable with new software\"?","choices":["To announce that the software will be delayed","To explain why paper forms will still be used","To ask for volunteers to test it","To introduce a way to get help"],"answer":3,"type":"의도 파악","explanation":"이 말 바로 뒤에 \"Well, the accounting team is holding a thirty-minute training session\"이라며 교육을 안내한다. 새 프로그램이 익숙하지 않은 사람을 위한 도움을 소개하려는 것이다."},{"q":"What will the speaker send by e-mail?","choices":["Information about a training session","A new travel policy","Notes from the meeting","Copies of receipts"],"answer":0,"type":"다음 할 일","explanation":"교육 참석을 요청한 뒤 \"I'll send the details by e-mail after this meeting.\"이라고 했으므로 교육에 관한 세부 정보를 보낸다."}],"translation":"오늘 회의를 마치기 전에 새 경비 보고 시스템에 대해 말씀드리고 싶습니다. 다음 달부터 모든 출장 경비는 종이 양식 대신 온라인으로 제출해야 합니다. 영수증마다 사진을 찍어 보고서와 함께 올리셔야 합니다. 좋은 점은 돈을 훨씬 빨리, 보통 영업일 5일 안에 돌려받으신다는 겁니다. 새 소프트웨어가 불편한 분들도 있다는 걸 압니다. 그래서 회계팀이 이번 주 목요일 2시에 30분짜리 교육을 엽니다. 업무로 출장을 다니시는 분은 모두 참석해 주셨으면 합니다. 자세한 내용은 회의가 끝난 뒤 이메일로 보내 드리겠습니다.","part":4},{"id":"p4-031","level":2,"topic":"직장인 어학원 광고","talk_type":"광고","voice":"male","script":"Is your company doing more business overseas? Then it's time to try Lingo Plus Language School. We offer Spanish, Chinese, Japanese, and German classes designed especially for busy professionals. Classes are held early in the morning and in the evening, so you don't have to miss work. Can't come to our school? Our teachers can also come to your office for group lessons. All of our teachers are native speakers with at least five years of experience. And right now, new students can take their first class for free. Just visit our Web site to find a class time that works for you. Lingo Plus, your partner in global business.","graphic":null,"questions":[{"q":"Who is the advertisement mainly intended for?","choices":["Tour guides who travel overseas","Language teachers","Working professionals","University students"],"answer":2,"type":"주제·목적","explanation":"화자가 \"classes designed especially for busy professionals\"라고 했고 업무를 빠지지 않아도 된다고 하므로 직장인 대상 광고다."},{"q":"What does the speaker say about the teachers?","choices":["They teach only online.","They have several years of experience.","They also run businesses.","They often travel abroad."],"answer":1,"type":"세부 사항","explanation":"화자가 \"native speakers with at least five years of experience\"라고 했으므로 최소 5년 경력이 있다. 강사가 사무실로 찾아가기도 하므로 온라인으로만 가르친다는 것은 오답이다."},{"q":"What is offered to new students?","choices":["A free textbook","A discount on group classes","A certificate","A free lesson"],"answer":3,"type":"세부 사항","explanation":"화자가 \"new students can take their first class for free\"라고 했으므로 첫 수업이 무료다."}],"translation":"귀사의 해외 사업이 늘고 있나요? 그렇다면 링고 플러스 어학원을 경험해 볼 때입니다. 저희는 바쁜 직장인을 위해 특별히 만든 스페인어, 중국어, 일본어, 독일어 수업을 제공합니다. 수업은 이른 아침과 저녁에 열리므로 일을 빠지지 않으셔도 됩니다. 학원에 오시기 어려우세요? 강사가 사무실로 찾아가 그룹 수업을 할 수도 있습니다. 저희 강사는 모두 최소 5년 경력의 원어민입니다. 그리고 지금 신규 수강생은 첫 수업을 무료로 들으실 수 있습니다. 웹사이트를 방문해 맞는 수업 시간을 찾아보세요. 링고 플러스, 글로벌 비즈니스의 동반자입니다.","part":4},{"id":"p4-032","level":2,"topic":"가족 운영 와이너리 투어","talk_type":"관광·견학 안내","voice":"female","script":"Welcome to Oak Valley Vineyard. My name is Sofia, and I'll be showing you around this afternoon. Our family has been making wine here for over sixty years. We'll start in the vineyard itself, where you'll see grapes that are almost ready to be picked. Then we'll go down to the cellar, where the wine is stored in wooden barrels. It's quite cool down there, so you may want to bring a jacket. The tour ends in our tasting room, where you can try four of our wines. For those of you who are driving, we also offer our own fresh grape juice. Please stay with the group, as some areas are not open to the public.","graphic":null,"questions":[{"q":"What does the speaker say about the vineyard?","choices":["It is run by a family.","It will close soon.","It grows many kinds of fruit.","It opened last year."],"answer":0,"type":"세부 사항","explanation":"화자가 \"Our family has been making wine here for over sixty years.\"라고 했으므로 가족이 운영하는 곳이다. 60년 넘게 운영했으므로 작년에 열었다는 것은 오답이다."},{"q":"Why does the speaker mention a jacket?","choices":["Jackets are sold in the shop.","The whole tour is outdoors.","One of the locations is cold.","It might rain later."],"answer":2,"type":"세부 사항","explanation":"지하 저장고에 대해 \"It's quite cool down there, so you may want to bring a jacket.\"이라고 했으므로 그곳이 서늘하기 때문이다."},{"q":"What is offered to drivers?","choices":["A bottle of wine to take home","A non-alcoholic drink","A shorter tour","Free parking"],"answer":1,"type":"세부 사항","explanation":"화자가 \"For those of you who are driving, we also offer our own fresh grape juice.\"라고 했다. 포도 주스를 알코올 없는 음료로 바꿔 표현했다."}],"translation":"오크 밸리 와이너리에 오신 것을 환영합니다. 제 이름은 소피아이고 오늘 오후 여러분을 안내하겠습니다. 저희 가족은 60년 넘게 이곳에서 와인을 만들어 왔습니다. 먼저 포도밭에서 시작하는데, 거의 수확할 때가 된 포도를 보시게 됩니다. 그다음 와인을 나무 통에 보관하는 지하 저장고로 내려가겠습니다. 그곳은 꽤 서늘하니 재킷을 챙기시는 게 좋겠습니다. 투어는 시음실에서 끝나며, 저희 와인 네 가지를 맛보실 수 있습니다. 운전하시는 분들을 위해 직접 만든 신선한 포도 주스도 준비해 두었습니다. 일부 구역은 일반인에게 공개되지 않으니 일행과 함께 다녀 주세요.","part":4},{"id":"p4-033","level":3,"topic":"팟캐스트 중간 광고 — 높이 조절 책상","talk_type":"광고","voice":"male","script":"This episode of Small Business Hour is sponsored by DeskMate. Most of us spend eight hours a day or more sitting at a desk, and by three o'clock, our backs are telling us about it. DeskMate is an adjustable desk that goes from sitting to standing height at the touch of a button. It remembers up to four height settings, so everyone in a shared office can use it comfortably. I've had one in my studio for six months. You can tell I'm standing right now, can't you? DeskMate ships free within five business days, and setup takes about twenty minutes, no tools needed. Listeners of this show can get fifteen percent off by entering the code HOUR at checkout.","graphic":null,"questions":[{"q":"What product is being advertised?","choices":["A recording device","A fitness app for desk workers","A massage service","A piece of office furniture"],"answer":3,"type":"주제·목적","explanation":"화자가 \"DeskMate is an adjustable desk\"라고 소개했다. desk를 a piece of office furniture로 바꿔 표현했다. 허리(backs) 이야기에 마사지를 고르면 안 된다."},{"q":"What feature of the product is mentioned?","choices":["It is made from recycled materials.","It comes with a matching chair.","It saves users' preferred heights.","It folds up for easy storage."],"answer":2,"type":"세부 사항","explanation":"화자가 \"It remembers up to four height settings\"라고 했으므로 사용자가 원하는 높이를 저장한다."},{"q":"Why does the speaker say, \"You can tell I'm standing right now, can't you?\"","choices":["To suggest that he is using the product as he speaks","To explain why the episode is shorter than usual today","To apologize for the sound quality","To ask listeners to stand up"],"answer":0,"type":"의도 파악","explanation":"\"I've had one in my studio for six months.\"라고 한 직후의 말로, 지금도 그 책상을 세워서 쓰며 방송하고 있다는 것을 가볍게 보여 주는 표현이다. 진행자 본인이 직접 쓰는 제품임을 강조한다."}],"translation":"이번 ‘스몰 비즈니스 아워’ 회차는 데스크메이트의 후원으로 제작됩니다. 우리 대부분은 하루 여덟 시간 이상 책상에 앉아 지내고, 오후 3시쯤이면 허리가 그걸 알려 주죠. 데스크메이트는 버튼 하나로 앉은 높이에서 선 높이로 바뀌는 높이 조절 책상입니다. 높이 설정을 네 개까지 기억하기 때문에 공용 사무실의 모든 사람이 편하게 쓸 수 있습니다. 저도 6개월째 스튜디오에서 쓰고 있어요. 지금 제가 서 있다는 게 느껴지시죠? 데스크메이트는 영업일 5일 안에 무료로 배송되고, 조립은 공구 없이 20분 정도면 됩니다. 이 방송 청취자는 결제할 때 HOUR 코드를 입력하면 15퍼센트 할인을 받을 수 있습니다.","part":4},{"id":"p4-034","level":3,"topic":"올해의 직원상 시상 연설","talk_type":"연설·소개","voice":"female","script":"Good evening, everyone. As CEO, I get to give out a lot of awards, but tonight's Employee of the Year award is always my favorite. This year's winner joined our customer service department just three years ago. Last spring, when our online ordering system went down for two full days, she organized a team that answered every customer call by hand and made sure each order was shipped on time. Many of those customers still mention her by name in their reviews. In addition to this award, she'll receive an extra week of paid vacation, which I'm told she's already planning to use in Portugal. Please join me in welcoming to the stage Ms. Hannah Cole.","graphic":null,"questions":[{"q":"Where most likely is the speech being given?","choices":["At a retirement party","At a press conference","At an awards dinner","At a training session"],"answer":2,"type":"화자 정보(직업·장소)","explanation":"화자가 \"tonight's Employee of the Year award\"를 발표하고 수상자를 무대로 부르므로 저녁 시상식 자리다."},{"q":"What did Hannah Cole do last spring?","choices":["She wrote online product reviews.","She opened an office in Portugal.","She designed a new ordering system for customers.","She led a response to a technical failure."],"answer":3,"type":"세부 사항","explanation":"화자가 \"when our online ordering system went down for two full days, she organized a team\"이라고 했다. 시스템 장애에 대응하는 팀을 이끈 것이다. 시스템을 설계한 것은 아니다."},{"q":"What will Ms. Cole receive in addition to the award?","choices":["A trip to Portugal","Additional time off","A cash bonus","A promotion"],"answer":1,"type":"세부 사항","explanation":"화자가 \"she'll receive an extra week of paid vacation\"이라고 했으므로 추가 휴가를 받는다. 포르투갈은 그 휴가를 쓸 곳일 뿐 회사가 여행을 주는 것이 아니다."}],"translation":"안녕하십니까, 여러분. CEO로서 저는 많은 상을 수여하지만, 오늘 밤 올해의 직원상은 언제나 제가 가장 좋아하는 상입니다. 올해 수상자는 불과 3년 전에 고객 서비스 부서에 입사했습니다. 지난봄 온라인 주문 시스템이 꼬박 이틀 동안 멈췄을 때, 그녀는 팀을 꾸려 모든 고객 전화를 직접 응대하고 모든 주문이 제때 발송되도록 했습니다. 그 고객들 중 상당수가 지금도 후기에서 그녀의 이름을 언급합니다. 이 상과 함께 그녀는 일주일의 유급 휴가를 추가로 받게 되는데, 벌써 포르투갈에서 쓸 계획이라고 들었습니다. 한나 콜 씨를 무대로 모시겠습니다. 함께 환영해 주십시오.","part":4},{"id":"p4-035","level":3,"topic":"신제품 출시 일정 점검 회의","talk_type":"회의 발췌","voice":"male","script":"Let's go over the launch timeline for the SmartKettle. The good news is that the packaging design was approved yesterday, well ahead of schedule. However, I got a call from the video production company this morning. Their editor is sick, so the training videos for retail staff won't be ready until a week after the deadline. That means stores will have less time to train their sales staff before the launch. To make up for this, I'd like our product specialists to visit our five largest retail partners in person. Rebecca, since you manage those accounts, could you set up the visits? Let's keep all the other dates as they are.","graphic":{"title":"SmartKettle Launch Timeline","rows":[["Task","Deadline"],["Final packaging design","June 3"],["Retailer training videos","June 17"],["Press release","June 24"],["Store launch","July 1"]]},"questions":[{"q":"What is the main purpose of the talk?","choices":["To review a product launch schedule","To report sales results from last quarter","To choose a packaging design","To announce a new hire"],"answer":0,"type":"주제·목적","explanation":"화자가 \"Let's go over the launch timeline for the SmartKettle.\"이라고 시작하므로 출시 일정을 점검하는 것이 목적이다. 포장 디자인은 이미 승인됐다."},{"q":"Look at the graphic. Which deadline will be missed?","choices":["July 1","June 17","June 3","June 24"],"answer":1,"type":"시각 자료 연계","explanation":"화자가 \"the training videos for retail staff won't be ready until a week after the deadline\"이라고 했다. 표에서 판매점 교육 영상 마감은 6월 17일이다. 6월 3일 포장 디자인은 오히려 일찍 끝났다."},{"q":"What is Rebecca asked to do?","choices":["Redesign the packaging","Edit the training videos","Arrange visits to retailers","Write a press release for the launch"],"answer":2,"type":"요청·제안","explanation":"화자가 대형 협력 매장 방문을 제안한 뒤 \"Rebecca ... could you set up the visits?\"라고 했다. 소매업체 방문 일정을 잡아 달라는 요청이다."}],"translation":"스마트케틀 출시 일정을 검토해 봅시다. 좋은 소식은 포장 디자인이 예정보다 훨씬 이른 어제 승인됐다는 겁니다. 그런데 오늘 아침 영상 제작사에서 전화가 왔습니다. 편집자가 아파서 판매점 직원용 교육 영상이 마감보다 일주일 늦게야 준비된다고 합니다. 그러면 매장들이 출시 전에 판매 직원을 교육할 시간이 줄어듭니다. 이를 보완하기 위해 우리 제품 전문가들이 가장 큰 협력 판매점 다섯 곳을 직접 방문했으면 합니다. 레베카, 그 거래처들을 맡고 있으니 방문 일정을 잡아 줄 수 있어요? 나머지 날짜는 모두 그대로 유지합시다.","part":4},{"id":"p4-036","level":3,"topic":"시립 도서관 리모델링 지역 뉴스","talk_type":"방송·뉴스","voice":"female","script":"In local news, the Westfield Public Library will close its main building on March first for a major renovation. The eighteen-month project will add a new children's wing, a community meeting room, and a rooftop reading garden. It's being paid for mostly through a state grant, along with donations from local businesses. During the renovation, the library will operate a temporary branch in the former post office building on Elm Street. Library director Maria Gomez says the temporary location will have a smaller collection, but any book can be requested online and delivered there within two days. Residents can see the design plans at an open house at City Hall next Tuesday evening.","graphic":null,"questions":[{"q":"What is the news report mainly about?","choices":["The renovation of a public building","A fundraising campaign for a new library","The opening of a new post office","A change in library hours"],"answer":0,"type":"주제·목적","explanation":"화자가 도서관 본관이 \"for a major renovation\" 문을 닫는다고 전하고 공사 내용을 설명하므로 공공건물 개보수가 주제다. 옛 우체국 건물은 임시 분관 장소다."},{"q":"How is the project mainly being funded?","choices":["With a bank loan","With higher library fees","With ticket sales","With government money"],"answer":3,"type":"세부 사항","explanation":"화자가 \"It's being paid for mostly through a state grant\"라고 했다. 주 정부 보조금을 government money로 바꿔 표현했다. 지역 기업 기부는 보조 재원이다."},{"q":"What can residents do next Tuesday?","choices":["Vote on a design","Borrow books from a new branch","Meet the construction workers","View the plans for a project"],"answer":3,"type":"세부 사항","explanation":"화자가 \"Residents can see the design plans at an open house at City Hall next Tuesday evening.\"이라고 했으므로 설계안을 볼 수 있다."}],"translation":"지역 소식입니다. 웨스트필드 공공 도서관이 대규모 개보수를 위해 3월 1일 본관을 닫습니다. 18개월에 걸친 이 공사로 새 어린이관, 주민 회의실, 옥상 독서 정원이 생깁니다. 공사비는 주로 주 정부 보조금과 지역 기업들의 기부금으로 충당됩니다. 공사 기간 동안 도서관은 엘름 스트리트의 옛 우체국 건물에서 임시 분관을 운영합니다. 마리아 고메즈 도서관장은 임시 분관의 장서는 더 적지만, 어떤 책이든 온라인으로 신청하면 이틀 안에 그곳으로 배송된다고 밝혔습니다. 주민들은 다음 주 화요일 저녁 시청에서 열리는 공개 행사에서 설계안을 볼 수 있습니다.","part":4},{"id":"p4-037","level":3,"topic":"의료 학회 둘째 날 안내 방송","talk_type":"안내 방송","voice":"male","script":"Good morning, and welcome to the second day of the Regional Health Care Conference. Just a few quick announcements before the morning sessions begin. First, the session on patient data security, originally scheduled for the Maple Room, has been moved to the Grand Ballroom because so many of you signed up for it. Second, lunch today will be served on the outdoor terrace, weather permitting. If it rains, it will be in the main dining hall on the first floor. Finally, if you haven't picked up your certificate of attendance, please stop by the registration desk before four o'clock this afternoon. Certificates will not be mailed after the conference.","graphic":null,"questions":[{"q":"Who most likely are the listeners?","choices":["Restaurant staff","Conference participants","Hospital patients","Hotel employees"],"answer":1,"type":"화자 정보(직업·장소)","explanation":"화자가 \"welcome to the second day of the Regional Health Care Conference\"라며 세션과 점심, 참석 증명서를 안내하므로 학회 참가자들이다. 의료(health care)가 주제라고 환자를 고르면 안 된다."},{"q":"Why was a session moved?","choices":["The speaker arrived late.","A room needed repairs after a leak.","It was more popular than expected.","The weather was bad."],"answer":2,"type":"세부 사항","explanation":"화자가 \"because so many of you signed up for it\"이라고 했으므로 신청자가 많아서 더 큰 곳으로 옮겼다."},{"q":"What should some listeners do before four o'clock?","choices":["Collect a document","Register for a session","Fill out a survey","Pay for lunch"],"answer":0,"type":"요청·제안","explanation":"화자가 참석 증명서를 아직 안 받았다면 \"stop by the registration desk before four o'clock\"이라고 했다. certificate를 document로 바꿔 표현했다."}],"translation":"좋은 아침입니다. 지역 보건의료 학회 둘째 날에 오신 것을 환영합니다. 오전 세션이 시작되기 전에 간단히 몇 가지 안내해 드리겠습니다. 먼저, 원래 메이플 룸에서 열릴 예정이던 환자 데이터 보안 세션은 신청하신 분이 너무 많아 그랜드 볼룸으로 옮겼습니다. 둘째, 오늘 점심은 날씨가 괜찮으면 야외 테라스에서 제공됩니다. 비가 오면 1층 대식당에서 제공됩니다. 마지막으로 아직 참석 증명서를 받지 않으셨다면 오늘 오후 4시 전에 등록 데스크에 들러 주십시오. 학회가 끝난 뒤에는 증명서를 우편으로 보내 드리지 않습니다.","part":4},{"id":"p4-038","level":3,"topic":"이사회 점심 케이터링 회신 전화","talk_type":"전화 메시지","voice":"female","script":"Hi, Mr. Walsh. This is Emma from Fresh Plate Catering, returning your call about the lunch for your board meeting on Friday the fifteenth. First, adding six more guests is no problem, so we'll plan for thirty people. You also asked whether we could include a few gluten-free meals. We can, and there's no extra charge. Now, you mentioned you might want to make more changes as late as next Wednesday. Well, our kitchen starts ordering ingredients and preparing food three days before each event. So it would be best to confirm everything by Monday. I'll e-mail you a revised quote this afternoon. Please call me at 555-0172 if you have any questions.","graphic":null,"questions":[{"q":"Why is the speaker calling?","choices":["To introduce a new menu for board events","To respond to a client's requests","To cancel an event","To ask for a payment"],"answer":1,"type":"주제·목적","explanation":"화자가 \"returning your call\"이라며 인원 추가, 글루텐 없는 식사 등 고객이 요청한 사항에 답하고 있다."},{"q":"Why does the speaker say, \"our kitchen starts ordering ingredients and preparing food three days before each event\"?","choices":["To justify a price increase","To apologize for a delivery delay","To explain why a proposed deadline is too late","To describe the quality of the food"],"answer":2,"type":"의도 파악","explanation":"고객이 수요일까지 변경하고 싶다고 한 데 대한 답으로, 행사(금요일) 사흘 전부터 준비하니 \"it would be best to confirm everything by Monday\"라고 이어진다. 수요일은 너무 늦다는 뜻이다."},{"q":"What will the speaker send this afternoon?","choices":["An updated price estimate","A contract for the catering service","A sample menu","A delivery schedule"],"answer":0,"type":"다음 할 일","explanation":"화자가 \"I'll e-mail you a revised quote this afternoon.\"이라고 했다. revised quote를 updated price estimate로 바꿔 표현했다."}],"translation":"안녕하세요, 월시 씨. 프레시 플레이트 케이터링의 엠마예요. 15일 금요일 이사회 점심 건으로 회신드려요. 먼저, 손님 여섯 분을 추가하는 건 문제없으니 30명으로 준비할게요. 글루텐 없는 식사를 몇 개 넣을 수 있는지도 물으셨는데, 가능하고 추가 요금도 없어요. 그런데 다음 주 수요일까지도 변경하고 싶으실 수 있다고 하셨죠. 음, 저희 주방은 각 행사 사흘 전부터 재료를 주문하고 음식을 준비해요. 그러니 월요일까지 모두 확정해 주시는 게 가장 좋아요. 오늘 오후에 수정 견적서를 이메일로 보내 드릴게요. 궁금한 점이 있으면 555-0172로 전화 주세요.","part":4},{"id":"p4-039","level":4,"topic":"투자자 대상 태양광 패널 공장 견학","talk_type":"관광·견학 안내","voice":"male","script":"Welcome to our Riverside production facility. Before we go onto the factory floor, I'll ask everyone to put on a pair of the safety glasses in the basket by the door. As investors, many of you have asked how we were able to cut production costs by twenty percent last year. Well, you're about to see the answer. Our new assembly line uses robots to cut and position the solar cells, and it has reduced material waste dramatically. After that, we'll stop by the quality-control lab, where every panel is tested under simulated storm conditions. Please note that photography isn't permitted inside the lab, as some of the equipment is still under patent review. We'll finish in the conference room, where our chief engineer will answer your questions.","graphic":null,"questions":[{"q":"Who most likely are the listeners?","choices":["Newly hired factory workers in training","Government safety inspectors","Solar panel customers","Financial backers of the company"],"answer":3,"type":"화자 정보(직업·장소)","explanation":"화자가 \"As investors, many of you have asked\"라고 했으므로 회사에 투자한 사람들이다. investors를 financial backers로 바꿔 표현했다. 보안경을 쓰라는 안내 때문에 안전 점검관을 고르면 안 된다."},{"q":"Why does the speaker say, \"you're about to see the answer\"?","choices":["To ask listeners to guess a number","To encourage listeners to take photographs","To indicate that the tour will explain a cost reduction","To apologize for not answering questions earlier"],"answer":2,"type":"의도 파악","explanation":"생산비를 20퍼센트 줄인 방법을 궁금해했다는 말 뒤에 이렇게 말하고 곧바로 로봇 조립 라인을 소개한다. 곧 보게 될 설비가 원가 절감의 비결이라는 뜻이다."},{"q":"Why are listeners not allowed to take photos in the lab?","choices":["Tests are already being filmed by a television crew.","The lab is too dark.","The equipment is dangerous to approach.","Some technology is awaiting legal protection."],"answer":3,"type":"세부 사항","explanation":"화자가 \"some of the equipment is still under patent review\"라고 했다. 특허 심사 중이라는 것을 법적 보호를 기다리고 있다고 바꿔 표현했다."}],"translation":"리버사이드 생산 시설에 오신 것을 환영합니다. 공장 작업장으로 들어가기 전에 모두 문 옆 바구니에 있는 보안경을 착용해 주십시오. 투자자로서 많은 분들이 저희가 작년에 어떻게 생산비를 20퍼센트 줄일 수 있었는지 물으셨습니다. 자, 이제 그 답을 보시게 됩니다. 새 조립 라인은 로봇을 이용해 태양전지를 자르고 배치하며, 원자재 낭비를 크게 줄였습니다. 그다음 품질 관리 연구실에 들르는데, 그곳에서는 모든 패널을 폭풍우를 재현한 조건에서 시험합니다. 일부 장비가 아직 특허 심사 중이라 연구실 안에서는 사진 촬영이 허용되지 않는다는 점 유의해 주십시오. 마지막으로 회의실에서 수석 엔지니어가 여러분의 질문에 답해 드릴 것입니다.","part":4},{"id":"p4-040","level":4,"topic":"항공사 합병 경제 뉴스","talk_type":"방송·뉴스","voice":"female","script":"And now for business news. Skyline Airways and Northern Air announced this morning that they have agreed to merge, creating the country's third-largest airline. The combined company will keep the Skyline name, but Northern Air's chief executive, Peter Lund, will lead it. The deal still needs government approval, which analysts expect could take up to a year. Frequent flyers are already asking what will happen to their reward miles. In a statement, both airlines said members of either program will be able to move their miles into a single account once the merger is complete. Meanwhile, Skyline's stock rose nearly nine percent on the news. We'll have more on this story at the top of the hour.","graphic":null,"questions":[{"q":"What is the news report mainly about?","choices":["A change in travel regulations","Two companies combining","An airline going out of business","A new airport opening"],"answer":1,"type":"주제·목적","explanation":"화자가 두 항공사가 \"agreed to merge\"했다고 전하므로 두 회사의 합병이 주제다."},{"q":"Who will run the new company?","choices":["The current head of Northern Air","A financial analyst","The current head of Skyline Airways","A government official"],"answer":0,"type":"세부 사항","explanation":"화자가 \"Northern Air's chief executive, Peter Lund, will lead it\"이라고 했다. 회사 이름은 스카이라인을 쓰지만 경영은 노던 에어 CEO가 맡는다는 점이 함정이다."},{"q":"According to the speaker, what are customers concerned about?","choices":["Baggage fees","Changes to flight schedules","Higher ticket prices","Their loyalty program benefits"],"answer":3,"type":"세부 사항","explanation":"화자가 \"Frequent flyers are already asking what will happen to their reward miles.\"라고 했다. 마일리지를 loyalty program benefits로 바꿔 표현했다."}],"translation":"이어서 경제 소식입니다. 스카이라인 항공과 노던 에어가 오늘 아침 합병에 합의했다고 발표해 국내 3위 규모의 항공사가 탄생하게 됐습니다. 합병 회사는 스카이라인이라는 이름을 유지하지만, 노던 에어의 피터 룬드 최고경영자가 회사를 이끌게 됩니다. 이 거래는 아직 정부 승인이 필요하며, 분석가들은 승인까지 최대 1년이 걸릴 수 있다고 봅니다. 단골 고객들은 벌써 자신들의 보상 마일리지가 어떻게 되는지 묻고 있습니다. 두 항공사는 성명을 통해 합병이 완료되면 어느 쪽 프로그램 회원이든 마일리지를 하나의 계정으로 옮길 수 있다고 밝혔습니다. 한편 이 소식에 스카이라인의 주가는 9퍼센트 가까이 올랐습니다. 정시 뉴스에서 이 소식을 더 전해 드리겠습니다.","part":4},{"id":"p4-041","level":4,"topic":"도시 디자인 포럼 강연자 소개","talk_type":"연설·소개","voice":"male","script":"Thank you all for coming to the final session of this year's Urban Design Forum. Our speaker this afternoon hardly needs an introduction, but I'll give her one anyway. Dr. Nadia Farouk began her career as a civil engineer, designing bridges, before moving into city planning. Over the past decade, she has advised more than thirty cities on how to redesign their streets for pedestrians and cyclists. Today, she'll be talking about how small, low-cost changes, like painted bike lanes and temporary seating, can test ideas before cities commit to expensive construction. Dr. Farouk will take questions at the end, so please write yours on the cards on your tables. Please join me in welcoming Dr. Farouk.","graphic":null,"questions":[{"q":"What was Dr. Farouk's first job?","choices":["Translating books","Designing bridges","Teaching architecture","Serving as a city mayor"],"answer":1,"type":"세부 사항","explanation":"화자가 \"Dr. Nadia Farouk began her career as a civil engineer, designing bridges\"라고 했으므로 처음에는 다리를 설계했다. 도시 계획은 그 뒤에 옮긴 분야다."},{"q":"What will Dr. Farouk's talk focus on?","choices":["Funding for large construction projects in cities","The history of bridge construction","Inexpensive ways to test changes to streets","Training programs for engineers"],"answer":2,"type":"주제·목적","explanation":"화자가 \"how small, low-cost changes ... can test ideas before cities commit to expensive construction\"에 대해 이야기할 것이라고 했다. 비싼 공사는 오히려 그 전에 시험해 보자는 대상이다."},{"q":"How should listeners submit questions?","choices":["By writing them on cards","By raising their hands at the end","By using a microphone","By sending e-mails"],"answer":0,"type":"요청·제안","explanation":"화자가 \"please write yours on the cards on your tables\"라고 했으므로 탁자 위 카드에 적어야 한다."}],"translation":"올해 도시 디자인 포럼의 마지막 세션에 와 주신 모든 분께 감사드립니다. 오늘 오후 연사는 따로 소개가 필요 없는 분이지만, 그래도 소개해 드리겠습니다. 나디아 파루크 박사는 도시 계획 분야로 옮기기 전, 다리를 설계하는 토목 기술자로 경력을 시작했습니다. 지난 10년간 30곳이 넘는 도시에 보행자와 자전거 이용자를 위해 거리를 재설계하는 방법을 자문해 왔습니다. 오늘은 페인트로 그린 자전거 도로나 임시 좌석처럼 작고 비용이 적게 드는 변화가 어떻게 도시가 비싼 공사에 착수하기 전에 아이디어를 시험해 볼 수 있게 하는지 이야기해 주실 겁니다. 파루크 박사는 마지막에 질문을 받으실 예정이니 탁자 위 카드에 질문을 적어 주십시오. 파루크 박사를 함께 환영해 주십시오.","part":4},{"id":"p4-042","level":4,"topic":"3분기 지역별 판매 실적 회의","talk_type":"회의 발췌","voice":"female","script":"Thanks, everyone. Let's look at third-quarter sales. Overall, we came in slightly below our target, but most regions did well. In fact, only one region fell short, and by quite a bit. After speaking with the regional manager there, I learned that our main distributor in that area was closed for most of August because of flood damage. So the problem wasn't customer demand. The distributor has reopened, and orders are already recovering. Still, to make sure this doesn't happen again, I'd like us to sign an agreement with a second distributor in each region. Kenji, please put together a list of possible partners before our next meeting.","graphic":{"title":"Q3 Sales by Region (units)","rows":[["Region","Target","Actual"],["North","5,000","5,400"],["South","4,000","3,100"],["East","6,000","6,200"],["West","3,500","3,600"]]},"questions":[{"q":"Look at the graphic. Which region is the speaker mainly discussing?","choices":["North","South","East","West"],"answer":1,"type":"시각 자료 연계","explanation":"화자가 \"only one region fell short, and by quite a bit\"라고 했다. 표에서 실적이 목표에 못 미친 곳은 남부(목표 4,000, 실제 3,100)뿐이다."},{"q":"What caused the problem in that region?","choices":["A product was recalled.","A competitor lowered its prices.","Customer demand decreased.","A business partner was temporarily closed."],"answer":3,"type":"세부 사항","explanation":"화자가 \"our main distributor in that area was closed for most of August because of flood damage\"라고 했고, 이어서 \"the problem wasn't customer demand\"라고 분명히 했다."},{"q":"What does the speaker ask Kenji to do?","choices":["Assess flood damage","Visit the regional manager","Identify potential distributors","Revise the sales targets"],"answer":2,"type":"요청·제안","explanation":"화자가 지역마다 두 번째 유통업체와 계약하자고 한 뒤 \"Kenji, please put together a list of possible partners\"라고 했다. 후보 유통업체를 찾아 달라는 요청이다."}],"translation":"고마워요, 여러분. 3분기 판매를 봅시다. 전체적으로는 목표에 약간 못 미쳤지만 대부분의 지역은 잘했습니다. 사실 목표에 못 미친 지역은 한 곳뿐인데, 그 차이가 꽤 큽니다. 그 지역 관리자와 이야기해 보니 그 지역의 주요 유통업체가 홍수 피해로 8월 대부분 문을 닫았더군요. 그러니 문제는 고객 수요가 아니었습니다. 그 유통업체는 다시 문을 열었고 주문도 벌써 회복되고 있습니다. 그래도 이런 일이 다시 없도록 지역마다 두 번째 유통업체와 계약을 맺었으면 합니다. 켄지, 다음 회의 전까지 협력 후보 업체 목록을 정리해 주세요.","part":4},{"id":"p4-043","level":4,"topic":"사무용 프린터 임대 서비스 광고","talk_type":"광고","voice":"male","script":"Tired of paying for printer repairs and running out of toner at the worst possible moment? With PrintPartner, you lease a high-speed office printer for one monthly fee, and we take care of everything else: toner, maintenance, and repairs. Our printers even order new toner automatically before you run out. Not sure which plan is right for you? Most offices with ten to fifteen employees print about five thousand pages a month, so choose the smallest plan that covers that amount. And this month only, if you sign a two-year lease, we'll cover your first month's fee. Call 1-800-555-0199 today, and a consultant will visit your office for a free printing assessment.","graphic":{"title":"PrintPartner Lease Plans","rows":[["Plan","Pages per Month","Monthly Fee"],["Basic","1,000","$49"],["Standard","3,000","$89"],["Business","8,000","$149"],["Enterprise","20,000","$299"]]},"questions":[{"q":"What is being advertised?","choices":["An equipment leasing service","A poster printing shop","A computer repair shop","An office supply store"],"answer":0,"type":"주제·목적","explanation":"화자가 \"With PrintPartner, you lease a high-speed office printer for one monthly fee\"라고 했으므로 사무기기 임대 서비스 광고다. 수리는 임대료에 포함된 서비스일 뿐이다."},{"q":"What feature of the service is mentioned?","choices":["Repairs cost extra.","Printers are delivered overnight.","Supplies are ordered automatically.","Paper is included at no charge for all plans."],"answer":2,"type":"세부 사항","explanation":"화자가 \"Our printers even order new toner automatically before you run out.\"이라고 했다. toner를 supplies로 바꿔 표현했다. 수리는 월 요금에 포함되므로 추가 비용이 든다는 것은 오답이다."},{"q":"Look at the graphic. How much would an office with twelve employees most likely pay per month?","choices":["$299","$49","$89","$149"],"answer":3,"type":"시각 자료 연계","explanation":"직원 10~15명 사무실은 한 달에 약 5,000장을 인쇄하니 그 양을 감당하는 가장 작은 요금제를 고르라고 했다. 표에서 5,000장 이상인 가장 작은 요금제는 Business(8,000장)로 월 149달러다. Standard는 3,000장이라 부족하다."}],"translation":"프린터 수리비를 내고, 가장 곤란한 순간에 토너가 떨어지는 데 지치셨나요? 프린트파트너와 함께라면 월 요금 하나로 고속 사무용 프린터를 임대하고, 토너·유지 관리·수리 등 나머지는 모두 저희가 맡습니다. 저희 프린터는 토너가 떨어지기 전에 자동으로 새 토너를 주문하기까지 합니다. 어떤 요금제가 맞을지 모르시겠다고요? 직원 10~15명인 사무실은 대부분 한 달에 약 5,000장을 인쇄하니, 그 양을 감당하는 가장 작은 요금제를 고르세요. 그리고 이번 달에만 2년 임대 계약을 맺으시면 첫 달 요금을 저희가 부담합니다. 오늘 1-800-555-0199로 전화 주시면 상담사가 사무실을 방문해 무료로 인쇄 환경을 진단해 드립니다.","part":4},{"id":"p4-044","level":4,"topic":"수입 화물 통관 보류 음성 메시지","talk_type":"전화 메시지","voice":"male","script":"Hello, Ms. Tanaka. This is Robert Kline from Harbor Logistics. I'm calling about your shipment of kitchen appliances that arrived at the port on Monday. Customs is holding it for inspection because the product descriptions on the commercial invoice don't match the item codes on the packing list. This happens more often than you'd think, and it's usually just a matter of correcting the paperwork. If you can send me a revised invoice by noon tomorrow, I should be able to get the shipment released by Thursday. Otherwise, the inspectors won't look at it again until next week. Your warehouse team mentioned they need the goods before the weekend sale, so please call me at 555-0163 as soon as you get this.","graphic":null,"questions":[{"q":"Why is the shipment being held?","choices":["Some products were damaged.","Some documents do not match each other.","Import taxes have not been paid.","The shipment arrived late."],"answer":1,"type":"세부 사항","explanation":"화자가 \"the product descriptions on the commercial invoice don't match the item codes on the packing list\"라고 했다. 송장과 포장 명세서가 서로 맞지 않는 서류 문제다."},{"q":"Why does the speaker say, \"This happens more often than you'd think\"?","choices":["To reassure the listener that the problem can be solved","To criticize the customs office","To explain why his fees are high","To suggest changing suppliers"],"answer":0,"type":"의도 파악","explanation":"이 말 뒤에 \"it's usually just a matter of correcting the paperwork\"라고 덧붙인다. 흔한 일이라 서류만 고치면 해결된다며 청자를 안심시키려는 것이다."},{"q":"What does the speaker ask the listener to provide?","choices":["A list of warehouse staff","Some product samples","Payment for storage","A corrected invoice"],"answer":3,"type":"요청·제안","explanation":"화자가 \"If you can send me a revised invoice by noon tomorrow\"라고 했으므로 수정된 송장을 요청했다."}],"translation":"안녕하세요, 다나카 씨. 하버 로지스틱스의 로버트 클라인입니다. 월요일에 항구에 도착한 주방 가전 화물 건으로 전화드렸어요. 상업 송장의 제품 설명이 포장 명세서의 품목 코드와 일치하지 않아서 세관이 검사를 위해 화물을 보류하고 있어요. 생각보다 자주 있는 일이고, 대개 서류만 바로잡으면 되는 문제예요. 내일 정오까지 수정된 송장을 보내 주시면 목요일까지 화물을 반출할 수 있을 거예요. 그렇지 않으면 검사관들이 다음 주에나 다시 볼 거예요. 창고 팀에서 주말 할인 행사 전에 물건이 필요하다고 하셨으니, 이 메시지를 받으시는 대로 555-0163으로 전화 주세요.","part":4},{"id":"p4-045","level":5,"topic":"도심 매장 폐쇄에 관한 주주총회 설명","talk_type":"회의 발췌","voice":"male","script":"Before we open the floor to questions, I want to address the decision many of you have asked about: why we closed our three downtown stores this year even though they were profitable. Profitable, yes. But the numbers tell only part of the story. Downtown rents have risen forty percent in five years, while our online orders from those same neighborhoods have tripled. So we've shifted that investment into two small distribution centers that can deliver to those customers within two hours. Early results are encouraging: delivery sales downtown are up twenty-two percent compared with the same quarter last year. That said, we recognize the stores had loyal customers, so we'll be opening pickup counters in two of the former locations this fall.","graphic":null,"questions":[{"q":"Who most likely are the listeners?","choices":["Delivery drivers","Real estate agents","People who own shares in the company","Store employees"],"answer":2,"type":"화자 정보(직업·장소)","explanation":"화자가 \"Before we open the floor to questions\"라며 한 해의 경영 결정과 실적을 설명하므로 주주들을 상대로 한 자리다. 매장 직원이나 배송 기사에게 투자 전환을 해명하는 상황이 아니다."},{"q":"What does the speaker mean when he says, \"the numbers tell only part of the story\"?","choices":["Profit alone did not justify keeping the stores open.","Sales at the stores were lower than had been announced to shareholders.","The financial figures were reported incorrectly.","More data will be released later."],"answer":0,"type":"의도 파악","explanation":"매장이 흑자였다고 인정한 뒤 이 말을 하고 임대료 상승과 온라인 주문 증가를 설명한다. 이익이 났다는 사실만으로는 매장을 유지할 이유가 되지 않았다는 뜻이다. 수치가 틀렸다는 뜻이 아니다."},{"q":"What does the company plan to do this fall?","choices":["Open three new downtown stores near the old sites","Use some former store sites for order pickup","Close its distribution centers","Raise its delivery prices"],"answer":1,"type":"다음 할 일","explanation":"화자가 \"we'll be opening pickup counters in two of the former locations this fall\"이라고 했으므로 예전 매장 자리 두 곳을 주문품 수령 장소로 쓴다."}],"translation":"질의응답을 시작하기 전에, 많은 분들이 물으신 결정에 대해 말씀드리겠습니다. 바로 올해 도심 매장 세 곳이 흑자였는데도 왜 문을 닫았느냐는 것입니다. 흑자였던 건 맞습니다. 하지만 수치는 이야기의 일부만 보여 줍니다. 도심 임대료는 5년 동안 40퍼센트 올랐고, 같은 동네에서 들어오는 온라인 주문은 세 배가 됐습니다. 그래서 그 투자를 해당 고객들에게 두 시간 안에 배송할 수 있는 소형 물류 센터 두 곳으로 옮겼습니다. 초기 결과는 고무적입니다. 도심 지역 배송 매출이 작년 같은 분기보다 22퍼센트 늘었습니다. 그렇긴 하지만 그 매장들에 단골 고객이 있었다는 것을 알기에, 올가을 예전 매장 자리 두 곳에 주문품 수령 카운터를 열 예정입니다.","part":4},{"id":"p4-046","level":5,"topic":"공급망 지속가능성 정상회의 기조연설","talk_type":"연설·소개","voice":"female","script":"Thank you. It's a privilege to open this year's Sustainable Supply Chain Summit. When our company first set a goal of zero landfill waste, our own operations team told me it was impossible. Five years later, eleven of our fourteen factories have reached it. I'd love to say it was because of some breakthrough technology. It wasn't. Most of the progress came from suppliers agreeing to take back their packaging, and from line workers who suggested hundreds of small changes. That's why today I'm announcing that we'll publish our entire supplier take-back agreement online, free for any company to copy. We don't see this as giving away an advantage. The more companies that adopt these practices, the cheaper recycled materials become for everyone, including us.","graphic":null,"questions":[{"q":"What has the speaker's company achieved?","choices":["All of its factories now use recycled materials in their packaging.","It has reduced its number of suppliers.","It has invented a new recycling technology.","Most of its factories no longer send waste to landfills."],"answer":3,"type":"세부 사항","explanation":"화자가 매립 폐기물 제로 목표를 \"eleven of our fourteen factories have reached it\"이라고 했다. 14곳 중 11곳이므로 ‘대부분’이며 ‘모든’ 공장은 아니다. 획기적 기술 덕분이 아니었다고 했으므로 기술 발명도 오답이다."},{"q":"Why does the speaker say, \"I'd love to say it was because of some breakthrough technology\"?","choices":["To admit that a goal was not reached","To promote a new technology","To emphasize that the results came from ordinary efforts","To ask for investment in research"],"answer":2,"type":"의도 파악","explanation":"바로 \"It wasn't.\"라고 부정한 뒤 공급업체의 포장재 회수와 현장 직원들의 작은 개선 제안 덕분이었다고 설명한다. 대단한 기술이 아니라 평범한 노력의 결과였음을 강조하려는 것이다."},{"q":"How does the speaker expect her company to benefit from sharing its agreement?","choices":["It will attract new employees.","Recycled materials will become less expensive.","Suppliers will lower their packaging prices for her company.","It will receive licensing fees."],"answer":1,"type":"세부 사항","explanation":"화자가 \"The more companies that adopt these practices, the cheaper recycled materials become for everyone, including us.\"라고 했다. 무료로 공개하므로 사용료 수입은 없다."}],"translation":"감사합니다. 올해 지속가능한 공급망 정상회의의 문을 열게 되어 영광입니다. 저희 회사가 처음 매립 폐기물 제로라는 목표를 세웠을 때, 저희 운영팀조차 불가능하다고 했습니다. 5년이 지난 지금, 14개 공장 중 11곳이 목표를 달성했습니다. 어떤 획기적인 기술 덕분이었다고 말할 수 있다면 좋겠지만, 그렇지 않았습니다. 진전의 대부분은 포장재를 회수하기로 동의한 공급업체들과 수백 가지의 작은 개선을 제안한 생산 라인 직원들에게서 나왔습니다. 그래서 오늘 저는 저희의 공급업체 회수 협약 전체를 온라인에 공개해 어떤 회사든 무료로 가져다 쓸 수 있게 하겠다고 발표합니다. 저희는 이것을 우위를 내주는 일로 보지 않습니다. 이런 방식을 도입하는 회사가 많아질수록 저희를 포함한 모두에게 재활용 원료가 더 저렴해지기 때문입니다.","part":4},{"id":"p4-047","level":5,"topic":"항만 파업과 인근 항구 적체 뉴스","talk_type":"방송·뉴스","voice":"male","script":"In business news, the strike by dock workers at Port Weston entered its second week today, and the effects are spreading. Shipping companies have been redirecting vessels to nearby ports, but not all of them are equipped to handle the extra volume. One port in particular, which typically clears containers in about a day, has seen wait times rise sixfold, since it lacks the cranes needed for larger ships. Retailers warn that the delays could leave store shelves short ahead of the holiday season. Talks between the union and port management are set to resume Thursday, with a government mediator present for the first time. Analysts say that even if an agreement is reached this week, it would take roughly a month to clear the backlog.","graphic":{"title":"Average Container Wait Times (days)","rows":[["Port","Last Month","This Week"],["Port Weston","2","9"],["Carlton Bay","3","4"],["Eastgate","1","6"],["Southmoor","2","3"]]},"questions":[{"q":"What is the main cause of the shipping delays?","choices":["A labor dispute","Severe weather","New government regulations","Broken equipment at Port Weston"],"answer":0,"type":"주제·목적","explanation":"화자가 \"the strike by dock workers at Port Weston\"을 첫머리에 전하므로 노동 분쟁(파업)이 원인이다. 크레인 부족은 다른 항구가 늘어난 물량을 감당하지 못하는 이유다."},{"q":"Look at the graphic. Which port does the speaker say lacks the necessary cranes?","choices":["Port Weston","Carlton Bay","Eastgate","Southmoor"],"answer":2,"type":"시각 자료 연계","explanation":"화자가 평소 \"about a day\"면 처리하던 항구의 대기 시간이 \"rise sixfold\"했다고 했다. 표에서 지난달 1일에서 이번 주 6일이 된 곳은 이스트게이트다. 포트 웨스턴은 파업이 일어난 항구다."},{"q":"What will be different about Thursday's talks?","choices":["Retailers will join the discussion.","They will be broadcast live.","They will be held at a new location.","A third party will take part."],"answer":3,"type":"세부 사항","explanation":"화자가 \"with a government mediator present for the first time\"이라고 했으므로 처음으로 정부 중재자, 즉 제3자가 참여한다."}],"translation":"경제 소식입니다. 포트 웨스턴 항만 노동자들의 파업이 오늘로 2주째에 접어들면서 그 여파가 퍼지고 있습니다. 해운사들은 선박을 인근 항구로 돌리고 있지만, 모든 항구가 늘어난 물량을 처리할 설비를 갖춘 것은 아닙니다. 특히 평소 하루 정도면 컨테이너를 처리하던 한 항구는 대형 선박에 필요한 크레인이 없어 대기 시간이 여섯 배로 늘었습니다. 소매업체들은 이 지연으로 연말 성수기를 앞두고 매장 진열대가 비게 될 수 있다고 경고합니다. 노조와 항만 경영진 간의 협상은 목요일에 재개되며, 처음으로 정부 중재자가 참석합니다. 분석가들은 이번 주에 합의가 이뤄지더라도 밀린 물량을 해소하는 데 약 한 달이 걸릴 것이라고 말합니다.","part":4},{"id":"p4-048","level":5,"topic":"미술관 건물 건축 투어","talk_type":"관광·견학 안내","voice":"female","script":"Good afternoon, and welcome to the Calloway Center's architecture tour. Most visitors come here for the art, but the building itself has quite a story. When it was completed in 1968, critics called it cold and unwelcoming, largely because of the concrete exterior you walked past on your way in. In fact, there was a serious proposal in the nineties to tear it down. What saved it was a public campaign led, interestingly, by the same newspaper that had criticized it thirty years earlier. As we move through the galleries, notice how the skylights are angled to keep direct sunlight off the paintings. That detail was so far ahead of its time that it's now standard in museum design. We'll end on the roof terrace, which reopened last month after being closed for over a decade.","graphic":null,"questions":[{"q":"What does the speaker say about the building's early reputation?","choices":["It was admired for its skylights.","It was poorly received.","It won several design awards.","It was considered too expensive."],"answer":1,"type":"세부 사항","explanation":"화자가 \"critics called it cold and unwelcoming\"이라고 했으므로 처음에는 평이 나빴다. 천창은 지금 높이 평가받는 요소이지 처음부터 칭찬받았다는 말은 없다."},{"q":"What is surprising about the campaign to save the building?","choices":["It was led by an organization that had once criticized the building.","It was funded mainly by artists.","It was organized by the original architect.","It began before the building was finished."],"answer":0,"type":"세부 사항","explanation":"화자가 \"interestingly, by the same newspaper that had criticized it thirty years earlier\"라고 했다. 30년 전에 건물을 비판했던 신문사가 보존 운동을 이끈 것이 흥미로운 점이다."},{"q":"What is mentioned about the skylights?","choices":["They were added in the nineties.","They will be replaced soon.","They let direct sunlight onto the paintings.","Their design influenced later museums."],"answer":3,"type":"세부 사항","explanation":"화자가 \"it's now standard in museum design\"이라고 했으므로 이후 미술관 설계에 영향을 주었다. 천창은 오히려 직사광선이 그림에 닿지 않도록 각도를 맞췄다."}],"translation":"안녕하세요, 캘러웨이 센터 건축 투어에 오신 것을 환영합니다. 대부분의 방문객은 미술 작품을 보러 오시지만, 이 건물 자체에도 꽤 긴 이야기가 있습니다. 1968년 완공 당시 비평가들은 이 건물을 차갑고 불친절하다고 평했는데, 주로 여러분이 들어오면서 지나친 콘크리트 외관 때문이었습니다. 실제로 90년대에는 건물을 허물자는 제안이 진지하게 나오기도 했습니다. 건물을 구한 것은 시민 운동이었는데, 흥미롭게도 그 운동을 이끈 곳은 30년 전에 이 건물을 비판했던 바로 그 신문사였습니다. 전시실을 지나가면서 천창이 그림에 직사광선이 닿지 않도록 각도가 맞춰져 있는 것을 보십시오. 이 설계는 시대를 크게 앞서 있어 지금은 미술관 설계의 표준이 되었습니다. 투어는 10년 넘게 닫혀 있다가 지난달 다시 문을 연 옥상 테라스에서 마치겠습니다.","part":4},{"id":"p4-049","level":5,"topic":"데이터 분석 컨설팅 광고","talk_type":"광고","voice":"male","script":"Your company has the data. Sales figures, customer feedback, supply costs, it's all there. So why do decisions still come down to whoever argues loudest in the meeting? At Clearline Analytics, we don't sell software. You probably have plenty already. Instead, our analysts work alongside your managers for twelve weeks, building the reports they'll actually use and teaching them to read the numbers themselves. When we leave, the skills stay. Last year, a regional grocery chain we worked with cut its food waste by eighteen percent simply by reorganizing its delivery schedule based on data it had been collecting for years. Visit clearline.com to read the full case study and book a free two-hour workshop for your leadership team.","graphic":null,"questions":[{"q":"What problem does the speaker describe?","choices":["Meetings take too long.","Decisions are not based on available information.","Companies do not collect enough data about their customers.","Software is too expensive."],"answer":1,"type":"주제·목적","explanation":"화자가 \"Your company has the data ... So why do decisions still come down to whoever argues loudest\"라고 했다. 데이터가 있는데도 결정에 활용하지 않는 것이 문제다. 데이터가 부족하다는 것은 정반대의 오답이다."},{"q":"Why does the speaker say, \"You probably have plenty already\"?","choices":["To praise the quality of listeners' current software products","To apologize for a limited product range","To suggest that buying more tools is not the solution","To announce a discount on software"],"answer":2,"type":"의도 파악","explanation":"\"we don't sell software\"에 이어 한 말로, 소프트웨어는 이미 충분하니 도구를 더 사는 것이 답이 아니라는 뜻이다. 이어서 분석가가 관리자와 함께 일하며 역량을 길러 준다는 차별점을 내세운다."},{"q":"What can listeners book on the Web site?","choices":["A free session for company executives","A discounted twelve-week consultation","A software demonstration","A meeting with a grocery chain"],"answer":0,"type":"세부 사항","explanation":"화자가 \"book a free two-hour workshop for your leadership team\"이라고 했다. leadership team을 company executives로 바꿔 표현했다. 12주는 본 서비스 기간이며 할인한다는 말은 없다."}],"translation":"귀사에는 데이터가 있습니다. 판매 수치, 고객 의견, 조달 비용, 전부 다 있죠. 그런데 왜 결정은 여전히 회의에서 가장 목소리 큰 사람에게 달려 있을까요? 클리어라인 애널리틱스는 소프트웨어를 팔지 않습니다. 아마 이미 충분히 갖고 계실 테니까요. 대신 저희 분석가들이 12주 동안 귀사 관리자들과 함께 일하며 실제로 쓰게 될 보고서를 만들고, 관리자들이 직접 수치를 읽는 법을 가르칩니다. 저희가 떠나도 역량은 남습니다. 작년에 저희와 함께한 한 지역 식료품 체인은 수년간 모아 온 데이터를 바탕으로 배송 일정만 재편해 음식 폐기량을 18퍼센트 줄였습니다. clearline.com을 방문해 사례 전문을 읽어 보시고, 경영진을 위한 두 시간짜리 무료 워크숍을 예약하세요.","part":4},{"id":"p4-050","level":5,"topic":"경기 지연에 따른 경기장 귀가 교통 안내","talk_type":"안내 방송","voice":"female","script":"Attention, fans. Because of this evening's weather delay, tonight's game is now expected to end around eleven thirty. Please plan your trip home accordingly. Because of the late finish, several transit options will not be available after the game, and the city has agreed to extend only one of them: the service that normally makes its last departure at eleven forty will run until one a.m. tonight. The East Pier is also closed tonight due to high water, so that option isn't available at all. If you parked in the South Lot, please note that the exit onto Stadium Drive will be closed after the game. Please use the River Road exit instead. Thank you, and enjoy the rest of the game.","graphic":{"title":"Post-Game Transit Options","rows":[["Option","Location","Last Departure"],["Blue Line Train","North Gate","11:40 P.M."],["Express Bus 12","West Plaza","11:15 P.M."],["Park-and-Ride Shuttle","South Lot","12:30 A.M."],["Water Taxi","East Pier","11:00 P.M."]]},"questions":[{"q":"Why will the game end later than usual?","choices":["A ceremony was added.","There was a power outage.","It went into extra time after a tie score.","It was delayed by weather."],"answer":3,"type":"세부 사항","explanation":"화자가 \"Because of this evening's weather delay\"라고 했으므로 날씨로 경기가 지연됐기 때문이다."},{"q":"Look at the graphic. Where should fans go to use the extended service?","choices":["East Pier","North Gate","West Plaza","South Lot"],"answer":1,"type":"시각 자료 연계","explanation":"연장 운행하는 것은 \"the service that normally makes its last departure at eleven forty\"라고 했다. 표에서 막차가 11시 40분인 것은 블루 라인 열차로 North Gate에서 탄다. East Pier는 오늘 밤 폐쇄된 곳이다."},{"q":"What are drivers who parked in the South Lot advised to do?","choices":["Leave before the game ends","Park on River Road","Leave by a different exit","Take the shuttle instead"],"answer":2,"type":"요청·제안","explanation":"화자가 스타디움 드라이브 쪽 출구가 닫힌다며 \"Please use the River Road exit instead.\"라고 했다. 리버 로드는 주차 장소가 아니라 이용할 출구다."}],"translation":"팬 여러분께 알려 드립니다. 오늘 저녁 기상 악화로 경기가 지연되어, 오늘 밤 경기는 11시 30분쯤 끝날 것으로 예상됩니다. 귀가 계획을 그에 맞게 세워 주십시오. 경기가 늦게 끝나 몇몇 교통수단은 경기 후 이용할 수 없으며, 시에서는 그중 하나만 연장 운행하기로 했습니다. 평소 막차가 11시 40분인 교통수단이 오늘 밤에는 새벽 1시까지 운행합니다. 동쪽 부두도 오늘 밤 수위가 높아 폐쇄되어 그 교통수단은 아예 이용할 수 없습니다. 남쪽 주차장에 주차하셨다면 경기 후 스타디움 드라이브 쪽 출구가 닫힌다는 점에 유의하십시오. 대신 리버 로드 쪽 출구를 이용해 주십시오. 감사합니다. 남은 경기 즐기십시오.","part":4},{"id":"p4-051","level":1,"topic":"도서관 예약 도서 도착 알림 전화","talk_type":"전화 메시지","voice":"female","script":"Hello, this is Karen from the Riverside Public Library. I'm calling for Mr. David Park. The book you asked for, The Garden Cookbook, has arrived. We will keep it for you at the front desk for one week, so please pick it up by next Friday. Please bring your library card with you. Also, the library will be closed this Monday because of a holiday. On other weekdays, we are open from nine a.m. to seven p.m. If you have any questions, please call us at 555-0142. Thank you, and have a nice day.","graphic":null,"questions":[{"q":"Why is the speaker calling?","choices":["To ask for a late fee","To change a meeting time","To say that a book is ready","To invite the listener to an event"],"answer":2,"type":"주제·목적","explanation":"화자가 “The book you asked for ... has arrived.”라고 하며 신청한 책이 도착했다고 알린다. 연체료나 행사, 회의 시간 이야기는 나오지 않는다."},{"q":"What should the listener bring?","choices":["A library card","Some money","A receipt","A shopping bag"],"answer":0,"type":"세부 사항","explanation":"“Please bring your library card with you.”라고 했으므로 도서관 카드를 가져와야 한다. 영수증·돈·가방은 언급되지 않았다."},{"q":"When will the library be closed?","choices":["On Saturday","On Friday","On Monday","On Sunday"],"answer":2,"type":"세부 사항","explanation":"“the library will be closed this Monday because of a holiday”라고 했다. 금요일은 책을 찾아가야 하는 기한이다."}],"translation":"안녕하세요, 리버사이드 공공 도서관의 캐런입니다. 데이비드 박 씨께 전화드렸습니다. 신청하신 책 『가든 쿡북』이 도착했습니다. 안내 데스크에서 일주일 동안 보관해 드리니 다음 주 금요일까지 찾아가 주세요. 도서관 카드를 꼭 가지고 오세요. 그리고 이번 월요일은 공휴일이라 도서관이 문을 닫습니다. 다른 평일에는 오전 9시부터 오후 7시까지 엽니다. 궁금한 점이 있으시면 555-0142로 전화 주세요. 감사합니다. 좋은 하루 보내세요.","part":4},{"id":"p4-052","level":1,"topic":"사무실 건물 엘리베이터 점검 안내","talk_type":"안내 방송","voice":"male","script":"Good morning, everyone. This is an announcement from the building manager. Today, workers will check the elevators on the east side of the building. The work will start at ten a.m. and finish at about two p.m. The work may be a little noisy. During this time, please use the elevators on the west side, near the main entrance. You can also use the stairs. If you need to move heavy boxes today, please call the front desk, and we will help you. We are sorry for the trouble, and thank you for your understanding.","graphic":null,"questions":[{"q":"Who most likely is the speaker?","choices":["A building manager","A delivery driver for the building","A bus driver","A hotel guest"],"answer":0,"type":"화자 정보(직업·장소)","explanation":"“This is an announcement from the building manager.”라고 했으므로 화자는 건물 관리자다. 배달 기사나 버스 기사에 대한 단서는 없다."},{"q":"What will happen at ten a.m.?","choices":["Boxes will be delivered.","The building will close.","A meeting will start.","Elevator work will begin."],"answer":3,"type":"세부 사항","explanation":"“The work will start at ten a.m.”라고 했으므로 오전 10시에 엘리베이터 점검 작업이 시작된다. 건물이 닫는다는 말은 없다."},{"q":"What should listeners do if they need to move heavy boxes?","choices":["Ask a coworker","Use the stairs","Call the front desk","Wait until tomorrow"],"answer":2,"type":"요청·제안","explanation":"“If you need to move heavy boxes today, please call the front desk”라고 했다. 계단 이용은 엘리베이터 대신 쓸 수 있는 방법으로 말한 것이지 무거운 상자에 대한 안내가 아니다."}],"translation":"안녕하세요, 여러분. 건물 관리자가 알려 드립니다. 오늘 작업자들이 건물 동쪽 엘리베이터를 점검합니다. 작업은 오전 10시에 시작해서 오후 2시쯤 끝납니다. 작업 중에 조금 시끄러울 수 있습니다. 이 시간 동안에는 정문 근처 서쪽 엘리베이터를 이용해 주세요. 계단을 이용하셔도 됩니다. 오늘 무거운 상자를 옮겨야 하시면 안내 데스크로 전화 주세요. 도와 드리겠습니다. 불편을 드려 죄송하며 이해해 주셔서 감사합니다.","part":4},{"id":"p4-053","level":1,"topic":"탕비실 새 커피 머신 설치 안내","talk_type":"회의 발췌","voice":"female","script":"Before we start today's meeting, I have some good news. We have a new coffee machine in the kitchen. It arrived yesterday, and it can make coffee, tea, and hot chocolate. It's very easy to use. Just put in a cup and press a button. It also uses less power than the old one. But please remember one thing. After you use it, clean the area around the machine. The cups are in the cabinet above the sink. Next week, we will also get some cold drinks for the refrigerator. OK, now let's talk about the sales report.","graphic":null,"questions":[{"q":"What is the speaker mainly talking about?","choices":["A kitchen renovation","A new machine in the kitchen","A sales report","A new employee"],"answer":1,"type":"주제·목적","explanation":"“We have a new coffee machine in the kitchen.”이라며 새 커피 머신을 소개하는 내용이 중심이다. 판매 보고서는 마지막에 다음 안건으로만 나온다."},{"q":"What does the speaker ask listeners to do?","choices":["Buy some tea","Bring their own cups","Turn off the machine","Keep the area clean"],"answer":3,"type":"요청·제안","explanation":"“After you use it, clean the area around the machine.”이라고 부탁했다. 컵은 싱크대 위 찬장에 있다고 했으므로 가져올 필요가 없다."},{"q":"What will the listeners most likely do next?","choices":["Go to a store","Discuss a sales report","Clean the kitchen","Have some coffee"],"answer":1,"type":"다음 할 일","explanation":"마지막에 “now let's talk about the sales report.”라고 했으므로 이어서 판매 보고서를 논의할 것이다."}],"translation":"오늘 회의를 시작하기 전에 좋은 소식이 있어요. 탕비실에 새 커피 머신이 생겼어요. 어제 도착했는데 커피, 차, 핫초코를 만들 수 있어요. 사용법도 아주 쉬워요. 컵을 넣고 버튼만 누르면 돼요. 예전 것보다 전기도 덜 써요. 하지만 한 가지는 꼭 기억해 주세요. 사용한 뒤에는 머신 주변을 깨끗이 닦아 주세요. 컵은 싱크대 위 찬장에 있어요. 다음 주에는 냉장고에 넣을 시원한 음료도 들어올 거예요. 자, 이제 판매 보고서 이야기를 해 봅시다.","part":4},{"id":"p4-054","level":1,"topic":"세탁소 이달의 할인 광고","talk_type":"광고","voice":"male","script":"Are your clothes dirty after a long week? Come to Fresh Clean Laundry on Main Street! We wash and iron your clothes, and they are ready the next day. We are open every day from seven a.m. to nine p.m., so you can visit before or after work. This month, we have a special offer. Bring in any jacket, and we will clean it for half price. We also pick up and deliver clothes for free if you live near Main Street. Just call us or visit our Web site. Fresh Clean Laundry. Clean clothes, happy you!","graphic":{"title":"Fresh Clean Laundry Price List","rows":[["Item","Price"],["Shirt","$3"],["Pants","$5"],["Jacket","$8"],["Coat","$12"]]},"questions":[{"q":"What is being advertised?","choices":["A laundry service","A car wash","A hotel","A clothing store"],"answer":0,"type":"주제·목적","explanation":"“Come to Fresh Clean Laundry”, “We wash and iron your clothes”라고 했으므로 세탁 서비스 광고다. 옷을 파는 가게가 아니다."},{"q":"When will clothes be ready?","choices":["In one hour","On weekends","In one week","The next day"],"answer":3,"type":"세부 사항","explanation":"“they are ready the next day”라고 했으므로 다음 날 찾을 수 있다."},{"q":"Look at the graphic. How much will it cost to clean a jacket this month?","choices":["$6","$3","$8","$4"],"answer":3,"type":"시각 자료 연계","explanation":"이달에는 재킷을 “half price”(반값)에 세탁해 준다고 했다. 표에서 재킷은 8달러이므로 반값인 4달러다. 8달러는 원래 가격이다."}],"translation":"긴 한 주를 보내고 옷이 더러워졌나요? 메인 스트리트의 프레시 클린 세탁소로 오세요! 옷을 세탁하고 다림질해 드리며, 다음 날 찾아가실 수 있습니다. 매일 오전 7시부터 오후 9시까지 열기 때문에 출근 전이나 퇴근 후에 들르실 수 있습니다. 이번 달에는 특별 할인이 있습니다. 재킷을 가져오시면 어떤 재킷이든 반값에 세탁해 드립니다. 메인 스트리트 근처에 사시면 옷을 무료로 가지러 가고 배달도 해 드립니다. 전화 주시거나 웹사이트를 방문하세요. 프레시 클린 세탁소. 깨끗한 옷, 행복한 당신!","part":4},{"id":"p4-055","level":1,"topic":"시민 마라톤 도로 통제 지역 뉴스","talk_type":"방송·뉴스","voice":"female","script":"Good morning. This is Radio 98 with the local news. This Sunday, the City Marathon will take place downtown. About five thousand runners are going to join the race. Because of the marathon, Park Avenue and River Road will be closed from six a.m. to one p.m. Buses will not stop on those roads during that time. If you need to go downtown, please take the subway. The race will start in front of City Hall at seven a.m. People can watch the runners along the river. Now, let's take a look at the weather.","graphic":null,"questions":[{"q":"What event will take place on Sunday?","choices":["A boat show","A running race","A music festival","A bicycle race"],"answer":1,"type":"세부 사항","explanation":"“This Sunday, the City Marathon will take place downtown.”이라고 했으므로 달리기 대회(마라톤)가 열린다. 자전거 경주가 아니다."},{"q":"What does the speaker suggest listeners do?","choices":["Drive on River Road","Leave home early","Take the subway","Buy tickets online"],"answer":2,"type":"요청·제안","explanation":"“If you need to go downtown, please take the subway.”라고 권했다. 리버 로드는 통제되는 도로다."},{"q":"What will listeners hear next?","choices":["A weather report","Some music","A sports interview","An advertisement"],"answer":0,"type":"다음 할 일","explanation":"마지막에 “Now, let's take a look at the weather.”라고 했으므로 이어서 날씨 정보가 나온다."}],"translation":"안녕하세요. 라디오 98 지역 뉴스입니다. 이번 일요일 시내에서 시민 마라톤 대회가 열립니다. 약 5천 명의 선수가 참가할 예정입니다. 마라톤 때문에 파크 애비뉴와 리버 로드가 오전 6시부터 오후 1시까지 통제됩니다. 그 시간 동안 버스는 이 도로에 정차하지 않습니다. 시내에 가셔야 하면 지하철을 이용해 주세요. 경주는 오전 7시에 시청 앞에서 출발합니다. 강을 따라 선수들을 구경하실 수 있습니다. 이제 날씨를 알아보겠습니다.","part":4},{"id":"p4-056","level":1,"topic":"점심 모임 신입 디자이너 소개","talk_type":"연설·소개","voice":"male","script":"Hi, everyone. Thank you for coming to lunch today. I'd like to introduce a new member of our team, Maria Lopez. Maria is joining us as a graphic designer. Before this, she worked at a small magazine for three years. She will help us with our posters and Web pages. She also loves taking photos, so ask her about her pictures sometime. Maria's desk is next to the window, near mine. Please stop by and say hello to her this afternoon. Maria, we're very happy to have you here. Now, let's enjoy our lunch. The pizza is here!","graphic":null,"questions":[{"q":"What is the purpose of the talk?","choices":["To explain a new project","To order lunch","To announce a retirement","To introduce a new employee"],"answer":3,"type":"주제·목적","explanation":"“I'd like to introduce a new member of our team, Maria Lopez.”라고 했으므로 신입 직원을 소개하는 것이 목적이다."},{"q":"Where did Maria work before?","choices":["At a photo studio","At a bakery","At a school","At a magazine"],"answer":3,"type":"세부 사항","explanation":"“Before this, she worked at a small magazine for three years.”라고 했다. 사진은 취미로 언급됐을 뿐 사진관에서 일한 것은 아니다."},{"q":"What are listeners asked to do?","choices":["Say hello to Maria","Make some posters","Move their desks","Bring some pizza"],"answer":0,"type":"요청·제안","explanation":"“Please stop by and say hello to her this afternoon.”이라고 부탁했다. 피자는 이미 도착했다."}],"translation":"안녕하세요, 여러분. 오늘 점심 자리에 와 주셔서 고맙습니다. 우리 팀의 새 식구 마리아 로페즈 씨를 소개하겠습니다. 마리아 씨는 그래픽 디자이너로 함께하게 됐습니다. 이전에는 작은 잡지사에서 3년 동안 일했습니다. 우리 포스터와 웹페이지 작업을 도와줄 겁니다. 사진 찍는 것도 아주 좋아하니 언제 사진 이야기를 물어보세요. 마리아 씨 자리는 창가, 제 자리 근처입니다. 오늘 오후에 들러서 인사해 주세요. 마리아 씨, 함께하게 돼서 정말 기쁩니다. 자, 이제 점심을 즐깁시다. 피자가 왔어요!","part":4},{"id":"p4-057","level":1,"topic":"수족관 가이드 투어","talk_type":"관광·견학 안내","voice":"female","script":"Welcome to the Blue Ocean Aquarium. My name is Sara, and I'll be your guide today. Our tour will take about one hour. First, we'll see the big fish tank on the first floor. Then we'll go upstairs to see the sea turtles. At eleven o'clock, you can watch our staff feed the penguins. Please don't take photos with a flash, because the light can hurt the animals. Also, food and drinks are not allowed inside. After the tour, you can visit our gift shop near the exit. OK, please follow me.","graphic":null,"questions":[{"q":"Where are the listeners?","choices":["At an aquarium","At an art museum","At a farm","At a pet store"],"answer":0,"type":"화자 정보(직업·장소)","explanation":"“Welcome to the Blue Ocean Aquarium.”이라고 했고 물고기 수조, 바다거북, 펭귄이 나오므로 수족관이다."},{"q":"What will happen at eleven o'clock?","choices":["The gift shop will open.","Penguins will be fed.","The tour will end.","A movie will start."],"answer":1,"type":"세부 사항","explanation":"“At eleven o'clock, you can watch our staff feed the penguins.”라고 했으므로 11시에 펭귄 먹이 주기가 있다."},{"q":"What are listeners asked not to do?","choices":["Use a flash when taking photos","Visit the gift shop","Touch the fish tank","Talk loudly near the sea turtles"],"answer":0,"type":"요청·제안","explanation":"“Please don't take photos with a flash”라고 했다. 기념품 가게는 투어 후에 가 보라고 권한 곳이다."}],"translation":"블루 오션 수족관에 오신 것을 환영합니다. 저는 오늘 여러분을 안내할 사라입니다. 투어는 약 1시간 걸립니다. 먼저 1층의 큰 물고기 수조를 보겠습니다. 그다음 위층으로 올라가 바다거북을 보겠습니다. 11시에는 직원들이 펭귄에게 먹이를 주는 모습을 보실 수 있습니다. 빛이 동물들에게 해로울 수 있으니 플래시를 켜고 사진을 찍지 마세요. 또한 안에서는 음식과 음료를 드실 수 없습니다. 투어가 끝나면 출구 근처 기념품 가게에 들르셔도 됩니다. 자, 저를 따라오세요.","part":4},{"id":"p4-058","level":2,"topic":"사무용품 주문 품절 안내 전화","talk_type":"전화 메시지","voice":"male","script":"Hi, Ms. Robinson. This is Tom Baker from Office Plus Supplies. I'm calling about the order you placed on Tuesday. You ordered twenty boxes of printer paper, ten packs of pens, and five desk lamps. Unfortunately, the desk lamps are out of stock right now, and we won't get more until the end of the month. We'll deliver the paper and pens tomorrow morning as planned. For the lamps, we can either send you a similar model that costs a little more, or we can give you a refund. Please call me back at 555-0198 and let me know which you prefer. Thanks.","graphic":null,"questions":[{"q":"Where does the speaker most likely work?","choices":["At a bank","At a print shop","At an office supply company","At a furniture factory"],"answer":2,"type":"화자 정보(직업·장소)","explanation":"“This is Tom Baker from Office Plus Supplies.”라고 했고 프린터 용지·펜·스탠드 주문을 다루므로 사무용품 회사 직원이다."},{"q":"What problem does the speaker mention?","choices":["A payment was declined by the bank.","An order was delivered late.","The wrong address was given.","Some items are not available."],"answer":3,"type":"세부 사항","explanation":"“the desk lamps are out of stock right now”라고 했으므로 일부 품목이 품절된 것이 문제다. 용지와 펜은 예정대로 배송된다."},{"q":"What does the speaker ask the listener to do?","choices":["Pick up an order","Choose between two options","Cancel an order","Pay an extra fee for faster delivery"],"answer":1,"type":"요청·제안","explanation":"비슷한 다른 모델을 보내거나 환불해 주겠다고 한 뒤 “let me know which you prefer”라고 했으므로 두 가지 중 하나를 골라 달라는 요청이다."}],"translation":"안녕하세요, 로빈슨 씨. 오피스 플러스 서플라이즈의 톰 베이커입니다. 화요일에 하신 주문 건으로 전화드렸습니다. 프린터 용지 20상자, 펜 10팩, 책상 스탠드 5개를 주문하셨는데요. 안타깝게도 책상 스탠드가 지금 품절이라 이달 말까지는 재입고가 되지 않습니다. 용지와 펜은 예정대로 내일 오전에 배송해 드리겠습니다. 스탠드는 가격이 조금 더 비싼 비슷한 모델을 보내 드리거나 환불해 드릴 수 있습니다. 555-0198로 다시 전화 주셔서 어느 쪽이 좋으신지 알려 주세요. 감사합니다.","part":4},{"id":"p4-059","level":2,"topic":"버스 터미널 탑승 게이트 변경","talk_type":"안내 방송","voice":"female","script":"Attention, passengers. This is an announcement for everyone traveling to Lakeside this morning. Because the floor near Gate Four is being repaired, the Lakeside bus will not leave from its usual gate today. Instead, it will depart from the gate used by the Oak Bay bus. The Oak Bay service has been canceled today because of road construction, so that gate is free. The departure time has not changed. Also, please remember that each passenger may bring one large suitcase and one small bag. Extra bags must be checked at the ticket counter. Thank you for traveling with Star Line Buses.","graphic":{"title":"Star Line Buses Morning Departures","rows":[["Destination","Gate","Time"],["Greenville","3","10:15"],["Lakeside","4","10:30"],["Hillsdale","5","10:45"],["Oak Bay","6","11:00"]]},"questions":[{"q":"Why is the usual gate unavailable?","choices":["It is too crowded with Oak Bay passengers.","A bus has broken down.","The door is locked.","The floor is being repaired."],"answer":3,"type":"세부 사항","explanation":"“Because the floor near Gate Four is being repaired”라고 했으므로 바닥 수리 때문이다."},{"q":"Look at the graphic. Which gate will the Lakeside bus depart from?","choices":["Gate 5","Gate 4","Gate 6","Gate 3"],"answer":2,"type":"시각 자료 연계","explanation":"레이크사이드행 버스는 “the gate used by the Oak Bay bus”에서 출발한다고 했다. 표에서 오크 베이행 버스의 게이트는 6번이다. 4번은 원래 게이트다."},{"q":"What should passengers with extra bags do?","choices":["Check them at the ticket counter","Leave them at the gate","Carry them onto the bus","Pay a fee online"],"answer":0,"type":"요청·제안","explanation":"“Extra bags must be checked at the ticket counter.”라고 했으므로 매표소에서 부쳐야 한다."}],"translation":"승객 여러분께 알려 드립니다. 오늘 아침 레이크사이드로 가시는 모든 분께 드리는 안내입니다. 4번 게이트 근처 바닥을 수리하고 있어서 레이크사이드행 버스는 오늘 평소 게이트에서 출발하지 않습니다. 대신 오크 베이행 버스가 쓰는 게이트에서 출발합니다. 오크 베이행 운행은 도로 공사 때문에 오늘 취소되어 그 게이트가 비어 있습니다. 출발 시간은 바뀌지 않았습니다. 또한 승객 한 분당 큰 여행 가방 하나와 작은 가방 하나를 가져가실 수 있다는 점을 기억해 주세요. 추가 가방은 매표소에서 부치셔야 합니다. 스타 라인 버스를 이용해 주셔서 감사합니다.","part":4},{"id":"p4-060","level":2,"topic":"사무실 이전 짐 싸기 안내","talk_type":"회의 발췌","voice":"male","script":"OK, everyone, just a quick update on our move to the new office. As you know, we're moving to the fifth floor of the Harper Building next Monday. The moving company will come on Friday afternoon, so all of your things need to be packed by Friday at noon. You'll find empty boxes in the storage room. Please write your name and desk number on every box. Now, I know some of you have a lot of files. Well, the new office has less storage space. So if you haven't looked at some papers in years, think about whether you really need them. Any questions?","graphic":null,"questions":[{"q":"What is the talk mainly about?","choices":["Hiring a moving company for next week","Preparing for an office move","Planning a team event","Renovating a storage room"],"answer":1,"type":"주제·목적","explanation":"“just a quick update on our move to the new office”로 시작해 짐 싸는 기한과 방법을 안내하므로 사무실 이전 준비가 주제다."},{"q":"By when must employees pack their things?","choices":["Monday morning","Friday at noon","Thursday afternoon","Friday evening"],"answer":1,"type":"세부 사항","explanation":"“all of your things need to be packed by Friday at noon”이라고 했다. 월요일은 이사하는 날, 금요일 오후는 이삿짐 업체가 오는 때다."},{"q":"What does the speaker imply when he says, \"the new office has less storage space\"?","choices":["The move will be delayed.","Some employees will work at another building.","More boxes will be ordered.","Employees should throw away some papers."],"answer":3,"type":"의도 파악","explanation":"바로 뒤에 “if you haven't looked at some papers in years, think about whether you really need them”이라고 했으므로 필요 없는 서류는 정리해서 버리라는 뜻이다."}],"translation":"자, 여러분, 새 사무실 이전에 대해 간단히 알려 드릴게요. 아시다시피 다음 주 월요일에 하퍼 빌딩 5층으로 이사합니다. 이삿짐 업체가 금요일 오후에 오니까 모든 짐은 금요일 정오까지 싸 두셔야 합니다. 빈 상자는 창고에 있어요. 상자마다 이름과 자리 번호를 적어 주세요. 그리고 서류가 많은 분들이 계신 걸 압니다. 그런데 새 사무실은 수납 공간이 더 적어요. 그러니 몇 년 동안 들여다보지 않은 서류가 있다면 정말 필요한지 생각해 보세요. 질문 있으세요?","part":4},{"id":"p4-061","level":2,"topic":"가정 청소 서비스 광고","talk_type":"광고","voice":"female","script":"Too busy to clean your home? Let Sparkle Home Services do it for you! Our trained cleaners will clean your kitchen, bathrooms, and floors while you're at work. We bring all of our own supplies, and we only use products that are safe for children and pets. You can book a one-time cleaning or choose a weekly plan. Weekly customers save fifteen percent on every visit. And right now, new customers get their first cleaning for just thirty dollars. To book, simply download our mobile app and choose a time that works for you. Sparkle Home Services. We make your home shine.","graphic":null,"questions":[{"q":"What is being advertised?","choices":["A moving company for small offices","A home cleaning service","A cleaning product","A pet store"],"answer":1,"type":"주제·목적","explanation":"“Our trained cleaners will clean your kitchen, bathrooms, and floors”라고 했으므로 집 청소 서비스 광고다. 세제 같은 제품을 파는 것이 아니다."},{"q":"What does the speaker say about the products the company uses?","choices":["They have no smell.","They are safe for children and pets.","They are made locally.","They are sold in stores."],"answer":1,"type":"세부 사항","explanation":"“we only use products that are safe for children and pets”라고 했다."},{"q":"How can listeners make a booking?","choices":["By sending an e-mail","By visiting an office","By calling a hotline","By using a mobile app"],"answer":3,"type":"세부 사항","explanation":"“To book, simply download our mobile app”이라고 했으므로 모바일 앱으로 예약한다."}],"translation":"너무 바빠서 집 청소할 시간이 없으신가요? 스파클 홈 서비스에 맡기세요! 교육받은 청소 직원이 여러분이 출근한 동안 주방, 욕실, 바닥을 청소해 드립니다. 청소 도구와 세제는 모두 저희가 가져가며, 아이와 반려동물에게 안전한 제품만 사용합니다. 1회 청소를 예약하시거나 주간 요금제를 선택하실 수 있습니다. 주간 고객은 매번 15퍼센트를 절약합니다. 그리고 지금 신규 고객은 첫 청소를 단 30달러에 받으실 수 있습니다. 예약하시려면 모바일 앱을 내려받아 편한 시간을 고르기만 하세요. 스파클 홈 서비스. 여러분의 집을 빛나게 해 드립니다.","part":4},{"id":"p4-062","level":2,"topic":"농산물 직거래 장터 개장 지역 뉴스","talk_type":"방송·뉴스","voice":"male","script":"And in local news, the Westfield Farmers Market will open for the season this Saturday at Central Square. More than forty farmers will be selling fresh vegetables, fruit, eggs, and honey. This year, the market will also have a small area for local bakers and cheese makers. The market will run every Saturday from eight a.m. to one p.m. until the end of October. Last year, parking was a big problem. This year, the city has opened the lot behind the library for market visitors. Organizers say the best items sell out early, so come before ten if you can.","graphic":null,"questions":[{"q":"What is new at the market this year?","choices":["Live music","Longer opening hours","A new location","An area for bakers and cheese makers"],"answer":3,"type":"세부 사항","explanation":"“This year, the market will also have a small area for local bakers and cheese makers.”라고 했다. 장소와 시간이 바뀌었다는 말은 없다."},{"q":"Why does the speaker say, \"Last year, parking was a big problem\"?","choices":["To explain why a parking area has been added","To suggest that the market should move to a new location","To warn that visitors cannot drive","To complain about the city"],"answer":0,"type":"의도 파악","explanation":"바로 뒤에 “This year, the city has opened the lot behind the library for market visitors.”라고 했으므로 올해 주차장을 새로 마련한 이유를 설명하려는 말이다."},{"q":"What do the organizers recommend?","choices":["Ordering online","Bringing cash","Arriving early","Taking a bus"],"answer":2,"type":"요청·제안","explanation":"“the best items sell out early, so come before ten if you can”이라고 했으므로 일찍 오라고 권한다."}],"translation":"지역 소식입니다. 웨스트필드 농산물 장터가 이번 토요일 센트럴 광장에서 올해 문을 엽니다. 40명이 넘는 농부들이 신선한 채소, 과일, 달걀, 꿀을 판매합니다. 올해는 지역 제빵사와 치즈 생산자를 위한 작은 구역도 마련됩니다. 장터는 10월 말까지 매주 토요일 오전 8시부터 오후 1시까지 열립니다. 작년에는 주차가 큰 문제였죠. 올해는 시에서 도서관 뒤 주차장을 장터 방문객에게 개방했습니다. 주최 측은 좋은 물건은 일찍 다 팔리니 가능하면 10시 전에 오라고 말합니다.","part":4},{"id":"p4-063","level":2,"topic":"주민센터 요리 교실 강사 소개","talk_type":"연설·소개","voice":"female","script":"Good evening, and welcome to the Community Center's spring cooking class. I'm Linda, the program coordinator. It's my pleasure to introduce tonight's teacher, Chef Antonio Russo. Chef Russo owns Bella Cucina, the Italian restaurant on Elm Street, and he has been cooking for more than twenty years. Tonight, he'll show you how to make fresh pasta by hand. Don't worry if you've never cooked before. This class is for beginners. You'll find an apron and all the ingredients at your table. At the end of the class, you can take home the pasta you make. Please give a warm welcome to Chef Russo.","graphic":null,"questions":[{"q":"Who is the speaker?","choices":["A food critic","A program coordinator","A cooking student","A restaurant owner"],"answer":1,"type":"화자 정보(직업·장소)","explanation":"“I'm Linda, the program coordinator.”라고 자신을 소개했다. 식당 주인은 소개받는 러소 셰프다."},{"q":"What will the listeners learn to make?","choices":["Bread","Pasta","Pizza","Soup"],"answer":1,"type":"세부 사항","explanation":"“he'll show you how to make fresh pasta by hand”라고 했으므로 파스타 만드는 법을 배운다."},{"q":"What can the listeners take home?","choices":["The food they make","A discount coupon","A recipe book written by the chef","An apron"],"answer":0,"type":"세부 사항","explanation":"“you can take home the pasta you make”라고 했으므로 직접 만든 음식을 가져갈 수 있다. 앞치마는 탁자에 준비돼 있다고만 했다."}],"translation":"안녕하세요, 주민센터 봄 요리 교실에 오신 것을 환영합니다. 저는 프로그램 담당자 린다입니다. 오늘 밤 강사이신 안토니오 러소 셰프님을 소개하게 되어 기쁩니다. 러소 셰프님은 엘름 스트리트의 이탈리아 식당 벨라 쿠치나의 주인이시고, 20년 넘게 요리를 해 오셨습니다. 오늘은 손으로 생파스타 만드는 법을 보여 주실 겁니다. 요리를 한 번도 해 보지 않으셨어도 걱정하지 마세요. 이 수업은 초보자를 위한 수업입니다. 탁자 위에 앞치마와 모든 재료가 준비되어 있습니다. 수업이 끝나면 직접 만든 파스타를 가져가실 수 있습니다. 러소 셰프님을 따뜻하게 맞아 주세요.","part":4},{"id":"p4-064","level":2,"topic":"식물원 가이드 투어 순서 변경","talk_type":"관광·견학 안내","voice":"male","script":"Good morning, and welcome to the Maple Hills Botanical Garden. I'm Greg, and I'll be showing you around today. We'll visit four gardens in about ninety minutes. Normally, we start at the Rose Garden, but a school group is there right now, so we'll begin with the second stop on the map and go back to the roses at the end. By the way, it gets very warm in the Tropical House, so you might want to take off your jackets before we go in. Also, please stay on the paths and don't pick any flowers. OK, if everyone has a map, let's get started.","graphic":{"title":"Maple Hills Botanical Garden Tour","rows":[["Stop","Garden"],["1","Rose Garden"],["2","Tropical House"],["3","Herb Garden"],["4","Japanese Garden"]]},"questions":[{"q":"Why has the tour order been changed?","choices":["A garden is closed for repairs this week.","Another group is at the first stop.","The tour is shorter today.","The weather is bad."],"answer":1,"type":"세부 사항","explanation":"“Normally, we start at the Rose Garden, but a school group is there right now”라고 했으므로 다른 단체가 첫 번째 장소에 있기 때문이다."},{"q":"Look at the graphic. Which garden will the listeners visit first?","choices":["Japanese Garden","Herb Garden","Rose Garden","Tropical House"],"answer":3,"type":"시각 자료 연계","explanation":"“we'll begin with the second stop on the map”이라고 했다. 표에서 2번 장소는 열대 온실(Tropical House)이다. 장미 정원은 마지막에 간다."},{"q":"What does the speaker suggest the listeners do?","choices":["Take some photos","Drink some water","Buy a map","Take off their jackets"],"answer":3,"type":"요청·제안","explanation":"열대 온실이 아주 덥다며 “you might want to take off your jackets before we go in”이라고 권했다."}],"translation":"안녕하세요, 메이플 힐스 식물원에 오신 것을 환영합니다. 저는 오늘 여러분을 안내할 그레그입니다. 약 90분 동안 네 개의 정원을 둘러보겠습니다. 보통은 장미 정원에서 시작하는데, 지금 그곳에 학교 단체가 있어서 지도의 두 번째 장소부터 시작하고 장미 정원은 마지막에 다시 가겠습니다. 그리고 열대 온실 안은 아주 더우니 들어가기 전에 재킷을 벗으시는 게 좋겠습니다. 또 길 위로만 다니시고 꽃은 꺾지 말아 주세요. 자, 모두 지도를 가지고 계시면 출발하겠습니다.","part":4},{"id":"p4-065","level":3,"topic":"물류창고 관리자 면접 일정 안내 전화","talk_type":"전화 메시지","voice":"female","script":"Hello, Mr. Chen. This is Hannah Wells from the human resources department at Brightline Logistics. Thank you for applying for our warehouse supervisor position. We were impressed with your application, and we'd like to invite you for an interview this Thursday. I've attached a schedule to the e-mail I sent you this morning. The morning slots have already been filled, and our operations director has a lunch meeting that might run late, so we've given you the last slot of the day. The interview will take about forty-five minutes, and you'll also be asked to complete a short written test. Please bring a copy of your forklift safety certificate. If Thursday doesn't work for you, call me at extension 214 by tomorrow afternoon.","graphic":{"title":"Interview Schedule: Thursday","rows":[["Time","Location"],["9:00 A.M.","Room 201"],["11:00 A.M.","Room 305"],["1:30 P.M.","Room 402"],["3:30 P.M.","Room 110"]]},"questions":[{"q":"Why is the speaker calling?","choices":["To confirm a delivery","To request a reference from a former employer","To offer a promotion","To arrange a job interview"],"answer":3,"type":"주제·목적","explanation":"지원에 감사하며 “we'd like to invite you for an interview this Thursday”라고 했으므로 채용 면접 일정을 잡으려는 전화다."},{"q":"Look at the graphic. Where will the listener's interview take place?","choices":["Room 110","Room 305","Room 402","Room 201"],"answer":0,"type":"시각 자료 연계","explanation":"오전은 이미 찼고 점심 회의가 길어질 수 있어서 “we've given you the last slot of the day”라고 했다. 표에서 마지막 시간인 오후 3시 30분은 110호다."},{"q":"What is the listener asked to bring?","choices":["A certificate","A photo ID","A copy of his resume","A reference letter"],"answer":0,"type":"요청·제안","explanation":"“Please bring a copy of your forklift safety certificate.”라고 했으므로 지게차 안전 자격증을 가져가야 한다."}],"translation":"안녕하세요, 첸 씨. 브라이트라인 물류 인사부의 해나 웰스입니다. 저희 창고 관리자 자리에 지원해 주셔서 감사합니다. 지원서가 인상적이어서 이번 목요일 면접에 모시고 싶습니다. 오늘 아침에 보내 드린 이메일에 일정표를 첨부했습니다. 오전 시간은 이미 다 찼고, 운영 이사님의 점심 회의가 늦게 끝날 수도 있어서 그날 마지막 시간으로 잡아 드렸습니다. 면접은 약 45분 걸리며, 짧은 필기시험도 보시게 됩니다. 지게차 안전 자격증 사본을 가져와 주세요. 목요일이 어려우시면 내일 오후까지 내선 214번으로 전화 주세요.","part":4},{"id":"p4-066","level":3,"topic":"기장의 기내 방송과 난기류 예고","talk_type":"안내 방송","voice":"male","script":"Good afternoon, ladies and gentlemen. This is your captain speaking. We've reached our cruising altitude, and our flight time to Vancouver today is about four hours and ten minutes. I do want to let you know that we're expecting some rough air over the mountains in about an hour. When that happens, I'll turn on the seat belt sign, and our flight attendants will stop the meal service for a while. So if you're hungry, now would be a good time to order. Our attendants will be coming through the cabin with sandwiches and drinks shortly. Also, for those of you sitting on the right side of the plane, you'll get a great view of Lake Superior in about twenty minutes. Sit back and enjoy the flight.","graphic":null,"questions":[{"q":"Who is the speaker?","choices":["A flight attendant","An airport employee","A pilot","A travel agent"],"answer":2,"type":"화자 정보(직업·장소)","explanation":"“This is your captain speaking.”이라고 했으므로 기장, 즉 조종사다. 승무원은 화자가 언급하는 다른 사람들이다."},{"q":"What does the speaker mean when he says, \"if you're hungry, now would be a good time to order\"?","choices":["Some items are sold out.","The meals are free today.","Food service may be interrupted later.","The flight will arrive early."],"answer":2,"type":"의도 파악","explanation":"약 한 시간 뒤 난기류가 오면 “our flight attendants will stop the meal service for a while”라고 했으므로, 나중에는 식사 서비스가 중단될 수 있으니 지금 주문하라는 뜻이다."},{"q":"According to the speaker, what will passengers on the right side be able to see?","choices":["The ocean","A lake","Some mountains","A city"],"answer":1,"type":"세부 사항","explanation":"“you'll get a great view of Lake Superior in about twenty minutes”라고 했으므로 호수를 볼 수 있다. 산은 난기류가 예상되는 곳으로 언급됐다."}],"translation":"안녕하십니까, 승객 여러분. 기장입니다. 순항 고도에 도달했으며, 오늘 밴쿠버까지 비행시간은 약 4시간 10분입니다. 약 한 시간 뒤 산악 지대 위에서 기류가 불안정할 것으로 예상된다는 점을 알려 드립니다. 그때가 되면 좌석 벨트 표시등을 켜고, 승무원들은 잠시 식사 서비스를 중단할 것입니다. 그러니 시장하시다면 지금 주문하시는 게 좋겠습니다. 승무원들이 곧 샌드위치와 음료를 가지고 객실을 돌 것입니다. 그리고 비행기 오른쪽에 앉으신 분들은 약 20분 뒤 슈피리어호를 멋지게 보실 수 있습니다. 편히 앉아 비행을 즐기십시오.","part":4},{"id":"p4-067","level":3,"topic":"회의실 온라인 예약 제도 도입","talk_type":"회의 발췌","voice":"female","script":"Before we wrap up, I want to mention a change to the way we book meeting rooms. Starting next month, all reservations will be made through the new online calendar instead of by e-mailing the front desk. You'll be able to see which rooms are free and what equipment each one has. Now, about our team's quarterly planning session on the fifteenth. There'll be about fifteen of us, and we'll need a projector for the presentations. I've already checked, and the smallest room that meets those needs is available, so I've booked it. Oh, and training sessions on the new calendar will be held next Tuesday. Please sign up by Friday.","graphic":{"title":"Meeting Rooms","rows":[["Room","Seats","Equipment"],["Aspen","6","TV screen"],["Birch","12","Projector"],["Cedar","20","Projector"],["Douglas","40","Video conference system"]]},"questions":[{"q":"What change is the speaker announcing?","choices":["A new way to reserve rooms","New equipment in meeting rooms","A new office layout","A change in meeting times"],"answer":0,"type":"주제·목적","explanation":"“all reservations will be made through the new online calendar instead of by e-mailing the front desk”라고 했으므로 회의실 예약 방식이 바뀐다."},{"q":"Look at the graphic. Which room has the speaker booked?","choices":["Cedar","Aspen","Birch","Douglas"],"answer":0,"type":"시각 자료 연계","explanation":"약 15명이 들어가고 프로젝터가 있는 방 중 가장 작은 방을 예약했다고 했다. 버치는 12석이라 부족하고, 20석에 프로젝터가 있는 시더가 조건에 맞는 가장 작은 방이다."},{"q":"What does the speaker ask the listeners to do by Friday?","choices":["E-mail the front desk","Book a meeting room","Submit their presentations","Register for training"],"answer":3,"type":"요청·제안","explanation":"새 캘린더 교육이 다음 주 화요일에 있다며 “Please sign up by Friday.”라고 했으므로 금요일까지 교육을 신청해야 한다."}],"translation":"마치기 전에 회의실 예약 방식이 바뀌는 것에 대해 말씀드릴게요. 다음 달부터 모든 예약은 안내 데스크에 이메일을 보내는 대신 새 온라인 캘린더로 하게 됩니다. 어떤 방이 비어 있고 방마다 어떤 장비가 있는지 볼 수 있어요. 그리고 15일에 있을 우리 팀 분기 기획 회의 말인데요. 인원은 15명 정도이고 발표용 프로젝터가 필요해요. 이미 확인해 봤는데, 그 조건을 충족하는 가장 작은 방이 비어 있어서 예약해 뒀어요. 아, 그리고 새 캘린더 사용 교육이 다음 주 화요일에 열려요. 금요일까지 신청해 주세요.","part":4},{"id":"p4-068","level":3,"topic":"가전제품 출장 수리 서비스 광고","talk_type":"광고","voice":"male","script":"Is your washing machine making strange noises? Has your refrigerator stopped keeping things cold? Before you spend hundreds of dollars on a new one, call FixRight Appliance Repair. Our technicians repair all major brands, and most repairs are finished in a single visit, because our vans carry more than two thousand common parts. We charge a flat fee of sixty dollars for the visit, and that fee is taken off your bill if you go ahead with the repair. And here's something you won't hear from other companies: every repair comes with a one-year guarantee. Buying new? You might not need to. Visit fixright.com to schedule an appointment, even on weekends.","graphic":null,"questions":[{"q":"Why are most repairs completed in a single visit?","choices":["Customers describe problems online.","The company repairs only one brand.","Technicians carry many parts.","Repairs are done at a workshop."],"answer":2,"type":"세부 사항","explanation":"“most repairs are finished in a single visit, because our vans carry more than two thousand common parts”라고 했다. 모든 주요 브랜드를 수리한다고 했으므로 한 브랜드만 한다는 말은 틀리다."},{"q":"What is said about the sixty-dollar fee?","choices":["It is subtracted if a repair is made.","It must be paid online in advance.","It is charged only on weekends.","It includes a one-year guarantee."],"answer":0,"type":"세부 사항","explanation":"“that fee is taken off your bill if you go ahead with the repair”라고 했으므로 수리를 진행하면 청구액에서 빠진다."},{"q":"What does the speaker imply when he says, \"Buying new? You might not need to\"?","choices":["The company sells used appliances.","New appliances are currently on sale.","Customers should wait before making a purchase.","Many appliances can be repaired instead of replaced."],"answer":3,"type":"의도 파악","explanation":"광고 앞부분에서 “Before you spend hundreds of dollars on a new one, call FixRight”라고 했으므로, 새로 살 필요 없이 고쳐 쓸 수 있다는 뜻이다."}],"translation":"세탁기에서 이상한 소리가 나나요? 냉장고가 더 이상 음식을 차갑게 유지하지 못하나요? 새 제품에 수백 달러를 쓰기 전에 픽스라이트 가전 수리에 전화하세요. 저희 기술자들은 모든 주요 브랜드를 수리하며, 차량에 2천 개가 넘는 일반 부품을 싣고 다니기 때문에 대부분의 수리가 한 번 방문으로 끝납니다. 방문비는 60달러 정액이며, 수리를 진행하시면 이 금액은 청구액에서 빼 드립니다. 그리고 다른 회사에서는 듣지 못할 이야기가 있습니다. 모든 수리에 1년 보증이 제공됩니다. 새로 사시려고요? 그러실 필요가 없을지도 모릅니다. fixright.com에서 주말에도 방문 예약을 하세요.","part":4},{"id":"p4-069","level":3,"topic":"공공 자전거 대여소 확충 시정 뉴스","talk_type":"방송·뉴스","voice":"female","script":"In city news, Harborview's bike-sharing program is expanding. The city council voted last night to add thirty new stations and three hundred bicycles by the end of the summer. Most of the new stations will be located near train stations and the university, where demand has been highest. Council member Janet Ortiz said the goal is to make it easier for people to get to work without driving. The expansion will be paid for mainly through advertising on the bikes themselves, so riders will not see an increase in prices. However, the city is asking for public input on exact locations. Residents can suggest sites on the city's Web site until May thirty-first.","graphic":null,"questions":[{"q":"What is the news report mainly about?","choices":["A change in parking fees","A new train line","The expansion of a bike program","A university construction project"],"answer":2,"type":"주제·목적","explanation":"“Harborview's bike-sharing program is expanding.”으로 시작해 대여소 30곳과 자전거 300대 추가 소식을 전한다. 기차역과 대학은 새 대여소 위치로만 언급됐다."},{"q":"How will the expansion mainly be funded?","choices":["Through a new tax","Through donations from the university","Through advertising","Through higher prices"],"answer":2,"type":"세부 사항","explanation":"“The expansion will be paid for mainly through advertising on the bikes themselves”라고 했고, 이용 요금은 오르지 않는다고 했다."},{"q":"What are residents invited to do?","choices":["Test new bicycles at the university","Vote in an election","Attend a council meeting","Suggest station locations"],"answer":3,"type":"요청·제안","explanation":"“Residents can suggest sites on the city's Web site until May thirty-first.”라고 했으므로 대여소 위치를 제안할 수 있다."}],"translation":"시정 소식입니다. 하버뷰의 공공 자전거 대여 프로그램이 확대됩니다. 시의회는 어젯밤 여름이 끝날 때까지 대여소 30곳과 자전거 300대를 추가하기로 의결했습니다. 새 대여소는 대부분 수요가 가장 많았던 기차역과 대학 근처에 들어섭니다. 재닛 오티즈 시의원은 사람들이 차를 운전하지 않고도 더 쉽게 출근할 수 있게 하는 것이 목표라고 말했습니다. 확대 비용은 주로 자전거에 싣는 광고로 충당되므로 이용자 요금은 오르지 않습니다. 다만 시는 정확한 위치에 대해 시민 의견을 받고 있습니다. 주민들은 5월 31일까지 시 웹사이트에서 장소를 제안할 수 있습니다.","part":4},{"id":"p4-070","level":3,"topic":"하천 산책로 정화 자원봉사 시작 인사","talk_type":"연설·소개","voice":"male","script":"Good morning, volunteers, and thank you all for coming out so early on a Saturday. I'm Paul Anders from the Greenway Parks Association. Today we'll be cleaning up the trails along Miller Creek. We've divided you into four teams, and each team leader has a map showing your section. Gloves, trash bags, and grabbers are on the tables behind me. Now, the forecast says it'll be sunny and hot by noon. There's plenty of water in the coolers. We'll meet back here at twelve thirty for lunch, which has been donated by Rosie's Deli. Finally, if you find anything large, like old tires, don't try to lift it yourself. Just mark the spot on your map.","graphic":null,"questions":[{"q":"Where does the speaker most likely work?","choices":["At a weather station near the creek","At a delicatessen","At a parks association","At a recycling plant"],"answer":2,"type":"화자 정보(직업·장소)","explanation":"“I'm Paul Anders from the Greenway Parks Association.”이라고 했다. 델리(식당)는 점심을 기부한 곳이다."},{"q":"Why does the speaker say, \"the forecast says it'll be sunny and hot by noon\"?","choices":["To explain why the event may be canceled","To explain why lunch will be served indoors","To announce a change in the schedule","To encourage the volunteers to take water"],"answer":3,"type":"의도 파악","explanation":"이 말 바로 뒤에 “There's plenty of water in the coolers.”라고 했으므로 더워질 테니 물을 챙기라는 뜻이다. 일정 변경이나 취소는 언급되지 않았다."},{"q":"What should volunteers do if they find a large item?","choices":["Carry it to the tables","Put it in a trash bag","Mark its location on a map","Leave it at the meeting point"],"answer":2,"type":"요청·제안","explanation":"“if you find anything large ... don't try to lift it yourself. Just mark the spot on your map.”이라고 했다."}],"translation":"자원봉사자 여러분, 좋은 아침입니다. 토요일 이른 아침에 모두 나와 주셔서 감사합니다. 저는 그린웨이 공원 협회의 폴 앤더스입니다. 오늘은 밀러 하천을 따라 난 산책로를 청소하겠습니다. 여러분을 네 팀으로 나눴고, 팀장마다 맡은 구역이 표시된 지도를 가지고 있습니다. 장갑, 쓰레기봉투, 집게는 제 뒤 탁자 위에 있습니다. 그런데 일기 예보에 따르면 정오쯤에는 맑고 더워진다고 합니다. 아이스박스에 물이 넉넉히 있습니다. 12시 30분에 여기 다시 모여 점심을 먹겠습니다. 점심은 로지스 델리에서 기부해 주셨습니다. 마지막으로 낡은 타이어처럼 큰 물건을 발견하면 혼자 들려고 하지 마세요. 지도에 위치만 표시해 주세요.","part":4},{"id":"p4-071","level":3,"topic":"신문사 인쇄 공장 견학","talk_type":"관광·견학 안내","voice":"female","script":"Welcome to the Daily Tribune's printing facility. I'm Grace, and I'll be leading today's tour. This building houses the three presses that print every copy of our morning paper, about two hundred thousand copies a night. Because the presses run overnight, you won't see them in full operation today, but our technicians will demonstrate a short test run in about twenty minutes. Before we enter the press hall, please put on the earplugs and safety glasses you were given at the entrance. It gets extremely loud in there. After the demonstration, we'll visit the newsroom archive, where you can see front pages going back to 1890. And at the end, everyone will receive a copy of a front page with your group's photo on it.","graphic":null,"questions":[{"q":"Why won't the listeners see the presses in full operation?","choices":["They were recently replaced.","They are used only on weekends.","They run at night.","They are being repaired."],"answer":2,"type":"세부 사항","explanation":"“Because the presses run overnight, you won't see them in full operation today”라고 했다. 대신 짧은 시험 가동을 보여 준다."},{"q":"What are the listeners asked to do before entering the press hall?","choices":["Put on protective equipment","Leave their bags at the entrance","Turn off their phones","Sign a form"],"answer":0,"type":"요청·제안","explanation":"“please put on the earplugs and safety glasses you were given at the entrance”라고 했으므로 귀마개와 보안경 같은 보호 장비를 착용해야 한다."},{"q":"What will the listeners receive at the end of the tour?","choices":["A group discount","A personalized front page","A book about the newspaper's history","A free subscription"],"answer":1,"type":"세부 사항","explanation":"“everyone will receive a copy of a front page with your group's photo on it”이라고 했으므로 단체 사진이 실린 1면을 받는다."}],"translation":"데일리 트리뷴 인쇄 시설에 오신 것을 환영합니다. 저는 오늘 투어를 진행할 그레이스입니다. 이 건물에는 조간신문 전 부수, 하룻밤에 약 20만 부를 찍는 윤전기 세 대가 있습니다. 윤전기는 밤사이에 돌아가기 때문에 오늘은 완전히 가동되는 모습을 보실 수 없지만, 약 20분 뒤 기술자들이 짧은 시험 가동을 보여 드릴 겁니다. 인쇄실에 들어가기 전에 입구에서 받으신 귀마개와 보안경을 착용해 주세요. 안은 엄청나게 시끄럽습니다. 시연이 끝나면 편집국 자료실에 가서 1890년까지 거슬러 올라가는 1면들을 보시게 됩니다. 그리고 마지막에는 모두 여러분 단체 사진이 실린 1면을 한 부씩 받으십니다.","part":4},{"id":"p4-072","level":4,"topic":"매장 진열대 화물 통관 지연 통보 전화","talk_type":"전화 메시지","voice":"male","script":"Hi, Ms. Patel, it's Derek Owens from Summit Freight. I'm calling about the shipment of display shelving that's supposed to arrive at your Riverside store on Wednesday. I'm afraid our truck was held up at the border this morning because some of the customs paperwork didn't match the invoice. We've sent the corrected documents, and we expect the truck to be released by tomorrow, which would put delivery on Friday instead. I know your grand opening is Saturday. Our crew can do the installation Friday evening if that helps, and we've waived the delivery charge on this order. Could you let me know by the end of the day whether Friday evening works for your staff? My direct line is 555-0176.","graphic":null,"questions":[{"q":"What caused the delay?","choices":["Bad weather at the border","A mechanical problem with a truck","A documentation error","A shortage of shelving"],"answer":2,"type":"세부 사항","explanation":"트럭이 국경에 묶인 이유를 “some of the customs paperwork didn't match the invoice”라고 설명했으므로 서류 오류 때문이다."},{"q":"What does the speaker imply when he says, \"I know your grand opening is Saturday\"?","choices":["He understands that the schedule is tight.","He wants to deliver the shelves on Saturday.","He plans to attend the event.","He thinks the opening should be postponed."],"answer":0,"type":"의도 파악","explanation":"배송이 개점 하루 전인 금요일로 밀린다고 한 직후의 말이고, 이어서 금요일 저녁 설치와 배송비 면제를 제안한다. 일정이 빠듯하다는 점을 알고 있다는 뜻이다."},{"q":"What does the speaker ask the listener to do?","choices":["Confirm an installation time","Send a corrected invoice","Reschedule the grand opening","Pay a delivery charge"],"answer":0,"type":"요청·제안","explanation":"“Could you let me know by the end of the day whether Friday evening works for your staff?”라고 했으므로 설치 시간을 확인해 달라는 요청이다. 배송비는 면제됐다."}],"translation":"안녕하세요, 파텔 씨. 서밋 운송의 데릭 오언스입니다. 수요일에 리버사이드 매장에 도착할 예정이던 진열대 화물 건으로 전화드렸습니다. 죄송하지만 오늘 아침 통관 서류 일부가 송장과 일치하지 않아 저희 트럭이 국경에서 멈춰 있습니다. 수정한 서류를 보냈고 내일까지는 트럭이 풀려날 것으로 보여서, 배송은 대신 금요일이 될 것 같습니다. 토요일이 개점일이신 거 압니다. 도움이 된다면 저희 작업반이 금요일 저녁에 설치해 드릴 수 있고, 이번 주문의 배송비는 받지 않기로 했습니다. 금요일 저녁이 직원분들께 괜찮은지 오늘 중으로 알려 주시겠어요? 제 직통 번호는 555-0176입니다.","part":4},{"id":"p4-073","level":4,"topic":"비즈니스 서밋 오후 세션 장소 변경 안내","talk_type":"안내 방송","voice":"female","script":"Good afternoon, attendees of the Regional Business Summit. We have a few updates to this afternoon's program. First, due to a problem with the audio system in Room C, the three o'clock session will now be held in the main ballroom on the ground floor. Please note that the ballroom is in the east wing, so allow a few extra minutes to get there. Second, the speaker for the one o'clock session has been delayed at the airport, so that session will start thirty minutes late. Finally, lunch is being served on the terrace until one fifteen. Attendees who registered for this evening's networking reception should pick up their wristbands at the registration desk before five o'clock. Thank you.","graphic":{"title":"Afternoon Sessions","rows":[["Time","Session","Room"],["1:00","Digital Marketing Trends","Room A"],["2:00","Supply Chain Analytics","Room B"],["3:00","Leadership in Remote Teams","Room C"],["4:00","Negotiation Skills","Room D"]]},"questions":[{"q":"Look at the graphic. Which session has been moved?","choices":["Leadership in Remote Teams","Negotiation Skills","Digital Marketing Trends","Supply Chain Analytics"],"answer":0,"type":"시각 자료 연계","explanation":"C호실 음향 문제로 “the three o'clock session will now be held in the main ballroom”이라고 했다. 표에서 3시 C호실 세션은 원격 팀 리더십이다. 1시 세션은 장소가 아니라 시작 시간이 늦춰진다."},{"q":"Why will a session start late?","choices":["Audio equipment is being repaired in Room C.","A presenter's travel has been delayed.","The room is being cleaned.","Lunch is running late."],"answer":1,"type":"세부 사항","explanation":"“the speaker for the one o'clock session has been delayed at the airport”라고 했으므로 발표자의 이동이 늦어졌기 때문이다. 음향 문제는 장소 변경의 이유다."},{"q":"What should attendees of the evening reception do?","choices":["Register online","Pay an additional fee at the entrance","Collect their wristbands","Go to the terrace"],"answer":2,"type":"요청·제안","explanation":"저녁 네트워킹 행사 등록자는 “should pick up their wristbands at the registration desk before five o'clock”이라고 했다."}],"translation":"지역 비즈니스 서밋 참석자 여러분, 안녕하십니까. 오늘 오후 프로그램에 몇 가지 변경 사항이 있습니다. 첫째, C호실 음향 시스템 문제로 3시 세션은 1층 대연회장에서 열립니다. 대연회장은 동관에 있으니 이동 시간을 몇 분 더 여유 있게 잡아 주십시오. 둘째, 1시 세션 연사가 공항에서 지연되어 해당 세션은 30분 늦게 시작합니다. 마지막으로 점심은 1시 15분까지 테라스에서 제공됩니다. 오늘 저녁 네트워킹 리셉션에 등록하신 분들은 5시 전에 등록 데스크에서 손목 밴드를 받아 가십시오. 감사합니다.","part":4},{"id":"p4-074","level":4,"topic":"고객센터 통화 대기 시간 점검 회의","talk_type":"회의 발췌","voice":"male","script":"Let's move on to the call center numbers. As you can see on the chart, wait times climbed steadily through the first quarter, and they peaked in the month we launched the new billing system, which generated a flood of questions from customers. The good news is that after we added the automated callback option, the figure dropped to its lowest level this year. Now, some of you have asked whether we still need the six temporary agents we brought on in March. Well, the summer promotion starts in June. I'd rather not find ourselves back where we were. So what I'd like each team lead to do is review your staffing schedules for June and July and send me your projections by next Wednesday.","graphic":{"title":"Average Call Wait Time","rows":[["Month","Minutes"],["January","6.5"],["February","7.2"],["March","9.8"],["April","5.1"]]},"questions":[{"q":"Look at the graphic. In which month was the new billing system launched?","choices":["February","March","January","April"],"answer":1,"type":"시각 자료 연계","explanation":"대기 시간이 “peaked in the month we launched the new billing system”이라고 했다. 표에서 대기 시간이 가장 긴 달은 9.8분인 3월이다. 4월은 자동 콜백 도입 후 가장 낮아진 달이다."},{"q":"What does the speaker imply when he says, \"the summer promotion starts in June\"?","choices":["Wait times will be reported in June.","The billing system will change again.","The temporary agents should be kept.","The promotion should be canceled."],"answer":2,"type":"의도 파악","explanation":"임시 상담원 6명이 아직 필요하냐는 질문에 대한 답이고, 이어서 “I'd rather not find ourselves back where we were.”라고 했다. 여름 행사로 문의가 늘 테니 임시 인력을 유지해야 한다는 뜻이다."},{"q":"What are the team leads asked to do?","choices":["Test the callback option","Submit staffing projections","Hire more temporary agents","Contact billing customers"],"answer":1,"type":"요청·제안","explanation":"“review your staffing schedules for June and July and send me your projections by next Wednesday”라고 했으므로 인력 예측치를 제출해야 한다."}],"translation":"콜센터 수치로 넘어가겠습니다. 차트에서 보시듯이 대기 시간은 1분기 내내 꾸준히 올라갔고, 새 청구 시스템을 도입한 달에 최고치를 찍었습니다. 그때 고객 문의가 폭주했죠. 좋은 소식은 자동 콜백 기능을 추가한 뒤 수치가 올해 최저 수준으로 떨어졌다는 것입니다. 그런데 3월에 들인 임시 상담원 여섯 명이 아직도 필요하냐고 물으신 분들이 있습니다. 음, 여름 판촉 행사가 6월에 시작됩니다. 저는 예전 상황으로 돌아가고 싶지 않습니다. 그래서 각 팀장님은 6월과 7월 인력 배치표를 검토해서 다음 주 수요일까지 예측치를 보내 주셨으면 합니다.","part":4},{"id":"p4-075","level":4,"topic":"공유 오피스 멤버십 광고","talk_type":"광고","voice":"female","script":"Tired of working from your kitchen table? Or paying for a full office you only use three days a week? At Hive Workspaces, you get a professional environment without the long-term lease. Our flexible memberships start at just one hundred and fifty dollars a month and include high-speed Internet, printing, and unlimited coffee. Need to impress a client? Private meeting rooms can be reserved by the hour through our app. With twelve locations across the metro area, there's always a Hive near you, and your membership works at all of them. Still not sure? Come see for yourself. Your first week is on us. Visit hiveworkspaces.com to book a tour of the location nearest you.","graphic":null,"questions":[{"q":"What is being advertised?","choices":["An office cleaning company","Shared office space","A coffee delivery service","Home office furniture"],"answer":1,"type":"주제·목적","explanation":"“you get a professional environment without the long-term lease”, 월 멤버십, 회의실 예약 등을 소개하므로 공유 사무실 광고다."},{"q":"What is mentioned about the memberships?","choices":["They are discounted for students.","They include private parking.","They require a one-year contract.","They can be used at any location."],"answer":3,"type":"세부 사항","explanation":"“With twelve locations ... your membership works at all of them”이라고 했다. 장기 임대 계약이 없다는 점을 강조했으므로 1년 계약은 틀리다."},{"q":"What does the speaker mean when she says, \"Your first week is on us\"?","choices":["Listeners can try the service free for a week.","Tours are available only during the first week.","A deposit is required for the first week.","Members must choose a location in the first week."],"answer":0,"type":"의도 파악","explanation":"“Still not sure? Come see for yourself.” 다음에 나온 말로, be on us는 ‘우리가 부담한다’는 뜻이다. 첫 주는 무료로 이용해 보라는 의미다."}],"translation":"식탁에서 일하는 데 지치셨나요? 아니면 일주일에 사흘만 쓰는 사무실 전체에 돈을 내고 계신가요? 하이브 워크스페이스에서는 장기 임대 없이 전문적인 업무 환경을 누리실 수 있습니다. 유연한 멤버십은 월 150달러부터 시작하며 고속 인터넷, 인쇄, 무제한 커피가 포함됩니다. 고객에게 좋은 인상을 줘야 하나요? 개인 회의실은 저희 앱으로 시간 단위 예약이 가능합니다. 수도권 전역에 12개 지점이 있어 가까운 곳에 늘 하이브가 있고, 멤버십은 모든 지점에서 사용하실 수 있습니다. 아직 망설여지세요? 직접 와서 보세요. 첫 주는 저희가 쏩니다. hiveworkspaces.com에서 가장 가까운 지점 둘러보기를 예약하세요.","part":4},{"id":"p4-076","level":4,"topic":"제조업체 주 4일 근무 시범 도입 경제 뉴스","talk_type":"방송·뉴스","voice":"male","script":"In business news, Corvell Manufacturing, one of the region's largest employers, announced today that it will pilot a four-day work week at its Dayton plant beginning in September. Under the plan, roughly eight hundred production workers will work four ten-hour shifts instead of five eight-hour shifts, with no change in pay. The company says the move is aimed at reducing turnover, which has risen sharply as competitors offer more flexible schedules. Analysts note that similar programs elsewhere have produced mixed results, particularly where overtime costs increased. Corvell will evaluate the pilot after six months before deciding whether to extend it to its two other facilities. Coming up after the break, we'll look at how rising interest rates are affecting home sales.","graphic":null,"questions":[{"q":"What is the report mainly about?","choices":["A merger between two manufacturing firms","A trial of a new work schedule","A change in employee pay","The opening of a new plant"],"answer":1,"type":"주제·목적","explanation":"“it will pilot a four-day work week at its Dayton plant”라고 했으므로 새 근무 형태의 시범 운영이 주제다. 급여는 “with no change in pay”라고 했다."},{"q":"According to the company, why is it making the change?","choices":["To lower overtime costs","To increase production","To attract new customers","To keep employees from leaving"],"answer":3,"type":"세부 사항","explanation":"“the move is aimed at reducing turnover”라고 했으므로 직원 이직을 줄이기 위해서다. 초과 근무 비용은 분석가들이 우려한 점이지 회사가 밝힌 이유가 아니다."},{"q":"What will listeners most likely hear about after the break?","choices":["Factory safety rules","The housing market","Job openings in the region","Interest rates on car loans"],"answer":1,"type":"다음 할 일","explanation":"“after the break, we'll look at how rising interest rates are affecting home sales”라고 했으므로 주택 판매, 즉 주택 시장 소식이 이어진다."}],"translation":"경제 소식입니다. 지역 최대 고용주 중 하나인 코벨 제조는 오늘 9월부터 데이턴 공장에서 주 4일 근무를 시범 운영하겠다고 발표했습니다. 계획에 따르면 생산직 근로자 약 800명이 하루 8시간씩 5일 대신 하루 10시간씩 4일 근무하며, 급여는 변하지 않습니다. 회사 측은 경쟁사들이 더 유연한 근무 일정을 제공하면서 급격히 늘어난 이직률을 낮추려는 조치라고 밝혔습니다. 분석가들은 다른 곳의 비슷한 제도가 엇갈린 결과를 냈으며, 특히 초과 근무 비용이 늘어난 경우가 그랬다고 지적합니다. 코벨은 6개월 뒤 시범 운영을 평가한 다음 나머지 두 시설로 확대할지 결정할 예정입니다. 광고 후에는 금리 상승이 주택 판매에 어떤 영향을 주고 있는지 살펴보겠습니다.","part":4},{"id":"p4-077","level":4,"topic":"은행 신규 지점 개점식 연설","talk_type":"연설·소개","voice":"female","script":"Good morning, everyone, and thank you for joining us for the opening of Northfield Bank's newest branch here in Cedar Grove. When we first looked at this neighborhood three years ago, the nearest bank was a twenty-minute drive away, and many of the small business owners we spoke to told us they were spending hours each week just handling deposits. That's why this branch is designed a little differently. In addition to the usual services, we've included a business center with two advisers who specialize in loans for small retailers. We're also extending our hours to seven p.m. on weekdays. I'd like to thank Mayor Diane Holt, who helped us secure this location. Mayor Holt, would you come up and help me cut the ribbon?","graphic":null,"questions":[{"q":"What is the purpose of the speech?","choices":["To celebrate the opening of a branch","To introduce a new mayor","To announce a merger","To promote a local election"],"answer":0,"type":"주제·목적","explanation":"“thank you for joining us for the opening of Northfield Bank's newest branch”라고 했으므로 신규 지점 개점을 기념하는 연설이다."},{"q":"What is special about the branch?","choices":["It offers advice to small businesses.","It is located inside city hall.","It is open on weekends.","It has no human tellers."],"answer":0,"type":"세부 사항","explanation":"“a business center with two advisers who specialize in loans for small retailers”라고 했다. 연장 영업은 평일 오후 7시까지이며 주말 영업은 언급되지 않았다."},{"q":"What will most likely happen next?","choices":["Advisers will be introduced.","A ribbon will be cut.","Customers will open accounts.","A tour of the branch will begin."],"answer":1,"type":"다음 할 일","explanation":"마지막에 시장에게 “would you come up and help me cut the ribbon?”이라고 했으므로 곧 테이프 커팅을 할 것이다."}],"translation":"안녕하십니까, 여러분. 이곳 시더 그로브에 문을 여는 노스필드 은행 신규 지점 개점식에 함께해 주셔서 감사합니다. 3년 전 이 동네를 처음 살펴봤을 때 가장 가까운 은행은 차로 20분 거리에 있었고, 저희가 만난 소상공인 중 많은 분이 입금 처리에만 매주 몇 시간씩 쓰고 있다고 하셨습니다. 그래서 이 지점은 조금 다르게 설계했습니다. 일반 업무 외에 소매업체 대출을 전문으로 하는 상담사 두 명이 있는 비즈니스 센터를 두었습니다. 또 평일 영업시간을 오후 7시까지 연장합니다. 이 부지를 확보하도록 도와주신 다이앤 홀트 시장님께 감사드립니다. 홀트 시장님, 앞으로 나오셔서 테이프 커팅을 함께해 주시겠습니까?","part":4},{"id":"p4-078","level":4,"topic":"옛 항구 역사 지구 도보 투어","talk_type":"관광·견학 안내","voice":"male","script":"Welcome to the Old Harbor walking tour. I'm Martin, and for the next two hours, we'll be exploring the district that made this city a trading center in the eighteen hundreds. We'll start here at the Customs House, which was converted into a public library in the nineteen seventies, and then make our way down Chandler Street, where you'll see some of the original warehouses. Several have been turned into restaurants, so if something smells good, make a note of it, because you'll have free time for lunch at the end. A couple of things before we set off. Parts of the street are still cobblestone, so watch your step. And if you'd like to see inside the lighthouse, tickets are sold separately at the gift shop. Let's go.","graphic":null,"questions":[{"q":"What does the speaker say about the Customs House?","choices":["It houses a restaurant.","It is closed for renovation.","It now serves as a library.","It was built in the 1970s."],"answer":2,"type":"세부 사항","explanation":"“the Customs House, which was converted into a public library in the nineteen seventies”라고 했다. 1970년대는 지어진 때가 아니라 도서관으로 바뀐 때다."},{"q":"What will participants be able to do at the end of the tour?","choices":["Climb the lighthouse for free","Have lunch on their own","Visit a warehouse museum","Take a boat ride"],"answer":1,"type":"세부 사항","explanation":"“you'll have free time for lunch at the end”라고 했다. 등대는 입장권을 따로 사야 하므로 무료가 아니다."},{"q":"What does the speaker advise the listeners to do?","choices":["Walk carefully","Buy tickets in advance","Stay close to the group","Bring an umbrella"],"answer":0,"type":"요청·제안","explanation":"“Parts of the street are still cobblestone, so watch your step.”이라고 했으므로 발밑을 조심하라고 권했다."}],"translation":"올드 하버 도보 투어에 오신 것을 환영합니다. 저는 마틴이고, 앞으로 두 시간 동안 1800년대에 이 도시를 무역 중심지로 만든 지구를 둘러보겠습니다. 1970년대에 공공 도서관으로 바뀐 이곳 세관 건물에서 출발해 챈들러 스트리트를 따라 내려가면서 당시 창고 몇 곳을 보겠습니다. 그중 몇 곳은 식당으로 바뀌었으니 좋은 냄새가 나는 곳이 있으면 기억해 두세요. 마지막에 점심 자유 시간이 있거든요. 출발 전에 몇 가지 말씀드릴게요. 거리 일부는 아직 자갈길이니 발밑을 조심하세요. 그리고 등대 내부를 보고 싶으시면 입장권은 기념품 가게에서 따로 판매합니다. 출발하겠습니다.","part":4},{"id":"p4-079","level":5,"topic":"로비 설계 변경에 대한 건축가 회신 전화","talk_type":"전화 메시지","voice":"female","script":"Hi, Raymond, it's Ingrid Novak at Castellan Architects, returning your call about the lobby redesign. I went over the revised drawings with our structural engineer this morning, and there's a complication. Removing that column to open up the reception area would mean adding a steel beam across the ceiling, which, frankly, would eat up most of the savings you were hoping for on the finishes. Now, I'm not saying it can't be done. But before we commit, I'd suggest we look at an alternative: keeping the column and wrapping it in the same wood paneling as the reception desk, so it reads as a design feature rather than an obstacle. I've sketched both options. I'll be at the site Thursday morning, so if you can spare half an hour, we could walk through them together.","graphic":null,"questions":[{"q":"What problem does the speaker mention?","choices":["The drawings contain measurement errors.","The wood paneling is unavailable.","The reception desk is too large.","A structural change would be costly."],"answer":3,"type":"세부 사항","explanation":"기둥을 없애려면 천장에 철골 보를 더해야 하고 “would eat up most of the savings you were hoping for”라고 했으므로 구조 변경 비용이 크다는 것이 문제다."},{"q":"What does the speaker imply when she says, \"I'm not saying it can't be done\"?","choices":["The engineer has already approved the plan.","She needs more time to review the drawings.","She disagrees with the engineer's conclusion.","The change is possible but may not be worthwhile."],"answer":3,"type":"의도 파악","explanation":"비용 문제를 설명한 뒤 이 말을 하고 “But before we commit, I'd suggest we look at an alternative”라고 이어 갔다. 기술적으로는 가능하지만 들이는 비용만큼 가치가 있을지 의문이라는 뜻이다."},{"q":"What does the speaker propose?","choices":["Postponing the redesign","Hiring a different engineer to review the drawings","Meeting at the site to review options","Replacing the reception desk"],"answer":2,"type":"요청·제안","explanation":"두 안을 스케치했다며 “I'll be at the site Thursday morning ... we could walk through them together”라고 제안했다."}],"translation":"안녕하세요, 레이먼드 씨. 카스텔란 건축사무소의 잉그리드 노박입니다. 로비 재설계 건으로 주신 전화에 회신드립니다. 오늘 아침 저희 구조 엔지니어와 수정 도면을 검토했는데 문제가 하나 있습니다. 접수 공간을 트기 위해 그 기둥을 없애면 천장을 가로지르는 철골 보를 추가해야 하는데, 솔직히 말씀드리면 마감재에서 아끼려고 하셨던 비용 대부분이 거기에 들어갈 겁니다. 그렇다고 불가능하다는 말씀은 아닙니다. 다만 확정하기 전에 대안을 한번 보셨으면 합니다. 기둥을 그대로 두고 접수대와 같은 목재 패널로 감싸서 장애물이 아니라 디자인 요소로 보이게 하는 방법입니다. 두 가지 안을 모두 스케치해 두었습니다. 목요일 오전에 현장에 있을 예정이니 30분 정도 시간을 내 주시면 함께 살펴볼 수 있겠습니다.","part":4},{"id":"p4-080","level":5,"topic":"데이터센터 서버 이전 주말 중단 일정 사내 방송","talk_type":"안내 방송","voice":"male","script":"This is a message from the IT department for all staff. As many of you know, this weekend we'll be relocating our servers to the new data center in Fairmont. The schedule of outages is posted on the intranet. There's been one change since it was first published: the vendor has asked us to push back the migration of the system that was originally scheduled to go offline first, so it will now go down at the same time as the customer portal, for the same four hours. Anyone on weekend shifts who relies on the inventory database should print their pick lists before Saturday evening, since there will be no remote access during the migration. And please remember to shut down, rather than simply log off, your workstations before you leave on Friday. Updates will be posted on the status page throughout the weekend.","graphic":{"title":"Weekend System Outages","rows":[["System","Unavailable"],["E-mail","Saturday 8 P.M. to Sunday 2 A.M."],["Payroll","Saturday 10 P.M. to Sunday 6 A.M."],["Customer portal","Sunday 1 A.M. to 5 A.M."],["Inventory database","Sunday 3 A.M. to 9 A.M."]]},"questions":[{"q":"What is the purpose of the announcement?","choices":["To announce new weekend shifts","To introduce a new data center manager in Fairmont","To give details about a server relocation","To report a security problem"],"answer":2,"type":"주제·목적","explanation":"“this weekend we'll be relocating our servers to the new data center”라고 한 뒤 중단 일정 변경과 준비 사항을 안내하므로 서버 이전에 관한 공지다."},{"q":"Look at the graphic. When will e-mail be unavailable?","choices":["Saturday 8 P.M. to Sunday 2 A.M.","Sunday 3 A.M. to 9 A.M.","Sunday 1 A.M. to 5 A.M.","Saturday 10 P.M. to Sunday 6 A.M."],"answer":2,"type":"시각 자료 연계","explanation":"원래 가장 먼저 중단될 예정이던 시스템은 표에서 토요일 오후 8시에 시작하는 이메일이다. 이것이 “go down at the same time as the customer portal”로 바뀌었으므로 일요일 오전 1시부터 5시까지 중단된다. 토요일 오후 8시~일요일 오전 2시는 바뀌기 전 일정이다."},{"q":"What are employees asked to do before leaving on Friday?","choices":["Power off their computers","Change their passwords","Back up their files","Print their pick lists"],"answer":0,"type":"요청·제안","explanation":"“please remember to shut down, rather than simply log off, your workstations before you leave on Friday”라고 했다. 출고 목록 인쇄는 주말 근무자에게 토요일 저녁 전까지 하라고 한 것이다."}],"translation":"IT 부서에서 전 직원께 알려 드립니다. 많은 분이 아시다시피 이번 주말 서버를 페어몬트의 새 데이터센터로 이전합니다. 서비스 중단 일정은 인트라넷에 게시되어 있습니다. 처음 게시한 이후 한 가지가 바뀌었습니다. 업체 요청으로 원래 가장 먼저 중단될 예정이던 시스템의 이전을 뒤로 미루게 되어, 이 시스템은 이제 고객 포털과 같은 시간에 같은 네 시간 동안 중단됩니다. 재고 데이터베이스를 사용하는 주말 근무자는 이전 작업 중에는 원격 접속이 되지 않으니 토요일 저녁 전에 출고 목록을 인쇄해 두십시오. 그리고 금요일 퇴근 전에 업무용 컴퓨터를 로그오프만 하지 말고 반드시 전원을 꺼 주십시오. 주말 동안 상태 페이지에 진행 상황을 계속 올리겠습니다.","part":4},{"id":"p4-081","level":5,"topic":"친환경 포장재 공급업체 선정 회의","talk_type":"회의 발췌","voice":"female","script":"So here are the four bids we received for the new recyclable packaging. On price alone, the choice looks obvious. But remember, the retail launch is in seven weeks, and we'll need at least a week after delivery to run the packaging through quality testing. That rules out two of these straight away. Between the two that remain, the cheaper one would save us roughly four cents a unit, which, over three million units, isn't nothing. On the other hand, their production facility failed an environmental audit last year, and since this entire product line is being marketed on sustainability, I'm not comfortable with that risk. So my recommendation is to go with the other one. Tomasz, could you get in touch with their sales representative and ask whether they'd lock in that price for eighteen months?","graphic":{"title":"Packaging Supplier Bids","rows":[["Supplier","Unit Cost","Lead Time"],["Arden Pack","$0.42","7 weeks"],["Brixton Containers","$0.47","3 weeks"],["Calloway Corp.","$0.39","9 weeks"],["Delmar Industries","$0.51","2 weeks"]]},"questions":[{"q":"Look at the graphic. Which supplier does the speaker recommend?","choices":["Calloway Corp.","Arden Pack","Brixton Containers","Delmar Industries"],"answer":3,"type":"시각 자료 연계","explanation":"출시까지 7주이고 납품 후 품질 검사에 최소 1주가 필요하므로 납기 7주·9주인 두 업체는 제외된다. 남은 브릭스턴(0.47달러)과 델마(0.51달러) 중 더 싼 브릭스턴은 환경 감사에서 떨어져 “go with the other one”이라고 했으므로 델마를 추천한다."},{"q":"What does the speaker imply when she says, \"over three million units, isn't nothing\"?","choices":["The cost difference is significant.","The supplier cannot produce enough units.","The budget has already been exceeded.","The order size should be reduced."],"answer":0,"type":"의도 파악","explanation":"개당 4센트 차이를 말한 직후의 표현으로, 300만 개로 치면 무시할 수 없는 금액이라는 뜻이다. 그래도 환경 감사 문제 때문에 비싼 쪽을 고른다는 흐름이다."},{"q":"What is Tomasz asked to do?","choices":["Negotiate a faster delivery","Schedule an environmental audit of the factory","Request a long-term price guarantee","Arrange a quality inspection"],"answer":2,"type":"요청·제안","explanation":"“ask whether they'd lock in that price for eighteen months”라고 했으므로 18개월 동안 가격을 고정해 줄지 요청하는 것이다."}],"translation":"자, 새 재활용 포장재에 대해 받은 입찰 네 건입니다. 가격만 보면 답은 뻔해 보이죠. 하지만 매장 출시가 7주 뒤이고, 납품 후 포장재 품질 검사에 적어도 1주가 필요하다는 걸 기억하세요. 그러면 두 곳은 바로 제외됩니다. 남은 두 곳 중 더 싼 곳을 쓰면 개당 약 4센트를 아낄 수 있는데, 300만 개면 적은 돈이 아니죠. 반면 그 업체 생산 시설은 작년 환경 감사에서 불합격했고, 이 제품군 전체를 지속가능성을 내세워 판매하는 만큼 저는 그 위험이 마음에 걸립니다. 그래서 다른 한 곳으로 가자는 게 제 추천입니다. 토마시, 그쪽 영업 담당자에게 연락해서 그 가격을 18개월 동안 고정해 줄 수 있는지 물어봐 줄래요?","part":4},{"id":"p4-082","level":5,"topic":"기업 대상 통번역 서비스 광고","talk_type":"광고","voice":"male","script":"When your company enters a new market, every word counts. A mistranslated contract clause or a product label that reads awkwardly can cost you far more than the price of getting it right the first time. That's where Lexicon Global comes in. Our network of more than four thousand certified linguists covers sixty languages, and every project is assigned to a specialist in your industry, whether that's pharmaceuticals, finance, or engineering. For live negotiations and conferences, we also provide on-site and remote interpreters on as little as forty-eight hours' notice. Unlike automated tools, our translators adapt your message to local conventions, not just local vocabulary. Request a free assessment of your current materials at lexiconglobal.com, and see what you may have been missing.","graphic":null,"questions":[{"q":"What is being advertised?","choices":["Legal consulting","Language services for businesses","Translation software","Market research"],"answer":1,"type":"주제·목적","explanation":"공인 언어 전문가 네트워크, 번역과 통역을 소개하므로 기업용 언어 서비스 광고다. “Unlike automated tools”라고 했으므로 소프트웨어가 아니다."},{"q":"How are projects assigned, according to the speaker?","choices":["To translators with relevant industry knowledge","To several teams at once","Based on the client's location and the size of its budget","To automated tools first"],"answer":0,"type":"세부 사항","explanation":"“every project is assigned to a specialist in your industry, whether that's pharmaceuticals, finance, or engineering”라고 했으므로 해당 업계를 잘 아는 번역가에게 배정된다."},{"q":"What can listeners request on the Web site?","choices":["A free review of existing materials","A list of certified linguists","A discounted interpreter booking","A sample contract"],"answer":0,"type":"세부 사항","explanation":"“Request a free assessment of your current materials at lexiconglobal.com”이라고 했다. assessment of your current materials를 review of existing materials로 바꿔 말했다."}],"translation":"회사가 새 시장에 진출할 때는 단어 하나하나가 중요합니다. 잘못 번역된 계약 조항이나 어색하게 읽히는 제품 라벨은 처음부터 제대로 하는 비용보다 훨씬 큰 대가를 치르게 할 수 있습니다. 바로 그때 렉시콘 글로벌이 필요합니다. 4천 명이 넘는 공인 언어 전문가 네트워크가 60개 언어를 다루며, 모든 프로젝트는 제약, 금융, 공학 등 고객사 업계의 전문가에게 배정됩니다. 실시간 협상과 회의를 위해 단 48시간 전 요청으로도 현장 및 원격 통역사를 제공합니다. 자동 번역 도구와 달리 저희 번역가는 현지 어휘뿐 아니라 현지 관습에 맞게 메시지를 다듬습니다. lexiconglobal.com에서 현재 자료에 대한 무료 평가를 신청하시고 그동안 무엇을 놓치고 있었는지 확인해 보세요.","part":4},{"id":"p4-083","level":5,"topic":"상업용 태양광 지원금 제도 개편 뉴스","talk_type":"방송·뉴스","voice":"female","script":"Turning to energy policy, the state legislature yesterday approved a revised incentive program for commercial solar installations, replacing the flat rebate that has been in place since 2019. Under the new system, businesses will receive credits based on the amount of electricity their panels actually generate, rather than on the size of the system they install. Is this good news for local businesses? Well, that depends on who you ask. Supporters argue it rewards efficient projects and discourages oversized installations designed mainly to capture rebates. Smaller firms, however, point out that credits are paid out quarterly, meaning they must cover the entire installation cost up front and wait years to recover it. Brenda Kwan, who owns three dry cleaners in Oakdale, told us her company would love to go solar but simply can't tie up that much cash. The program takes effect in January.","graphic":null,"questions":[{"q":"What is the report mainly about?","choices":["A new solar panel factory","A tax increase for small businesses","A change to a renewable energy incentive","Rising electricity prices"],"answer":2,"type":"주제·목적","explanation":"“approved a revised incentive program for commercial solar installations”라고 했으므로 태양광 지원 제도 개편이 주제다."},{"q":"What does the speaker imply when she says, \"that depends on who you ask\"?","choices":["Most businesses have not heard of the program.","The details have not been announced.","The legislature may change its decision.","Opinions on the program are divided."],"answer":3,"type":"의도 파악","explanation":"이 말 다음에 지지하는 쪽(“Supporters argue...”)과 우려하는 소규모 업체(“Smaller firms, however...”)의 입장을 차례로 전하므로 의견이 갈린다는 뜻이다."},{"q":"What concern do smaller businesses have?","choices":["Their panels are too small to qualify for the new credit program.","They must pay installation costs before receiving credits.","The credits will expire in January.","Rebates will go only to large firms."],"answer":1,"type":"세부 사항","explanation":"“credits are paid out quarterly, meaning they must cover the entire installation cost up front”라고 했으므로 크레딧을 받기 전에 설치비를 먼저 부담해야 하는 점을 걱정한다. 1월은 제도 시행 시점이다."}],"translation":"에너지 정책 소식입니다. 주 의회는 어제 2019년부터 시행해 온 정액 환급 제도를 대신할 상업용 태양광 설비 지원 제도 개정안을 통과시켰습니다. 새 제도에서는 기업이 설치한 설비의 규모가 아니라 패널이 실제로 생산한 전력량에 따라 크레딧을 받게 됩니다. 지역 기업들에게 좋은 소식일까요? 글쎄요, 누구에게 묻느냐에 따라 다릅니다. 지지자들은 이 제도가 효율적인 사업에 보상하고 주로 환급금을 노린 과도한 설비를 막는다고 주장합니다. 하지만 소규모 업체들은 크레딧이 분기마다 지급되기 때문에 설치 비용 전체를 먼저 부담하고 이를 회수하는 데 몇 년을 기다려야 한다고 지적합니다. 오크데일에서 세탁소 세 곳을 운영하는 브렌다 콴 씨는 태양광을 정말 도입하고 싶지만 그만큼의 현금을 묶어 둘 수는 없다고 말했습니다. 이 제도는 1월부터 시행됩니다.","part":4},{"id":"p4-084","level":5,"topic":"전국 영업 회의 폐회사와 보너스 기준 변경","talk_type":"연설·소개","voice":"male","script":"Well, that brings us to the end of this year's national sales conference. Before everyone heads to the airport, I want to leave you with one number: eighteen. That's the percentage of our revenue last year that came from customers who had been with us for less than twelve months. Three years ago, it was over forty. In other words, we've become very good at keeping clients, and not nearly as good at finding new ones. That's why, starting in the new fiscal year, a portion of every regional bonus will be tied to new-account growth. Your managers will walk you through the details in the coming weeks. I realize that's a significant shift, and I don't expect it to be comfortable. But I'm confident this group can make it work. Safe travels, everyone.","graphic":null,"questions":[{"q":"Where is the talk most likely taking place?","choices":["At an orientation for new hires","At a sales conference","At a shareholders' meeting","At an awards dinner"],"answer":1,"type":"화자 정보(직업·장소)","explanation":"“that brings us to the end of this year's national sales conference”라고 했으므로 영업 회의의 마무리 발언이다."},{"q":"What does the number eighteen refer to?","choices":["The number of regions that met their targets last year","The number of new accounts opened last year","The percentage increase in bonuses","The share of revenue from recently acquired customers"],"answer":3,"type":"세부 사항","explanation":"“the percentage of our revenue last year that came from customers who had been with us for less than twelve months”라고 했으므로 1년 미만 신규 고객에게서 나온 매출 비중이다."},{"q":"What will change in the new fiscal year?","choices":["Regional managers will be reassigned.","The conference will be held twice a year.","Bonuses will partly depend on attracting new clients.","Sales targets will be lowered for every region next year"],"answer":2,"type":"세부 사항","explanation":"“a portion of every regional bonus will be tied to new-account growth”라고 했으므로 보너스 일부가 신규 고객 확보와 연동된다."}],"translation":"자, 이것으로 올해 전국 영업 회의를 마칩니다. 모두 공항으로 떠나기 전에 숫자 하나를 남겨 드리고 싶습니다. 18입니다. 작년 매출 중 거래한 지 12개월이 안 된 고객에게서 나온 비율입니다. 3년 전에는 40퍼센트가 넘었습니다. 다시 말해 우리는 고객을 유지하는 데는 아주 능숙해졌지만 새 고객을 찾는 데는 그만큼 능숙하지 못합니다. 그래서 새 회계연도부터 모든 지역 보너스의 일부를 신규 거래처 증가와 연동하기로 했습니다. 자세한 내용은 앞으로 몇 주 안에 관리자들이 설명해 드릴 겁니다. 큰 변화라는 걸 알고 있고, 편하지 않으리라는 것도 압니다. 하지만 여러분이라면 해낼 수 있다고 확신합니다. 모두 안전하게 돌아가십시오.","part":4},{"id":"p4-085","level":5,"topic":"항공기 중정비 격납고 견학","talk_type":"관광·견학 안내","voice":"female","script":"Good afternoon, and welcome to Hangar Seven, Aerotech's heavy maintenance facility. I'm Priya Raman, the hangar's operations lead. What you're looking at is a wide-body aircraft about three weeks into what we call a C-check, an inspection so thorough that nearly every panel is removed and the plane is out of service for up to a month. Airlines schedule these years in advance, and every idle day costs them tens of thousands of dollars, so our turnaround time is essentially our reputation. Last year we cut the average from twenty-eight days to twenty-two, largely by having parts in place before the aircraft even arrives. In a moment, we'll climb the stairs to the observation deck. I'd ask that you keep your visitor badges visible at all times, and photography is permitted only from the deck itself.","graphic":null,"questions":[{"q":"Who is the speaker?","choices":["An airline pilot","A parts supplier","An operations manager","A safety inspector from the airline"],"answer":2,"type":"화자 정보(직업·장소)","explanation":"“I'm Priya Raman, the hangar's operations lead.”라고 했으므로 격납고 운영 책임자다."},{"q":"According to the speaker, how did the facility reduce its turnaround time?","choices":["By inspecting fewer panels","By preparing parts in advance","By hiring additional technicians","By working longer shifts"],"answer":1,"type":"세부 사항","explanation":"“largely by having parts in place before the aircraft even arrives”라고 했으므로 부품을 미리 준비해 둔 덕분이다."},{"q":"What are the listeners asked to do?","choices":["Wear protective helmets","Leave their cameras at the entrance","Sign a visitor log","Keep their badges displayed"],"answer":3,"type":"요청·제안","explanation":"“keep your visitor badges visible at all times”라고 했다. 사진은 관람 데크에서만 허용된다고 했을 뿐 카메라를 맡기라는 말은 없다."}],"translation":"안녕하십니까, 에어로텍의 중정비 시설인 7번 격납고에 오신 것을 환영합니다. 저는 격납고 운영 책임자 프리야 라만입니다. 지금 보고 계신 것은 C 점검이라고 부르는 정비에 들어간 지 약 3주 된 대형 항공기입니다. C 점검은 거의 모든 패널을 떼어 낼 정도로 철저한 점검이라 항공기가 최대 한 달간 운항하지 못합니다. 항공사들은 이 점검을 몇 년 전부터 일정에 잡아 두고, 비행기가 놀고 있는 하루하루가 수만 달러의 손실이기 때문에 정비 소요 시간이 곧 저희의 평판입니다. 작년에는 평균 소요 기간을 28일에서 22일로 줄였는데, 주로 항공기가 도착하기도 전에 부품을 미리 갖춰 둔 덕분입니다. 잠시 후 계단을 올라 관람 데크로 가겠습니다. 방문자 출입증은 항상 보이게 달아 주시고, 사진 촬영은 관람 데크에서만 가능합니다.","part":4},{"id":"p4-086","level":1,"topic":"미용실 예약 시간 변경 요청 전화","talk_type":"전화 메시지","voice":"female","script":"Hi, this is Amy from Bella Hair Salon. I'm calling for Ms. Laura Chen. You have an appointment for a haircut with Nina tomorrow at ten a.m. I'm sorry, but Nina is sick today, and she won't be at work tomorrow morning. She can see you at three p.m. instead. If that time is not good for you, our other stylist, Mark, is free at ten. Please call us back today and tell us which you'd like. Our number is 555-0187. Thank you!","graphic":null,"questions":[{"q":"Why is the speaker calling?","choices":["To offer a new job","To sell a hair product","To ask for a payment","To change an appointment"],"answer":3,"type":"주제·목적","explanation":"내일 오전 10시 예약 담당자 Nina가 아파서 오후 3시로 바꾸거나 다른 미용사를 고르라고 하므로 예약 변경이 목적이다. 제품 판매나 결제 이야기는 없다."},{"q":"What is the problem?","choices":["The salon is closed tomorrow.","The listener was late.","The price has changed.","A stylist is sick."],"answer":3,"type":"세부 사항","explanation":"'Nina is sick today, and she won't be at work tomorrow morning'에서 미용사가 아프다는 것이 문제다. 미용실이 문을 닫는다는 말은 없다."},{"q":"What does the speaker ask the listener to do?","choices":["Visit the Web site","Come in early","Bring a photo","Call the salon back"],"answer":3,"type":"요청·제안","explanation":"'Please call us back today'라고 했으므로 미용실에 다시 전화해 달라는 요청이다."}],"translation":"안녕하세요, 벨라 헤어 살롱의 에이미입니다. 로라 첸 님께 전화드렸습니다. 내일 오전 10시에 니나에게 커트 예약이 되어 있는데요. 죄송하지만 니나가 오늘 아파서 내일 오전에 출근하지 못합니다. 대신 오후 3시에는 봐 드릴 수 있습니다. 그 시간이 괜찮지 않으시면 다른 미용사인 마크가 10시에 비어 있습니다. 오늘 중으로 다시 전화 주셔서 어느 쪽이 좋으신지 알려 주세요. 번호는 555-0187입니다. 감사합니다!","part":4},{"id":"p4-087","level":1,"topic":"백화점 아동용품 할인 행사 안내 방송","talk_type":"안내 방송","voice":"male","script":"Good afternoon, shoppers, and welcome to Parkview Department Store. Today only, we are having a big sale on children's clothes and toys. Everything is thirty percent off until six p.m. You can find the sale in our children's section. Also, there is a free face-painting event for kids next to the sale area. It starts at two o'clock. If you need a shopping cart or a stroller, please ask at the information desk near the main entrance. Thank you for shopping with us!","graphic":{"title":"Parkview Department Store Directory","rows":[["Floor","Section"],["1st Floor","Shoes & Bags"],["2nd Floor","Women's Clothing"],["3rd Floor","Children's Clothing & Toys"],["4th Floor","Home Goods"]]},"questions":[{"q":"What is on sale today?","choices":["Shoes","Kitchen items","Books","Children's goods"],"answer":3,"type":"세부 사항","explanation":"'a big sale on children's clothes and toys'라고 했으므로 아동복과 장난감이 할인 대상이다. 신발이나 주방용품은 언급되지 않았다."},{"q":"Look at the graphic. Where is the sale?","choices":["On the 1st floor","On the 2nd floor","On the 4th floor","On the 3rd floor"],"answer":3,"type":"시각 자료 연계","explanation":"할인 행사는 아동 코너(children's section)에서 열린다. 안내도에서 아동복·장난감은 3층이므로 정답은 3층이다."},{"q":"What will happen at two o'clock?","choices":["The store will close.","A prize will be given.","A new store will open.","A face-painting event will start."],"answer":3,"type":"세부 사항","explanation":"'a free face-painting event for kids ... It starts at two o'clock'이라고 했다. 가게는 6시까지 할인하며 문을 닫는다는 말은 없다."}],"translation":"쇼핑객 여러분, 안녕하세요. 파크뷰 백화점에 오신 것을 환영합니다. 오늘 하루만 아동복과 장난감 대할인 행사를 합니다. 오후 6시까지 전 품목 30퍼센트 할인입니다. 할인 행사는 아동 코너에서 찾으실 수 있습니다. 또 할인 매장 옆에서 어린이를 위한 무료 페이스 페인팅 행사가 있습니다. 2시에 시작합니다. 쇼핑 카트나 유모차가 필요하시면 정문 근처 안내 데스크에 문의해 주세요. 저희 매장을 이용해 주셔서 감사합니다!","part":4},{"id":"p4-088","level":1,"topic":"새 사원증 배부 안내","talk_type":"회의 발췌","voice":"male","script":"OK, everyone, before we start today's meeting, I have some news. Next Monday, we are changing our security system, so all of you will get a new staff ID card. The old cards will not open the doors after Monday. You can pick up your new card at the security office on the first floor. The office is open from eight a.m. to five p.m. this Thursday and Friday. Please bring your old card with you, and give it to the security staff. Thanks. Now, let's talk about this week's schedule.","graphic":null,"questions":[{"q":"What is the speaker mainly talking about?","choices":["A holiday party","A new office","A training class","New ID cards"],"answer":3,"type":"주제·목적","explanation":"보안 시스템을 바꾸면서 모두 새 사원증(new staff ID card)을 받게 된다는 안내가 중심이다. 사무실 이전이나 교육 이야기는 아니다."},{"q":"Where can the listeners get their cards?","choices":["At the front desk","At the security office","In the meeting room","At the cafeteria"],"answer":1,"type":"세부 사항","explanation":"'You can pick up your new card at the security office on the first floor'라고 했다. 1층 보안실이 정답이다."},{"q":"What should the listeners bring?","choices":["A photo","A signed form","Some money","Their old card"],"answer":3,"type":"요청·제안","explanation":"'Please bring your old card with you'라고 했으므로 예전 카드를 가져와야 한다. 사진이나 서류는 언급되지 않았다."}],"translation":"자, 여러분, 오늘 회의를 시작하기 전에 알려 드릴 소식이 있습니다. 다음 주 월요일에 보안 시스템을 바꾸기 때문에 모두 새 사원증을 받게 됩니다. 예전 카드로는 월요일 이후 문이 열리지 않습니다. 새 카드는 1층 보안실에서 받으실 수 있습니다. 보안실은 이번 주 목요일과 금요일 오전 8시부터 오후 5시까지 엽니다. 예전 카드를 가져오셔서 보안 직원에게 반납해 주세요. 감사합니다. 이제 이번 주 일정 이야기를 해 봅시다.","part":4},{"id":"p4-089","level":1,"topic":"자전거 가게 봄맞이 할인 광고","talk_type":"광고","voice":"male","script":"Spring is here, so it's time to ride! Come to Wheel World, the biggest bike shop in Greenville. This week only, all adult bikes are twenty percent off. Do you already have a bike? Bring it in, and we'll check it for free. We also sell helmets, lights, and bike bags. Wheel World is on Oak Street, across from the city park. We're open from ten to eight every day. Visit us this week and enjoy the spring sunshine on a new bike!","graphic":null,"questions":[{"q":"What kind of business is being advertised?","choices":["A sports center","A car shop","A park","A bicycle store"],"answer":3,"type":"주제·목적","explanation":"'Wheel World, the biggest bike shop in Greenville'이라고 했으므로 자전거 가게 광고다. 공원은 가게의 위치를 설명할 때만 나온다."},{"q":"What does the business offer for free?","choices":["A helmet","A riding lesson","A bike bag","A bike check"],"answer":3,"type":"세부 사항","explanation":"'Bring it in, and we'll check it for free'라고 했으므로 무료 자전거 점검이다. 헬멧과 가방은 판매하는 물건이다."},{"q":"Where is the business located?","choices":["Near a train station","Next to a school","Inside a mall","Across from a park"],"answer":3,"type":"세부 사항","explanation":"'on Oak Street, across from the city park'라고 했으므로 공원 맞은편에 있다."}],"translation":"봄이 왔으니 자전거를 탈 때입니다! 그린빌에서 가장 큰 자전거 가게, 휠 월드로 오세요. 이번 주에만 성인용 자전거 전 제품이 20퍼센트 할인됩니다. 이미 자전거가 있으신가요? 가져오시면 무료로 점검해 드립니다. 헬멧, 라이트, 자전거 가방도 판매합니다. 휠 월드는 오크 스트리트, 시립 공원 맞은편에 있습니다. 매일 10시부터 8시까지 영업합니다. 이번 주에 방문하셔서 새 자전거로 봄 햇살을 즐기세요!","part":4},{"id":"p4-090","level":1,"topic":"시립 야외 수영장 여름 개장 지역 뉴스","talk_type":"방송·뉴스","voice":"female","script":"And now for some local news. The Fairfield outdoor pool will open for the summer this Saturday. The pool was closed for two months because workers were painting it and fixing the showers. Now everything is ready. The pool will be open every day from nine a.m. to seven p.m. until the end of August. Children under six can swim for free. The city also says the parking lot is small, so people should walk or take the bus if they can. For more information, visit the city's Web site.","graphic":null,"questions":[{"q":"Why was the pool closed?","choices":["Because of bad weather","Because it had no staff","Because of a festival","Because of repair work"],"answer":3,"type":"세부 사항","explanation":"'workers were painting it and fixing the showers'라고 했으므로 보수 공사 때문에 닫혀 있었다. 날씨나 직원 부족 이야기는 없다."},{"q":"Who can swim for free?","choices":["Older people","City workers","Students","Young children"],"answer":3,"type":"세부 사항","explanation":"'Children under six can swim for free'라고 했으므로 6세 미만 어린이가 무료다."},{"q":"What are people asked to do?","choices":["Bring their own towels","Arrive early","Buy tickets online","Walk or take the bus"],"answer":3,"type":"요청·제안","explanation":"주차장이 작아서 'people should walk or take the bus if they can'이라고 했다. 걸어오거나 버스를 타라는 요청이다."}],"translation":"이어서 지역 소식입니다. 페어필드 야외 수영장이 이번 주 토요일에 여름 개장을 합니다. 수영장은 작업자들이 페인트칠을 하고 샤워 시설을 고치느라 두 달 동안 문을 닫았습니다. 이제 모든 준비가 끝났습니다. 수영장은 8월 말까지 매일 오전 9시부터 오후 7시까지 운영합니다. 6세 미만 어린이는 무료로 수영할 수 있습니다. 시는 또 주차장이 작으니 가능하면 걸어오거나 버스를 이용해 달라고 당부했습니다. 자세한 내용은 시 웹사이트를 참고하세요.","part":4},{"id":"p4-091","level":1,"topic":"중고 도서 바자회 자원봉사자 환영 인사","talk_type":"연설·소개","voice":"female","script":"Good morning, everyone, and thank you for coming. My name is Grace, and I'm the manager of this year's used book sale. We have more than five thousand books this year, so we really need your help. This morning, some of you will put books on the tables, and others will work at the cash desks. The doors open to the public at ten. Lunch will be in the staff room at one o'clock. Before we start, please take a green T-shirt from the box by the door. That way, shoppers will know you're a volunteer.","graphic":null,"questions":[{"q":"Who most likely are the listeners?","choices":["Book writers","Teachers","Store owners","Volunteers"],"answer":3,"type":"화자 정보(직업·장소)","explanation":"화자는 바자회 책임자이고, 쇼핑객이 'you're a volunteer'임을 알 수 있도록 티셔츠를 입으라고 하므로 청자는 자원봉사자다."},{"q":"What time will the doors open to the public?","choices":["At nine","At one","At ten","At eleven"],"answer":2,"type":"세부 사항","explanation":"'The doors open to the public at ten'이라고 했다. 1시는 점심시간이다."},{"q":"What are the listeners asked to do?","choices":["Sign a form","Bring some books","Pay at the desk","Wear a T-shirt"],"answer":3,"type":"요청·제안","explanation":"'please take a green T-shirt from the box by the door'라고 하며 입으라고 했다. 티셔츠를 입는 것이 요청 사항이다."}],"translation":"여러분, 좋은 아침입니다. 와 주셔서 감사합니다. 저는 그레이스이고 올해 중고 도서 바자회 책임자입니다. 올해는 책이 5,000권이 넘어서 여러분의 도움이 정말 필요합니다. 오늘 오전에 몇 분은 테이블에 책을 진열하고, 다른 분들은 계산대에서 일하시게 됩니다. 일반 손님에게는 10시에 문을 엽니다. 점심은 1시에 직원 휴게실에서 드립니다. 시작하기 전에 문 옆 상자에서 초록색 티셔츠를 하나씩 가져가 주세요. 그래야 손님들이 여러분이 자원봉사자라는 것을 알 수 있습니다.","part":4},{"id":"p4-092","level":1,"topic":"치즈 농장 견학","talk_type":"관광·견학 안내","voice":"male","script":"Hello, everyone, and welcome to Hilltop Cheese Farm. I'm Peter, and I'll be your guide today. First, we'll visit the barn and meet our cows. Then we'll go to the kitchen, where you can watch us make cheese. After that, you'll have time to taste five different kinds of cheese. Please don't touch the machines in the kitchen. They are very hot. At the end of the tour, you can buy cheese at our farm shop. OK, please follow me to the barn.","graphic":{"title":"Hilltop Cheese Farm Tour","rows":[["Time","Activity"],["10:00","Meet the cows"],["10:30","Cheese-making kitchen"],["11:00","Cheese tasting"],["11:30","Farm shop"]]},"questions":[{"q":"Who is the speaker?","choices":["A shop owner","A cook","A farmer's customer","A tour guide"],"answer":3,"type":"화자 정보(직업·장소)","explanation":"'I'm Peter, and I'll be your guide today'라고 했으므로 견학 안내원이다."},{"q":"Look at the graphic. When will the listeners watch cheese being made?","choices":["At 10:00","At 10:30","At 11:00","At 11:30"],"answer":1,"type":"시각 자료 연계","explanation":"치즈 만드는 것은 부엌(kitchen)에서 본다. 일정표에서 Cheese-making kitchen은 10:30이다. 11:00은 시식 시간이다."},{"q":"Why should the listeners not touch the machines?","choices":["They are new.","They are expensive.","They are dirty.","They are very hot."],"answer":3,"type":"세부 사항","explanation":"'Please don't touch the machines ... They are very hot'이라고 했으므로 뜨겁기 때문이다."}],"translation":"여러분, 안녕하세요. 힐탑 치즈 농장에 오신 것을 환영합니다. 저는 피터이고 오늘 여러분의 안내를 맡았습니다. 먼저 헛간에 가서 젖소들을 만나 보겠습니다. 그다음 부엌으로 가서 치즈 만드는 모습을 보시게 됩니다. 그 후에는 다섯 가지 치즈를 맛볼 시간이 있습니다. 부엌에 있는 기계는 만지지 마세요. 아주 뜨겁습니다. 견학이 끝나면 농장 매장에서 치즈를 사실 수 있습니다. 자, 헛간으로 저를 따라오세요.","part":4},{"id":"p4-093","level":1,"topic":"소파 배송 시간 확인 전화","talk_type":"전화 메시지","voice":"male","script":"Hello, this message is for Mr. Robert Kim. This is Sam from Comfort Home Furniture. Your new sofa is ready, and we will deliver it this Wednesday. Our truck will arrive between one and three p.m. Someone needs to be at home to sign for it. Also, please make sure the doorway is clear, because the sofa is quite large. If Wednesday doesn't work for you, please call me at 555-0163 before Tuesday. Thank you for shopping with us.","graphic":null,"questions":[{"q":"What will be delivered?","choices":["A bed","A table","A desk","A sofa"],"answer":3,"type":"세부 사항","explanation":"'Your new sofa is ready'라고 했으므로 소파가 배송된다."},{"q":"What does the speaker ask the listener to do?","choices":["Clear the doorway","Pay in cash","Pick up the item","Open the garage"],"answer":0,"type":"요청·제안","explanation":"소파가 크기 때문에 'please make sure the doorway is clear'라고 했다. 출입구를 비워 달라는 요청이다."},{"q":"When should the listener call if Wednesday is not good?","choices":["Before Monday","Before Friday","On Wednesday","Before Tuesday"],"answer":3,"type":"세부 사항","explanation":"'please call me at 555-0163 before Tuesday'라고 했으므로 화요일 전에 전화해야 한다."}],"translation":"안녕하세요, 로버트 김 님께 남기는 메시지입니다. 컴포트 홈 가구의 샘입니다. 새 소파가 준비되어 이번 주 수요일에 배송해 드릴 예정입니다. 저희 트럭은 오후 1시에서 3시 사이에 도착합니다. 수령 서명을 하실 분이 집에 계셔야 합니다. 또 소파가 꽤 크니 출입구를 꼭 비워 두세요. 수요일이 안 되시면 화요일 전에 555-0163으로 저에게 전화 주세요. 저희 매장을 이용해 주셔서 감사합니다.","part":4},{"id":"p4-094","level":2,"topic":"박물관 폐관 30분 전 안내","talk_type":"안내 방송","voice":"female","script":"Attention, visitors. The Lakeside History Museum will close in thirty minutes, at five o'clock. Please begin making your way toward the main exit on the first floor. The special exhibit on the second floor, Ships of the Great Lakes, has already closed for the day. However, our gift shop will stay open until five thirty, so you still have time to pick up a souvenir. If you left a coat or bag in the lockers, please remember to collect it before you leave. We hope you enjoyed your visit, and we look forward to seeing you again.","graphic":null,"questions":[{"q":"Where is the announcement being made?","choices":["At a library","At a museum","At a shopping mall","At a theater"],"answer":1,"type":"화자 정보(직업·장소)","explanation":"'The Lakeside History Museum will close in thirty minutes'라고 했으므로 박물관에서 하는 방송이다."},{"q":"What does the speaker say about the special exhibit?","choices":["It is free today.","It has moved to the first floor.","It will open next month.","It is closed for the day."],"answer":3,"type":"세부 사항","explanation":"'has already closed for the day'라고 했으므로 특별 전시는 오늘 이미 마감되었다."},{"q":"What does the speaker remind listeners to do?","choices":["Take their items from the lockers","Buy tickets for tomorrow","Fill out a survey","Return their audio guides"],"answer":0,"type":"요청·제안","explanation":"'If you left a coat or bag in the lockers, please remember to collect it'라고 했으므로 사물함의 물건을 챙기라는 당부다. 설문이나 오디오 가이드는 언급되지 않았다."}],"translation":"관람객 여러분께 알려 드립니다. 레이크사이드 역사박물관은 30분 후인 5시에 문을 닫습니다. 1층 정문 출구 쪽으로 이동해 주시기 바랍니다. 2층 특별 전시 '오대호의 배들'은 오늘 이미 관람이 끝났습니다. 다만 기념품점은 5시 30분까지 영업하므로 아직 기념품을 사실 시간이 있습니다. 사물함에 코트나 가방을 두셨다면 나가시기 전에 꼭 챙겨 가세요. 즐거운 관람이 되셨기를 바라며, 다시 뵙기를 기대합니다.","part":4},{"id":"p4-095","level":2,"topic":"주차장 도색 공사로 주차 구역 변경","talk_type":"회의 발췌","voice":"male","script":"One more thing before we finish. The company is repainting the lines in our parking lot next week. They'll work on one area at a time, so we'll have to park in different places for a few days. On Monday and Tuesday, Area A will be closed, and the work moves to Area B on Wednesday. Our team usually parks in Area A, so for the first two days, please use the visitor lot behind the building. You'll need a temporary pass to park there. I'll put the passes on your desks this afternoon.","graphic":{"title":"Parking Lot Repainting Schedule","rows":[["Day","Closed Area"],["Monday","Area A"],["Tuesday","Area A"],["Wednesday","Area B"],["Thursday","Area C"]]},"questions":[{"q":"What will happen next week?","choices":["Parking lines will be repainted.","A building will be cleaned.","New parking fees will start.","The office will be closed."],"answer":0,"type":"주제·목적","explanation":"'The company is repainting the lines in our parking lot next week'라고 했으므로 주차선 도색 공사가 있다. 주차 요금 이야기는 없다."},{"q":"Look at the graphic. On which day can the listeners park in their usual area again?","choices":["Monday","Tuesday","Wednesday","Saturday"],"answer":2,"type":"시각 자료 연계","explanation":"청자들은 보통 A구역에 주차하는데 표에서 A구역은 월·화요일에만 닫힌다. 따라서 수요일부터 다시 평소 구역을 쓸 수 있다."},{"q":"What will the speaker do this afternoon?","choices":["Call the painting company","Move his car","Send an e-mail","Hand out parking passes"],"answer":3,"type":"다음 할 일","explanation":"'I'll put the passes on your desks this afternoon'이라고 했으므로 임시 주차권을 나눠 줄 것이다."}],"translation":"끝내기 전에 한 가지 더 있습니다. 다음 주에 회사가 주차장 주차선을 다시 칠합니다. 한 구역씩 작업하기 때문에 며칠 동안은 다른 곳에 주차해야 합니다. 월요일과 화요일에는 A구역이 닫히고, 수요일에는 작업이 B구역으로 옮겨 갑니다. 우리 팀은 보통 A구역에 주차하니까 처음 이틀 동안은 건물 뒤 방문객 주차장을 이용해 주세요. 거기에 주차하려면 임시 주차권이 필요합니다. 오늘 오후에 주차권을 여러분 책상에 놓아 두겠습니다.","part":4},{"id":"p4-096","level":2,"topic":"사진관 가족사진 촬영 광고","talk_type":"광고","voice":"female","script":"When was the last time your whole family had a photo taken together? At Brightside Photo Studio, we make it easy. Our professional photographers will help everyone look their best, even the little ones who won't sit still. Each session lasts one hour, and you can change clothes as many times as you like. This month, every family session comes with a free framed print. Sessions fill up fast, especially on weekends, so book online at brightsidephoto.com today. Brightside Photo Studio, where memories last forever.","graphic":null,"questions":[{"q":"What is being advertised?","choices":["A photo studio","A camera store","A clothing shop","An art class"],"answer":0,"type":"주제·목적","explanation":"'At Brightside Photo Studio, we make it easy'라며 가족사진 촬영을 홍보하므로 사진관 광고다. 카메라를 파는 가게가 아니다."},{"q":"What is included this month?","choices":["A framed picture","A second session","A family album","A discount on cameras"],"answer":0,"type":"세부 사항","explanation":"'every family session comes with a free framed print'라고 했으므로 액자에 넣은 사진이 포함된다."},{"q":"Why does the speaker recommend booking soon?","choices":["The price will go up.","The studio is moving.","A photographer is leaving.","Sessions are popular."],"answer":3,"type":"세부 사항","explanation":"'Sessions fill up fast, especially on weekends'라고 했으므로 예약이 빨리 차기 때문에, 즉 인기가 많기 때문이다."}],"translation":"가족 모두가 함께 사진을 찍은 게 언제였나요? 브라이트사이드 사진관에서는 쉽게 해결됩니다. 전문 사진작가들이 가만히 앉아 있지 못하는 어린아이들까지 모두 가장 멋진 모습으로 나오도록 도와드립니다. 촬영은 한 번에 한 시간이며 옷은 원하시는 만큼 갈아입으실 수 있습니다. 이번 달에는 모든 가족 촬영에 액자 사진 한 장을 무료로 드립니다. 촬영 예약은 특히 주말에 빨리 차니 오늘 brightsidephoto.com에서 온라인으로 예약하세요. 추억이 영원히 남는 곳, 브라이트사이드 사진관입니다.","part":4},{"id":"p4-097","level":2,"topic":"새 공항 버스 노선 개통 지역 뉴스","talk_type":"방송·뉴스","voice":"male","script":"In local news, a new bus line between downtown Westport and the airport will start running on Monday. Route 50 will leave from City Hall and make only two stops before reaching the airport, so the trip will take about forty minutes. City officials say the new route will reduce traffic and give travelers a cheaper way to get to their flights. A one-way ticket will cost three dollars, the same as a regular city bus. Riders can pay with cash or a city transit card, but drivers will not be able to give change.","graphic":{"title":"Route 50 Weekday Departures from City Hall","rows":[["First Bus","Last Bus","Frequency"],["5:30 A.M.","11:00 P.M.","Every 20 minutes"]]},"questions":[{"q":"What is the news report mainly about?","choices":["A new bus route","A new airport building","Higher taxi fares","A road closure"],"answer":0,"type":"주제·목적","explanation":"도심과 공항을 잇는 새 버스 노선(Route 50)이 운행을 시작한다는 소식이다. 공항 건물이나 택시 요금 이야기는 아니다."},{"q":"Look at the graphic. What time does the first Route 50 bus leave City Hall on weekdays?","choices":["5:00 A.M.","5:30 A.M.","6:00 A.M.","11:00 P.M."],"answer":1,"type":"시각 자료 연계","explanation":"표의 First Bus 칸을 보면 평일 첫차는 5:30 A.M.이다. 11:00 P.M.은 막차 시각이고, 담화에는 첫차 시각이 나오지 않으므로 표를 확인해야 풀 수 있다."},{"q":"What does the speaker say about paying?","choices":["Drivers cannot give change.","Only cards are accepted.","Tickets must be bought online.","Children ride for free."],"answer":0,"type":"세부 사항","explanation":"'drivers will not be able to give change'라고 했으므로 운전기사가 거스름돈을 줄 수 없다. 현금도 받으므로 카드만 된다는 말은 틀리다."}],"translation":"지역 소식입니다. 웨스트포트 도심과 공항을 잇는 새 버스 노선이 월요일부터 운행을 시작합니다. 50번 버스는 시청에서 출발해 공항에 도착하기 전까지 두 곳에만 정차하므로 약 40분이 걸립니다. 시 관계자들은 새 노선이 교통량을 줄이고 여행객들에게 더 저렴하게 비행기를 타러 갈 방법을 제공할 것이라고 말했습니다. 편도 요금은 일반 시내버스와 같은 3달러입니다. 현금이나 시 교통카드로 낼 수 있지만, 운전기사가 거스름돈을 드릴 수는 없습니다.","part":4},{"id":"p4-098","level":2,"topic":"사내 안전 교육 강사 소개","talk_type":"연설·소개","voice":"female","script":"Good morning, everyone. As you know, all warehouse staff must complete safety training once a year, and today's session will focus on lifting heavy boxes safely. I'm happy to introduce our trainer, Daniel Ortiz. Daniel worked in our shipping department for ten years before he became a safety instructor, so he knows our warehouse very well. He'll begin with a short video, and then you'll practice in small groups. The training will take about two hours. When it's finished, please sign the attendance sheet at the back of the room so we have a record.","graphic":null,"questions":[{"q":"What is the topic of the training?","choices":["Lifting things safely","Using new software","Driving a forklift","Packing orders quickly"],"answer":0,"type":"주제·목적","explanation":"'today's session will focus on lifting heavy boxes safely'라고 했으므로 무거운 상자를 안전하게 드는 방법이 주제다."},{"q":"What is mentioned about Daniel Ortiz?","choices":["He used to work in the shipping department.","He wrote a book about safety.","He is a new manager.","He works for another company."],"answer":0,"type":"세부 사항","explanation":"'Daniel worked in our shipping department for ten years'라고 했으므로 예전에 배송 부서에서 일했다."},{"q":"What should the listeners do after the training?","choices":["Watch a video","Take a test","Return their equipment","Sign a sheet"],"answer":3,"type":"요청·제안","explanation":"'please sign the attendance sheet at the back of the room'이라고 했다. 영상은 교육 시작 때 본다."}],"translation":"여러분, 좋은 아침입니다. 아시다시피 모든 창고 직원은 1년에 한 번 안전 교육을 이수해야 하는데요, 오늘 교육은 무거운 상자를 안전하게 드는 방법에 초점을 맞춥니다. 우리 강사 다니엘 오르티즈 씨를 소개하게 되어 기쁩니다. 다니엘 씨는 안전 강사가 되기 전에 우리 배송 부서에서 10년 동안 일했기 때문에 우리 창고를 아주 잘 압니다. 먼저 짧은 영상을 보신 다음 소그룹으로 실습하게 됩니다. 교육은 약 두 시간 걸립니다. 끝나면 기록을 위해 강의실 뒤쪽에 있는 출석부에 서명해 주세요.","part":4},{"id":"p4-099","level":2,"topic":"동물원 야간 투어","talk_type":"관광·견학 안내","voice":"male","script":"Good evening, and welcome to the Night Safari at Riverside Zoo. Many of our animals sleep during the day and become active after dark, so tonight you'll see things that daytime visitors never get to see. We'll start at the owl house and finish at the bat cave. Now, I know many of you have your phones out. Well, the animals' eyes are very sensitive to light. So please turn off your camera flash for the whole tour. The walk takes about an hour. Stay close to the group, because some paths are quite dark.","graphic":null,"questions":[{"q":"What is special about the tour?","choices":["It is free tonight.","It is led by a scientist.","It includes a meal.","It takes place at night."],"answer":3,"type":"세부 사항","explanation":"'Night Safari'이며 해가 진 뒤 활동하는 동물을 보는 투어이므로 밤에 진행된다는 점이 특별하다."},{"q":"Why does the speaker say, \"I know many of you have your phones out\"?","choices":["To ask people to call a number","To suggest downloading a map","To introduce a rule about photos","To complain about noise"],"answer":2,"type":"의도 파악","explanation":"이 말 뒤에 동물 눈이 빛에 민감하니 카메라 플래시를 끄라고 한다. 사진 촬영 규칙을 꺼내기 위한 말이다."},{"q":"Where will the tour end?","choices":["At the owl house","At the main gate","At the gift shop","At the bat cave"],"answer":3,"type":"세부 사항","explanation":"'We'll start at the owl house and finish at the bat cave'라고 했으므로 박쥐 동굴에서 끝난다."}],"translation":"안녕하세요, 리버사이드 동물원 나이트 사파리에 오신 것을 환영합니다. 많은 동물이 낮에는 자고 해가 진 뒤에 활동하기 때문에, 오늘 밤 여러분은 낮 관람객은 절대 보지 못하는 모습을 보시게 됩니다. 올빼미 사육장에서 시작해 박쥐 동굴에서 끝납니다. 자, 많은 분들이 휴대폰을 꺼내 들고 계신 걸 압니다. 그런데 동물들의 눈은 빛에 아주 민감합니다. 그러니 투어 내내 카메라 플래시를 꺼 주세요. 걷는 시간은 약 한 시간입니다. 일부 길은 꽤 어두우니 일행 가까이 계세요.","part":4},{"id":"p4-100","level":2,"topic":"호텔 객실 무료 업그레이드 안내 전화","talk_type":"전화 메시지","voice":"female","script":"Hello, Ms. Sato. This is Rachel calling from the front desk of the Harbor View Hotel. You're booked with us for three nights starting this Friday. I'm calling because there's a problem with the air conditioning in the room you reserved, and it won't be fixed in time. But here's the good news. We've moved you to a suite on the top floor at no extra charge. It has a much better view of the harbor. Your check-in time is still three p.m. If you have any questions, just call the front desk.","graphic":null,"questions":[{"q":"Who most likely is the speaker?","choices":["A hotel employee","A travel agent","A repair worker","A tour guide"],"answer":0,"type":"화자 정보(직업·장소)","explanation":"'Rachel calling from the front desk of the Harbor View Hotel'이라고 했으므로 호텔 직원이다."},{"q":"What problem does the speaker mention?","choices":["A room has a broken air conditioner.","A reservation was canceled.","The hotel is fully booked.","A payment did not go through."],"answer":0,"type":"세부 사항","explanation":"'there's a problem with the air conditioning in the room you reserved'라고 했으므로 예약한 방의 에어컨이 고장 났다."},{"q":"What does the speaker imply when she says, \"But here's the good news\"?","choices":["The listener can check in early.","The repair is already finished.","The listener will get a better room.","The price has been reduced."],"answer":2,"type":"의도 파악","explanation":"이 말 뒤에 추가 요금 없이 꼭대기 층 스위트룸으로 옮겨 드렸다고 하므로 더 좋은 방을 받게 된다는 뜻이다. 체크인 시간은 그대로 3시다."}],"translation":"안녕하세요, 사토 님. 하버 뷰 호텔 프런트 데스크의 레이첼입니다. 이번 주 금요일부터 3박 예약이 되어 있으신데요. 예약하신 객실의 에어컨에 문제가 있는데 그때까지 수리가 끝나지 않을 것 같아 전화드렸습니다. 하지만 좋은 소식이 있습니다. 추가 요금 없이 꼭대기 층 스위트룸으로 옮겨 드렸습니다. 항구 전망이 훨씬 좋습니다. 체크인 시간은 그대로 오후 3시입니다. 궁금한 점이 있으시면 프런트 데스크로 전화 주세요.","part":4},{"id":"p4-101","level":2,"topic":"새 복합기 사용 방법 안내","talk_type":"회의 발췌","voice":"female","script":"Before we get into today's agenda, I want to tell you about the new copy machine. It was installed by the kitchen yesterday. It's much faster than the old one, and it can scan documents straight to your e-mail. To use it, you'll need to tap your staff ID card on the reader first. That way, we can see how much each department prints. If the machine runs out of paper, extra paper is in the cabinet below it. And if it stops working, please don't try to fix it yourself. Just call Kevin in IT at extension 214.","graphic":null,"questions":[{"q":"Where is the new machine?","choices":["In the lobby","Near the kitchen","In the IT office","Next to the meeting room"],"answer":1,"type":"세부 사항","explanation":"'It was installed by the kitchen yesterday'라고 했으므로 탕비실 옆에 있다."},{"q":"Why do listeners have to use their ID cards?","choices":["To unlock the office door","To get free paper","To track printing by department","To order supplies"],"answer":2,"type":"세부 사항","explanation":"카드를 대야 'we can see how much each department prints'라고 했다. 부서별 인쇄량을 확인하기 위해서다."},{"q":"What should listeners do if the machine breaks?","choices":["Contact the IT department","Use the old machine","Call the manufacturer","Write a report"],"answer":0,"type":"요청·제안","explanation":"'please don't try to fix it yourself. Just call Kevin in IT'라고 했으므로 IT 부서에 연락해야 한다."}],"translation":"오늘 안건에 들어가기 전에 새 복사기에 대해 말씀드리겠습니다. 어제 탕비실 옆에 설치되었습니다. 예전 것보다 훨씬 빠르고 문서를 바로 이메일로 스캔할 수 있습니다. 사용하려면 먼저 사원증을 리더기에 대야 합니다. 그래야 부서별로 얼마나 인쇄하는지 알 수 있습니다. 용지가 떨어지면 여분 용지는 복사기 아래 캐비닛에 있습니다. 그리고 고장 나면 직접 고치려고 하지 마세요. IT팀 케빈에게 내선 214번으로 전화하시면 됩니다.","part":4},{"id":"p4-102","level":3,"topic":"온라인 장보기 배달 앱 광고","talk_type":"광고","voice":"female","script":"Tired of spending your Saturday mornings in long checkout lines? Let FreshCart do the shopping for you. With the FreshCart app, you can choose from over ten thousand grocery items, from fresh fruit to household cleaners, and have them delivered to your door in as little as two hours. Our shoppers carefully pick every item, and if something you ordered is out of stock, they'll text you to suggest a replacement before checking out. And here's a tip: the more you order, the less you pay for delivery. Download FreshCart today and use the code FIRST to get your first delivery absolutely free.","graphic":{"title":"FreshCart Delivery Fees","rows":[["Order Amount","Delivery Fee"],["Under $30","$7.99"],["$30 - $59","$4.99"],["$60 - $99","$2.99"],["$100 or more","Free"]]},"questions":[{"q":"What does FreshCart do when an item is unavailable?","choices":["It cancels the whole order.","It gives a full refund automatically.","It sends a message to the customer.","It delivers the item the next day."],"answer":2,"type":"세부 사항","explanation":"품절이면 'they'll text you to suggest a replacement'라고 했으므로 고객에게 문자를 보낸다. 주문 전체 취소나 자동 환불은 언급되지 않았다."},{"q":"Look at the graphic. How much would a new customer using the code pay for delivery on a $45 order?","choices":["$7.99","$4.99","$2.99","Nothing"],"answer":3,"type":"시각 자료 연계","explanation":"표에 따르면 45달러 주문은 보통 4.99달러지만, 코드 FIRST를 쓰면 'your first delivery absolutely free'라고 했다. 신규 고객은 배달비를 내지 않는다."},{"q":"What is mentioned about the delivery fee?","choices":["It is the same for every order.","It is higher on weekends.","It goes down as orders get larger.","It depends on the customer's location."],"answer":2,"type":"세부 사항","explanation":"'the more you order, the less you pay for delivery'라고 했으므로 주문 금액이 커질수록 배달비가 내려간다. 표의 내용과도 일치한다."}],"translation":"토요일 아침마다 긴 계산대 줄에서 시간을 보내는 게 지겨우신가요? 프레시카트가 대신 장을 봐 드립니다. 프레시카트 앱으로 신선한 과일부터 생활용 세제까지 1만 가지가 넘는 식료품 중에서 고르시면, 빠르면 두 시간 안에 문 앞까지 배달해 드립니다. 저희 쇼퍼들이 모든 상품을 꼼꼼하게 고르며, 주문하신 상품이 품절이면 계산하기 전에 문자로 대체 상품을 제안해 드립니다. 그리고 팁을 하나 드리자면, 많이 주문할수록 배달비가 줄어듭니다. 오늘 프레시카트를 내려받고 코드 FIRST를 입력하시면 첫 배달이 완전히 무료입니다.","part":4},{"id":"p4-103","level":3,"topic":"지역 단편 영화제 개최 뉴스","talk_type":"방송·뉴스","voice":"male","script":"This is Channel 8 Evening News. The Millbrook Short Film Festival returns this weekend for its fifth year, and organizers say it's bigger than ever. More than ninety films from twelve countries will be shown at three theaters downtown. Last year, nearly every screening sold out. Tickets for this year went on sale Monday morning. The festival director, Hannah Price, says this year's highlight is a new competition for student filmmakers, with the winner receiving funding for their next project. In addition, all Sunday screenings at the public library will be free of charge. A full schedule is available on the festival's Web site.","graphic":null,"questions":[{"q":"How many years has the festival been held, including this year?","choices":["Five","Three","Eight","Twelve"],"answer":0,"type":"세부 사항","explanation":"'returns this weekend for its fifth year'라고 했으므로 올해가 다섯 번째다. 12는 참가 국가 수다."},{"q":"Why does the speaker say, \"Last year, nearly every screening sold out\"?","choices":["To suggest that listeners buy tickets soon","To explain why the festival moved","To complain about ticket prices","To announce a new theater"],"answer":0,"type":"의도 파악","explanation":"작년에 거의 매진되었다는 말 바로 뒤에 올해 표가 이미 판매 중이라고 하므로, 서둘러 표를 사라는 뜻을 전하려는 것이다."},{"q":"What is new at this year's festival?","choices":["Films from other countries","Screenings at a library","A contest for students","Online ticket sales"],"answer":2,"type":"세부 사항","explanation":"'this year's highlight is a new competition for student filmmakers'라고 했으므로 학생 경연이 새로 생겼다. 도서관 상영은 무료라는 정보일 뿐 새로운 것이라고 하지 않았다."}],"translation":"채널 8 저녁 뉴스입니다. 밀브룩 단편 영화제가 다섯 번째를 맞아 이번 주말 다시 열리는데, 주최 측은 그 어느 때보다 규모가 크다고 말합니다. 12개국 90편이 넘는 영화가 도심의 극장 세 곳에서 상영됩니다. 작년에는 거의 모든 상영이 매진되었습니다. 올해 표는 월요일 아침부터 판매가 시작되었습니다. 영화제 감독 한나 프라이스는 올해의 하이라이트는 학생 영화 제작자를 위한 새로운 경연이며, 우승자는 다음 작품 제작비를 지원받는다고 말했습니다. 또한 일요일에 공공 도서관에서 열리는 상영은 모두 무료입니다. 전체 일정은 영화제 웹사이트에서 볼 수 있습니다.","part":4},{"id":"p4-104","level":3,"topic":"사내 멘토링 프로그램 시작 발표","talk_type":"연설·소개","voice":"female","script":"Thank you all for joining this lunch session. I'm Monica Reyes from Human Resources, and I'm excited to announce the launch of our new mentoring program. Starting in March, every employee who joined the company within the past year will be paired with an experienced colleague from a different department. We think working with someone outside your own team will give you a broader view of how the company operates. Mentors and mentees will meet at least twice a month, and the company will cover the cost of lunch for those meetings. If you'd like to be a mentor, please complete the short form on the HR page by February fifteenth.","graphic":null,"questions":[{"q":"Who will be paired with mentors?","choices":["Department managers","Employees changing teams","Summer interns","Recently hired employees"],"answer":3,"type":"세부 사항","explanation":"'every employee who joined the company within the past year'라고 했으므로 최근 1년 안에 입사한 직원이 대상이다."},{"q":"According to the speaker, why will mentors come from different departments?","choices":["To reduce costs","To fill open positions","To help employees understand the company better","To improve customer service"],"answer":2,"type":"세부 사항","explanation":"'will give you a broader view of how the company operates'라고 했으므로 회사 운영을 더 넓게 이해하도록 돕기 위해서다."},{"q":"What are interested mentors asked to do?","choices":["Attend a training session","Send an e-mail to their manager","Fill out a form online","Meet with HR in March"],"answer":2,"type":"요청·제안","explanation":"'please complete the short form on the HR page by February fifteenth'라고 했으므로 온라인 양식을 작성해야 한다. 3월은 프로그램 시작 시기다."}],"translation":"이번 점심 모임에 와 주셔서 모두 감사합니다. 인사팀의 모니카 레이예스입니다. 새 멘토링 프로그램을 시작하게 되었음을 알려 드리게 되어 기쁩니다. 3월부터 지난 1년 안에 입사한 모든 직원은 다른 부서의 경험 많은 동료와 짝을 이루게 됩니다. 자기 팀 밖의 사람과 함께 일하면 회사가 어떻게 운영되는지 더 넓게 볼 수 있을 것이라고 생각합니다. 멘토와 멘티는 한 달에 최소 두 번 만나고, 그 만남의 점심 비용은 회사가 부담합니다. 멘토가 되고 싶으신 분은 2월 15일까지 인사팀 페이지의 간단한 양식을 작성해 주세요.","part":4},{"id":"p4-105","level":3,"topic":"도자기 공방 견학","talk_type":"관광·견학 안내","voice":"male","script":"Welcome to Stonebridge Pottery. This workshop has been making plates, bowls, and cups by hand since 1952, and many of our pieces are sold in restaurants across the region. In a moment, you'll see our potters shaping clay on the wheel. Then we'll pass through the glazing room, where the colors are added, and finish at the kilns, the large ovens where everything is fired. The kilns reach over a thousand degrees, so please stay behind the yellow line in that area. Afterward, you're welcome to try the wheel yourself. Aprons are hanging by the door, so grab one before you sit down. Your clothes will thank you.","graphic":null,"questions":[{"q":"What is mentioned about the business?","choices":["It was founded recently.","It has several locations.","It uses machines to make cups.","It sells products to restaurants."],"answer":3,"type":"세부 사항","explanation":"'many of our pieces are sold in restaurants across the region'이라고 했다. 1952년부터 손으로 만들어 왔으므로 최근 설립이나 기계 생산은 틀리다."},{"q":"Why are the listeners asked to stay behind a line?","choices":["The kilns are very hot.","Photography is not allowed.","The floor is wet.","Workers need space."],"answer":0,"type":"요청·제안","explanation":"가마가 1,000도가 넘으니 'please stay behind the yellow line'이라고 했다. 뜨거움 때문이다."},{"q":"What are the listeners encouraged to do before using the wheel?","choices":["Wash their hands","Watch a video","Put on an apron","Pay a small fee"],"answer":2,"type":"세부 사항","explanation":"'Aprons are hanging by the door, so grab one before you sit down'이라고 했으므로 앞치마를 입으라고 권한다."}],"translation":"스톤브리지 도자기 공방에 오신 것을 환영합니다. 이 공방은 1952년부터 접시, 그릇, 컵을 손으로 만들어 왔으며, 저희 제품 상당수가 지역 곳곳의 식당에 팔리고 있습니다. 잠시 후 도예가들이 물레 위에서 흙을 빚는 모습을 보시게 됩니다. 그다음 색을 입히는 유약실을 지나, 모든 작품을 굽는 커다란 오븐인 가마에서 마칩니다. 가마는 1,000도가 넘게 올라가니 그 구역에서는 노란 선 뒤에 계세요. 그 후에는 직접 물레를 돌려 보셔도 됩니다. 문 옆에 앞치마가 걸려 있으니 앉기 전에 하나씩 챙기세요. 옷이 고마워할 겁니다.","part":4},{"id":"p4-106","level":3,"topic":"출장 항공편 결항과 대체편 안내 전화","talk_type":"전화 메시지","voice":"female","script":"Hi, Mr. Walsh, this is Tina from Globe Corporate Travel. I'm calling about your trip to Denver on Thursday. The airline has just canceled your eight-fifteen flight because of a crew shortage. I've looked at the other options, and since your meeting in Denver begins at two in the afternoon, the noon flight wouldn't get you there in time. So I've held a seat for you on the earliest one. It doesn't cost anything extra, but the hold will only last until five p.m. today. Please call me back to confirm, and I'll send you the new ticket right away.","graphic":{"title":"Thursday Flights to Denver","rows":[["Departure","Arrival","Fare"],["6:40 A.M.","8:10 A.M.","$310"],["9:30 A.M.","11:00 A.M.","$345"],["12:00 P.M.","1:30 P.M.","$290"]]},"questions":[{"q":"Why was the original flight canceled?","choices":["Bad weather","A mechanical problem","Not enough staff","Low ticket sales"],"answer":2,"type":"세부 사항","explanation":"'because of a crew shortage'라고 했으므로 승무원 부족, 즉 인력이 모자라서다."},{"q":"Look at the graphic. When will the listener's new flight depart?","choices":["At 6:40 A.M.","At 9:30 A.M.","At 12:00 P.M.","At 8:15 A.M."],"answer":0,"type":"시각 자료 연계","explanation":"화자는 'the earliest one'에 좌석을 잡아 두었다고 했다. 표에서 가장 이른 출발은 오전 6시 40분이다. 8시 15분은 결항된 원래 항공편이다."},{"q":"What does the speaker ask the listener to do?","choices":["Call her by a certain time","Pay an extra fee","Book a hotel room","Contact the airline"],"answer":0,"type":"요청·제안","explanation":"좌석 확보는 오늘 5시까지만 유지되니 'Please call me back to confirm'이라고 했다. 정해진 시간까지 전화해 달라는 요청이다. 추가 요금은 없다."}],"translation":"안녕하세요, 월시 님. 글로브 기업 출장 여행사의 티나입니다. 목요일 덴버 출장 건으로 전화드렸습니다. 항공사가 승무원 부족으로 8시 15분 항공편을 방금 결항시켰습니다. 다른 편을 살펴봤는데, 덴버 회의가 오후 2시에 시작하니 정오 항공편으로는 제시간에 도착하지 못합니다. 그래서 가장 이른 항공편에 좌석을 잡아 두었습니다. 추가 비용은 없지만 좌석 보류는 오늘 오후 5시까지만 유지됩니다. 확인 전화를 주시면 바로 새 항공권을 보내 드리겠습니다.","part":4},{"id":"p4-107","level":3,"topic":"쇼핑센터 화재 경보 점검 안내 방송","talk_type":"안내 방송","voice":"male","script":"Good morning, shoppers and store staff. This is an announcement from Maple Grove Shopping Center management. Between ten and eleven this morning, we'll be testing the fire alarm system throughout the building. During this time, you may hear the alarm several times, and some lights may flash. There's no need to leave the building. However, the elevators on the east side will be stopped during the test, so please use the escalators or the west elevators instead. Store managers, please let your customers know about the test if they seem concerned. Thank you for your understanding.","graphic":null,"questions":[{"q":"What is the purpose of the announcement?","choices":["To explain a scheduled test","To report an emergency","To announce new store hours","To introduce a new store"],"answer":0,"type":"주제·목적","explanation":"오전 10시~11시에 화재 경보 시스템을 점검한다고 미리 알리는 방송이다. 실제 비상 상황이 아니므로 대피할 필요가 없다고 했다."},{"q":"What are listeners told about the east elevators?","choices":["They are being replaced.","They will not be working for a while.","They are for staff only.","They will be crowded."],"answer":1,"type":"세부 사항","explanation":"'the elevators on the east side will be stopped during the test'라고 했으므로 점검 동안 운행하지 않는다."},{"q":"What are store managers asked to do?","choices":["Close their stores early","Lead customers outside","Inform worried customers","Turn off their lights"],"answer":2,"type":"요청·제안","explanation":"'please let your customers know about the test if they seem concerned'라고 했으므로 걱정하는 손님에게 점검 사실을 알려야 한다."}],"translation":"쇼핑객과 매장 직원 여러분, 안녕하세요. 메이플 그로브 쇼핑센터 관리사무소에서 알려 드립니다. 오늘 오전 10시부터 11시 사이에 건물 전체의 화재 경보 시스템을 점검합니다. 이 시간 동안 경보음이 여러 번 울릴 수 있고 일부 조명이 깜박일 수 있습니다. 건물 밖으로 나가실 필요는 없습니다. 다만 점검 중에는 동쪽 엘리베이터가 멈추므로 에스컬레이터나 서쪽 엘리베이터를 이용해 주세요. 매장 관리자분들께서는 손님이 걱정하시는 것 같으면 점검 중이라고 알려 주시기 바랍니다. 양해해 주셔서 감사합니다.","part":4},{"id":"p4-108","level":3,"topic":"직원 건강 검진 일정 안내","talk_type":"회의 발췌","voice":"female","script":"Next, I want to remind everyone about this year's free health checkups. A medical team will be here in the training room for four days next month, and each department has been given a specific date. Please check the schedule I just shared on the screen. If you can't attend on your department's day, you may come on another day, but you'll need to e-mail Ms. Gordon in HR in advance so she can make sure there's room. Also, the checkup includes a blood test, so please don't eat anything after midnight the night before. Coffee and a light breakfast will be provided right after your test.","graphic":{"title":"Health Checkup Schedule (Training Room)","rows":[["Date","Department"],["May 6","Sales"],["May 7","Marketing"],["May 8","Accounting"],["May 9","Engineering"]]},"questions":[{"q":"What is the speaker mainly discussing?","choices":["A new insurance plan","A training program","Health checkups for employees","A change in office hours"],"answer":2,"type":"주제·목적","explanation":"'this year's free health checkups'에 대해 일정과 주의사항을 안내하므로 직원 건강 검진이 주제다."},{"q":"Look at the graphic. The listeners work in Marketing. When is their checkup scheduled?","choices":["May 6","May 7","May 8","May 9"],"answer":1,"type":"시각 자료 연계","explanation":"표에서 Marketing 부서의 날짜는 5월 7일이다."},{"q":"What should listeners do the night before the checkup?","choices":["Avoid eating after midnight","Get enough sleep","Fill out a form","Drink plenty of water"],"answer":0,"type":"요청·제안","explanation":"혈액 검사가 있어 'please don't eat anything after midnight the night before'라고 했다. 자정 이후 금식이 정답이다."}],"translation":"다음으로 올해 무료 건강 검진에 대해 다시 알려 드리겠습니다. 다음 달에 의료진이 나흘 동안 이곳 교육실에 오고, 부서마다 정해진 날짜가 있습니다. 방금 화면에 띄운 일정표를 확인해 주세요. 자기 부서 날짜에 올 수 없으면 다른 날에 와도 되지만, 자리가 있는지 확인할 수 있도록 미리 인사팀 고든 씨에게 이메일을 보내야 합니다. 또 검진에 혈액 검사가 포함되어 있으니 전날 밤 자정 이후에는 아무것도 드시지 마세요. 검사 직후에 커피와 가벼운 아침 식사가 제공됩니다.","part":4},{"id":"p4-109","level":3,"topic":"지역 기업 합동 채용 박람회 뉴스","talk_type":"방송·뉴스","voice":"female","script":"Good morning. If you're looking for work, you may want to head to the Carlton Convention Center this Thursday. More than sixty local employers will be at the city's annual job fair, which runs from nine a.m. to four p.m. Organizers say this year there's especially strong demand for workers in health care and logistics, as two new hospitals and a large distribution center are opening in the area. Visitors are advised to bring several copies of their résumé and to dress professionally, since some companies plan to hold interviews on the spot. Admission is free, but registering online in advance will let you skip the line at the entrance.","graphic":null,"questions":[{"q":"What is the report mainly about?","choices":["A hospital opening","A job fair","A business conference","A college graduation"],"answer":1,"type":"주제·목적","explanation":"60곳 넘는 지역 기업이 참여하는 'the city's annual job fair'를 안내하는 소식이다. 병원 개원은 수요가 많은 이유로만 나온다."},{"q":"Why are health care workers in high demand?","choices":["Many workers are retiring.","Salaries have increased.","New facilities are opening.","A government program has started."],"answer":2,"type":"세부 사항","explanation":"'two new hospitals and a large distribution center are opening in the area'라고 했으므로 새 시설이 문을 열기 때문이다."},{"q":"What is a benefit of registering online?","choices":["A free gift","Avoiding a line","A guaranteed interview","Free parking"],"answer":1,"type":"세부 사항","explanation":"'registering online in advance will let you skip the line at the entrance'라고 했다. 입장 줄을 서지 않아도 된다는 것이 이점이다."}],"translation":"좋은 아침입니다. 일자리를 찾고 계시다면 이번 주 목요일 칼턴 컨벤션 센터에 가 보시는 게 좋겠습니다. 오전 9시부터 오후 4시까지 열리는 시의 연례 채용 박람회에 60곳이 넘는 지역 기업이 참여합니다. 주최 측은 올해 지역에 새 병원 두 곳과 대형 물류센터가 문을 열면서 특히 의료와 물류 분야 인력 수요가 많다고 말합니다. 일부 기업은 현장에서 면접을 볼 계획이므로 이력서를 여러 부 가져오고 단정한 복장을 하라고 권합니다. 입장은 무료이지만 미리 온라인으로 등록하면 입구에서 줄을 서지 않아도 됩니다.","part":4},{"id":"p4-110","level":4,"topic":"웹사이트 개편 사용자 테스트 결과 회의","talk_type":"회의 발췌","voice":"male","script":"Let's turn to the results from last week's user testing of the redesigned Web site. Overall, the feedback was encouraging. Testers found the new menu much easier to navigate, and most of them were able to locate products in under a minute. The one area that caused real trouble was checkout. Seven of the ten testers didn't notice the button for entering a discount code, and three gave up before completing their purchase. Now, our launch date is three weeks away. So I'd like the design team to focus entirely on the checkout page this week and have a revised version ready for a second round of testing by Friday.","graphic":null,"questions":[{"q":"What did testers like about the new Web site?","choices":["Its faster loading speed","Its easier menu","Its lower prices","Its new colors"],"answer":1,"type":"세부 사항","explanation":"'Testers found the new menu much easier to navigate'라고 했으므로 메뉴가 쉬워진 점을 좋아했다."},{"q":"What problem did the testing reveal?","choices":["Product photos were missing.","The site crashed often.","Users had trouble at checkout.","Search results were inaccurate."],"answer":2,"type":"세부 사항","explanation":"'The one area that caused real trouble was checkout'이라며 할인 코드 버튼을 못 찾고 구매를 포기했다고 했다. 결제 단계 문제다."},{"q":"Why does the speaker say, \"our launch date is three weeks away\"?","choices":["To suggest postponing the launch","To stress that the problem must be fixed quickly","To praise the team for being ahead of schedule","To announce a new project"],"answer":1,"type":"의도 파악","explanation":"이 말 뒤에 디자인팀이 이번 주 결제 페이지에만 집중해 금요일까지 수정본을 준비하라고 한다. 시간이 많지 않으니 빨리 고쳐야 한다는 점을 강조하려는 것이다."}],"translation":"지난주 개편 웹사이트 사용자 테스트 결과로 넘어가겠습니다. 전반적으로 반응은 고무적이었습니다. 테스트 참여자들은 새 메뉴가 훨씬 쉽게 이동할 수 있다고 느꼈고, 대부분 1분 안에 제품을 찾았습니다. 정말 문제가 된 한 부분은 결제였습니다. 열 명 중 일곱 명이 할인 코드 입력 버튼을 알아채지 못했고, 세 명은 구매를 마치기 전에 포기했습니다. 자, 출시일이 3주 남았습니다. 그래서 디자인팀은 이번 주에 결제 페이지에만 집중해서 금요일까지 2차 테스트용 수정본을 준비해 주셨으면 합니다.","part":4},{"id":"p4-111","level":4,"topic":"법인 차량 장기 리스 서비스 광고","talk_type":"광고","voice":"male","script":"Running a business means keeping your team on the road, but owning a fleet of vehicles ties up capital and creates endless paperwork. That's where Meridian Fleet Leasing comes in. We provide cars, vans, and light trucks on flexible two- to four-year leases, with maintenance, insurance, and roadside assistance all bundled into a single monthly payment. Our online dashboard lets you track fuel use and service schedules for every vehicle in real time. And if your needs change mid-lease, you can swap vehicles without penalty. Companies that switched to Meridian last year cut their transportation costs by an average of eighteen percent. Call today to schedule a free fleet review with one of our consultants.","graphic":null,"questions":[{"q":"What is included in the monthly payment?","choices":["Fuel costs","Driver training","Vehicle insurance","Parking fees"],"answer":2,"type":"세부 사항","explanation":"'maintenance, insurance, and roadside assistance all bundled into a single monthly payment'라고 했으므로 보험이 포함된다. 연료비는 대시보드로 추적할 수 있을 뿐 포함된다고 하지 않았다."},{"q":"According to the advertisement, what can customers do during a lease?","choices":["Exchange vehicles","Cancel at any time","Buy the vehicle at a discount","Add drivers for free"],"answer":0,"type":"세부 사항","explanation":"'you can swap vehicles without penalty'라고 했으므로 차량을 바꿀 수 있다. 언제든 해지할 수 있다는 말은 없다."},{"q":"What are listeners invited to do?","choices":["Visit a showroom","Arrange a free consultation","Download a mobile app","Take a test drive"],"answer":1,"type":"요청·제안","explanation":"'Call today to schedule a free fleet review with one of our consultants'라고 했으므로 무료 상담(점검) 예약을 권한다."}],"translation":"사업을 운영하려면 직원들이 계속 이동할 수 있어야 하지만, 차량을 여러 대 소유하면 자금이 묶이고 서류 작업이 끝이 없습니다. 바로 그럴 때 메리디안 플릿 리스가 필요합니다. 저희는 승용차, 밴, 소형 트럭을 2~4년의 유연한 리스로 제공하며, 정비·보험·긴급 출동 서비스가 모두 월 1회 납부금에 포함됩니다. 온라인 대시보드로 모든 차량의 연료 사용량과 정비 일정을 실시간으로 확인할 수 있습니다. 그리고 리스 도중 필요가 달라지면 위약금 없이 차량을 바꿀 수 있습니다. 작년에 메리디안으로 바꾼 기업들은 운송비를 평균 18퍼센트 줄였습니다. 오늘 전화하셔서 저희 컨설턴트와 무료 차량 운영 점검 일정을 잡으세요.","part":4},{"id":"p4-112","level":4,"topic":"지역 소매업체 온라인 판매 확대 경제 뉴스","talk_type":"방송·뉴스","voice":"female","script":"In business news, Hartwell's, the family-owned department store chain with eleven locations across the state, announced today that it will invest twenty million dollars over the next two years to expand its online operations. The company says online orders made up just eight percent of its sales last year, well below the industry average. Part of the investment will go toward converting the upper floor of its downtown flagship store into a distribution hub, allowing same-day delivery within the city. Company president Alan Hartwell said no stores will close as a result of the plan. In fact, the company expects to hire about one hundred and fifty additional workers, mostly in warehouse and customer service roles.","graphic":null,"questions":[{"q":"What did Hartwell's announce?","choices":["A merger with another chain","A plan to grow its online business","The closing of several stores","A change in leadership"],"answer":1,"type":"주제·목적","explanation":"'invest twenty million dollars ... to expand its online operations'라고 했으므로 온라인 사업 확대 계획이다. 매장을 닫지 않는다고 분명히 말했다."},{"q":"What will happen to part of the flagship store?","choices":["It will be rented to other businesses.","It will become a distribution center.","It will be turned into a restaurant.","It will be renovated for shoppers."],"answer":1,"type":"세부 사항","explanation":"'converting the upper floor of its downtown flagship store into a distribution hub'라고 했으므로 위층이 물류 거점이 된다."},{"q":"What does the company expect to do?","choices":["Reduce prices","Open new stores in other states","Hire more employees","Sell its warehouse"],"answer":2,"type":"세부 사항","explanation":"'the company expects to hire about one hundred and fifty additional workers'라고 했으므로 직원을 더 채용할 것이다."}],"translation":"경제 소식입니다. 주 전역에 매장 11곳을 둔 가족 경영 백화점 체인 하트웰스가 앞으로 2년간 2,000만 달러를 투자해 온라인 사업을 확대하겠다고 오늘 발표했습니다. 회사에 따르면 작년 온라인 주문은 매출의 8퍼센트에 불과해 업계 평균보다 한참 낮았습니다. 투자금 일부는 도심 대표 매장의 위층을 물류 거점으로 바꾸는 데 쓰여 시내 당일 배송이 가능해집니다. 앨런 하트웰 사장은 이 계획으로 문을 닫는 매장은 없을 것이라고 말했습니다. 오히려 회사는 주로 창고와 고객 서비스 분야에서 약 150명을 추가로 채용할 것으로 예상합니다.","part":4},{"id":"p4-113","level":4,"topic":"업계 시상식 공로상 수상자 소개","talk_type":"연설·소개","voice":"male","script":"Our final award this evening recognizes someone whose influence on this industry is hard to overstate. When Dr. Evelyn Marsh founded her small packaging lab thirty years ago, few people believed that food containers could be made from plant fibers at a reasonable cost. Today, the methods she developed are used by manufacturers on four continents, and her lab has trained more than two hundred engineers, many of whom are in this room tonight. Dr. Marsh has also been a generous advocate for young researchers, funding scholarships through her own foundation. It is my great honor to present this year's Lifetime Achievement Award to Dr. Evelyn Marsh. Please join me in welcoming her to the stage.","graphic":null,"questions":[{"q":"What field has Dr. Marsh worked in?","choices":["Food packaging","Agriculture","Restaurant management","Medical research"],"answer":0,"type":"화자 정보(직업·장소)","explanation":"소규모 포장 연구소를 세워 식물 섬유로 식품 용기를 만드는 방법을 개발했다고 하므로 식품 포장 분야다. 식물 섬유가 나온다고 농업 분야는 아니다."},{"q":"What does the speaker say about many people in the audience?","choices":["They were trained at Dr. Marsh's lab.","They received scholarships.","They traveled from other continents.","They nominated Dr. Marsh."],"answer":0,"type":"세부 사항","explanation":"'her lab has trained more than two hundred engineers, many of whom are in this room tonight'라고 했으므로 청중 다수가 그 연구소에서 교육받았다."},{"q":"What will most likely happen next?","choices":["A video will be shown.","Dr. Marsh will come to the stage.","The audience will have dinner.","Another award will be presented."],"answer":1,"type":"다음 할 일","explanation":"'Please join me in welcoming her to the stage'라고 했으므로 마시 박사가 무대에 오를 것이다. 이번 상이 오늘 밤 마지막 상이다."}],"translation":"오늘 저녁 마지막 상은 이 업계에 끼친 영향을 아무리 강조해도 지나치지 않은 분께 드립니다. 에블린 마시 박사가 30년 전 작은 포장 연구소를 세웠을 때, 식품 용기를 합리적인 비용으로 식물 섬유로 만들 수 있다고 믿은 사람은 거의 없었습니다. 오늘날 박사가 개발한 방법은 네 개 대륙의 제조업체들이 사용하고 있고, 박사의 연구소는 200명이 넘는 엔지니어를 길러 냈으며 그중 상당수가 오늘 밤 이 자리에 계십니다. 마시 박사는 또한 자신의 재단을 통해 장학금을 지원하며 젊은 연구자들을 아낌없이 후원해 왔습니다. 올해의 평생 공로상을 에블린 마시 박사께 드리게 되어 큰 영광입니다. 함께 박사님을 무대로 맞아 주십시오.","part":4},{"id":"p4-114","level":4,"topic":"식품 회사 시험 주방 견학","talk_type":"관광·견학 안내","voice":"female","script":"Welcome to the Northfield Foods test kitchen. This is where every new product we sell, from frozen pizzas to snack bars, is developed and tasted before it reaches store shelves. Our chefs typically test a recipe thirty or forty times before it's approved. Today you'll get to take part in that process. You'll be tasting samples from our upcoming soup line and rating each one on the cards you were given at reception. Your feedback really does matter; last year, visitor ratings led us to cancel two products entirely. Since you're the afternoon group, you'll begin with the soups first and then move on to the dessert samples. Please let a staff member know if you have any food allergies before we begin.","graphic":{"title":"Visitor Tasting Schedule","rows":[["Group","First Tasting","Second Tasting"],["Morning","Snack bars","Soups"],["Afternoon","Soups","Desserts"],["Evening","Desserts","Frozen pizzas"]]},"questions":[{"q":"What does the speaker say about the chefs?","choices":["They test recipes many times.","They trained in other countries.","They will lead a cooking class.","They designed the kitchen."],"answer":0,"type":"세부 사항","explanation":"'Our chefs typically test a recipe thirty or forty times before it's approved'라고 했으므로 레시피를 여러 번 시험한다."},{"q":"Why does the speaker mention that two products were canceled?","choices":["To apologize for a mistake","To show that visitors' opinions are important","To explain why the tour is shorter","To introduce a new product line"],"answer":1,"type":"주제·목적","explanation":"'Your feedback really does matter' 바로 뒤에 방문객 평가로 제품 두 개를 없앴다는 예를 든다. 방문객 의견이 실제로 중요하다는 것을 보여 주려는 것이다."},{"q":"Look at the graphic. What will the listeners taste second?","choices":["Snack bars","Soups","Desserts","Frozen pizzas"],"answer":2,"type":"시각 자료 연계","explanation":"청자는 오후 그룹(afternoon group)이다. 표에서 오후 그룹의 두 번째 시식은 Desserts다. 수프는 첫 번째다."}],"translation":"노스필드 식품 시험 주방에 오신 것을 환영합니다. 냉동 피자부터 스낵바까지 저희가 판매하는 모든 신제품은 매장 진열대에 오르기 전에 이곳에서 개발되고 맛 평가를 거칩니다. 저희 셰프들은 보통 레시피 하나를 승인받기까지 30~40번 시험합니다. 오늘은 여러분도 그 과정에 참여하시게 됩니다. 곧 출시될 수프 제품군의 샘플을 맛보시고, 접수처에서 받으신 카드에 하나씩 점수를 매기시면 됩니다. 여러분의 의견은 정말로 중요합니다. 작년에는 방문객 평가 때문에 제품 두 개를 아예 취소하기도 했습니다. 여러분은 오후 그룹이니 수프를 먼저 맛보신 다음 디저트 샘플로 넘어가겠습니다. 시작하기 전에 음식 알레르기가 있으시면 직원에게 알려 주세요.","part":4},{"id":"p4-115","level":4,"topic":"인쇄소의 카탈로그 용지 품절과 대체 용지 제안 전화","talk_type":"전화 메시지","voice":"male","script":"Hi, Ms. Delgado, it's Victor from Precision Print. I'm calling about the spring catalog order for your garden supply company. Unfortunately, our supplier just told us the paper you selected, the Classic Gloss, is out of stock until next month. I know the catalog has to be in customers' mailboxes before your March sale. So rather than wait, I'd suggest switching to a comparable paper. I'd recommend the one with the matte finish, since it's actually a little cheaper than what you chose and the photos of your plants will still look sharp. I've put a sample of it in the mail today. Once you've had a look, just let me know, and we can start printing right away.","graphic":{"title":"Paper Options (per 1,000 pages)","rows":[["Paper","Finish","Price"],["Classic Gloss","Glossy","$48"],["Premium Silk","Semi-gloss","$52"],["Natural Matte","Matte","$44"],["Eco Recycled","Matte","$50"]]},"questions":[{"q":"What problem does the speaker mention?","choices":["A deadline was missed.","A printing machine is broken.","Some paper is not available.","A payment has not been received."],"answer":2,"type":"세부 사항","explanation":"고객이 고른 Classic Gloss 용지가 'out of stock until next month'라고 했으므로 용지를 구할 수 없는 것이 문제다."},{"q":"Why does the speaker say, \"I know the catalog has to be in customers' mailboxes before your March sale\"?","choices":["To explain why waiting is not a good idea","To ask for a later delivery date","To remind the listener to pay","To suggest canceling the order"],"answer":0,"type":"의도 파악","explanation":"이 말 뒤에 'So rather than wait'라며 다른 용지로 바꾸자고 제안한다. 3월 할인 전에 도착해야 하므로 다음 달까지 기다리면 안 된다는 뜻이다."},{"q":"Look at the graphic. Which paper does the speaker recommend?","choices":["Classic Gloss","Premium Silk","Natural Matte","Eco Recycled"],"answer":2,"type":"시각 자료 연계","explanation":"무광(matte)이면서 원래 고른 Classic Gloss(48달러)보다 조금 싼 용지라고 했다. 무광 용지 중 48달러보다 싼 것은 Natural Matte(44달러)다. Eco Recycled는 무광이지만 50달러로 더 비싸다."}],"translation":"안녕하세요, 델가도 님. 프리시전 프린트의 빅터입니다. 귀사 원예용품 회사의 봄 카탈로그 주문 건으로 전화드렸습니다. 아쉽게도 공급업체에서 방금 고르신 클래식 글로스 용지가 다음 달까지 품절이라고 알려 왔습니다. 카탈로그가 3월 할인 행사 전에 고객 우편함에 도착해야 한다는 것을 알고 있습니다. 그래서 기다리기보다는 비슷한 용지로 바꾸시길 제안드립니다. 무광 마감 용지를 추천하는데, 고르신 것보다 실제로 조금 더 저렴하고 식물 사진도 여전히 선명하게 나옵니다. 오늘 샘플을 우편으로 보내 드렸습니다. 보시고 알려 주시면 바로 인쇄를 시작할 수 있습니다.","part":4},{"id":"p4-116","level":4,"topic":"무역 박람회 셔틀버스 운행 변경 안내 방송","talk_type":"안내 방송","voice":"female","script":"Attention, all exhibitors and visitors to the International Home Products Expo. Due to road construction on Harbor Boulevard, the shuttle bus stop at the Bayside Hotel has been moved to the hotel's rear entrance on Pine Street, effective immediately. In addition, because of higher demand than expected, we've added extra buses during the evening rush. Shuttles will now leave the convention center more frequently after five o'clock. Please note that the last shuttle of the day departs at nine p.m. Exhibitors who need to stay later to pack up their booths can request a taxi voucher at the organizer's office in Hall C.","graphic":{"title":"Expo Shuttle Service (from Convention Center)","rows":[["Time","Frequency"],["8:00 A.M. - 12:00 P.M.","Every 15 minutes"],["12:00 P.M. - 5:00 P.M.","Every 30 minutes"],["5:00 P.M. - 9:00 P.M.","Every 10 minutes"]]},"questions":[{"q":"Why has a shuttle stop been moved?","choices":["A hotel is being renovated.","There is road construction.","The expo has changed locations.","There is not enough parking."],"answer":1,"type":"세부 사항","explanation":"'Due to road construction on Harbor Boulevard'라고 했으므로 도로 공사 때문이다. 호텔 공사는 아니다."},{"q":"Look at the graphic. How often will shuttles run at 6 P.M.?","choices":["Every 10 minutes","Every 15 minutes","Every 30 minutes","Every hour"],"answer":0,"type":"시각 자료 연계","explanation":"오후 6시는 표의 5:00 P.M.~9:00 P.M. 구간에 해당하므로 10분 간격이다. 저녁에 버스를 늘렸다는 방송 내용과도 맞다."},{"q":"What can exhibitors who stay late do?","choices":["Use a staff parking lot","Store items in Hall C","Get a voucher for a taxi","Take a later shuttle"],"answer":2,"type":"요청·제안","explanation":"늦게까지 남는 전시업체는 'can request a taxi voucher at the organizer's office in Hall C'라고 했다. 마지막 셔틀은 9시라 더 늦은 셔틀은 없다."}],"translation":"국제 홈 제품 박람회의 모든 전시업체와 방문객 여러분께 알려 드립니다. 하버 대로의 도로 공사로 인해 베이사이드 호텔 셔틀버스 정류장이 지금부터 파인 스트리트 쪽 호텔 후문으로 옮겨졌습니다. 또한 예상보다 이용객이 많아 저녁 혼잡 시간대에 버스를 추가했습니다. 이제 5시 이후에는 컨벤션 센터에서 셔틀이 더 자주 출발합니다. 그날의 마지막 셔틀은 오후 9시에 출발한다는 점에 유의해 주세요. 부스 정리 때문에 더 늦게 남아야 하는 전시업체는 C홀 주최 측 사무실에서 택시 쿠폰을 요청하실 수 있습니다.","part":4},{"id":"p4-117","level":4,"topic":"출장비 규정 변경 설명","talk_type":"회의 발췌","voice":"male","script":"I've got an update on the travel policy that takes effect on the first of next month. Finance reviewed last year's expenses and found that hotel costs were about twenty percent over budget, mostly because people were booking on their own at the last minute. So from now on, all hotel reservations must go through the company's booking portal, where we've negotiated lower rates with several chains. Meal allowances, on the other hand, are going up slightly, to sixty dollars a day. I realize the portal will take some getting used to. That's why Finance is holding two short online demonstrations next week. I'd strongly encourage anyone who travels regularly to attend one of them.","graphic":null,"questions":[{"q":"According to the speaker, why is the policy changing?","choices":["Airline prices have risen.","Hotel spending was too high.","Employees requested more meal money.","A new travel agency was hired."],"answer":1,"type":"세부 사항","explanation":"'hotel costs were about twenty percent over budget'라고 했으므로 호텔 비용이 너무 많이 나왔기 때문이다."},{"q":"What is mentioned about meal allowances?","choices":["They will be removed.","They will stay the same.","They will increase a little.","They will be paid in advance."],"answer":2,"type":"세부 사항","explanation":"'Meal allowances, on the other hand, are going up slightly, to sixty dollars a day'라고 했으므로 조금 오른다."},{"q":"What does the speaker encourage frequent travelers to do?","choices":["Book hotels early","Attend a demonstration","Submit receipts weekly","Use a company credit card"],"answer":1,"type":"요청·제안","explanation":"포털 사용 시연회가 열린다며 'I'd strongly encourage anyone who travels regularly to attend one of them'이라고 했다."}],"translation":"다음 달 1일부터 시행되는 출장 규정에 대해 알려 드릴 것이 있습니다. 재무팀이 작년 경비를 검토한 결과, 호텔 비용이 예산을 약 20퍼센트 초과했는데, 주로 직원들이 막판에 각자 예약했기 때문이었습니다. 그래서 앞으로 모든 호텔 예약은 회사 예약 포털을 통해야 하며, 포털에서는 여러 호텔 체인과 협상한 더 낮은 요금을 이용할 수 있습니다. 반면 식비 수당은 하루 60달러로 조금 오릅니다. 포털에 익숙해지려면 시간이 좀 걸린다는 건 압니다. 그래서 재무팀이 다음 주에 짧은 온라인 시연회를 두 번 엽니다. 출장을 자주 다니는 분들은 꼭 둘 중 하나에 참석하시길 강력히 권합니다.","part":4},{"id":"p4-118","level":5,"topic":"신임 CEO의 첫 타운홀 연설","talk_type":"연설·소개","voice":"female","script":"Thank you all for being here, both in person and online. I've now spent my first six weeks as CEO visiting our plants and offices, and I want to share what I've heard. Over and over, people told me that good ideas get stuck because approvals take too long. One engineer in Leeds described waiting four months for permission to buy a forty-dollar part. Now, I'm not going to stand here and promise to fix everything overnight. What I will do is this: starting next quarter, managers will be able to approve purchases of up to five thousand dollars without sending them to headquarters. We'll review how that works in six months, and if it's successful, we'll go further. I'll also be holding open question sessions like this one every quarter, so please keep the feedback coming.","graphic":null,"questions":[{"q":"What has the speaker been doing for the past six weeks?","choices":["Visiting company facilities","Hiring new managers","Negotiating with suppliers","Reviewing financial reports"],"answer":0,"type":"세부 사항","explanation":"'visiting our plants and offices'라고 했으므로 회사 시설을 방문했다. 공장과 사무실이 'facilities'로 바꿔 표현되었다."},{"q":"Why does the speaker mention an engineer in Leeds?","choices":["To praise an outstanding employee","To illustrate a common complaint","To announce a new office","To explain a budget cut"],"answer":1,"type":"주제·목적","explanation":"승인이 너무 오래 걸린다는 의견을 반복해 들었다고 한 뒤, 40달러짜리 부품을 사는 데 넉 달을 기다린 사례를 든다. 흔한 불만의 구체적인 예다."},{"q":"What does the speaker imply when she says, \"I'm not going to stand here and promise to fix everything overnight\"?","choices":["She disagrees with the employees' feedback.","She plans to make changes gradually.","She will leave the decision to managers.","She needs more time before taking any action."],"answer":1,"type":"의도 파악","explanation":"이 말 뒤에 우선 관리자 승인 한도를 5,000달러로 올리고 6개월 뒤 검토해 성공하면 더 나아가겠다고 한다. 단계적으로 바꾸겠다는 뜻이다. 다음 분기에 바로 실행하므로 아무 조치도 미룬다는 해석은 틀리다."}],"translation":"현장과 온라인으로 함께해 주신 모든 분께 감사드립니다. CEO로서 첫 6주 동안 우리 공장과 사무실을 방문했는데, 들은 이야기를 공유하고 싶습니다. 승인이 너무 오래 걸려서 좋은 아이디어가 막힌다는 말을 계속해서 들었습니다. 리즈의 한 엔지니어는 40달러짜리 부품을 사기 위해 허가를 넉 달 동안 기다렸다고 했습니다. 자, 저는 여기 서서 하룻밤 사이에 모든 걸 고치겠다고 약속하지는 않겠습니다. 대신 이렇게 하겠습니다. 다음 분기부터 관리자는 5,000달러까지의 구매를 본사로 보내지 않고 승인할 수 있습니다. 6개월 뒤 그 결과를 검토하고, 성공적이면 더 나아가겠습니다. 또 이런 공개 질의응답 시간을 분기마다 열 테니 계속 의견을 보내 주십시오.","part":4},{"id":"p4-119","level":5,"topic":"물류센터 자동화와 지역 고용 영향 뉴스","talk_type":"방송·뉴스","voice":"male","script":"Turning to business, Corvant Logistics confirmed this morning that its distribution center outside Fairmont will be largely automated by the end of next year, with robotic systems taking over much of the sorting and packing currently done by hand. The announcement had raised concerns in a town where the center is the largest private employer. However, the company insists that no permanent staff will be laid off. Instead, it plans to reduce its reliance on seasonal temporary workers and to retrain about three hundred existing employees as equipment technicians through a partnership with Fairmont Community College. Local officials have cautiously welcomed the plan, though some economists point out that the loss of seasonal jobs could still hit students and part-time workers hard. We'll have more on this story at six.","graphic":null,"questions":[{"q":"What did Corvant Logistics confirm?","choices":["It will relocate its distribution center.","It will automate much of its operations.","It will build a new college campus.","It will be acquired by a competitor."],"answer":1,"type":"주제·목적","explanation":"물류센터가 'largely automated by the end of next year'라고 확인했다. 이전이나 인수 이야기는 없다."},{"q":"How will the company handle its permanent employees?","choices":["It will offer them early retirement.","It will transfer them to another city.","It will train them for new roles.","It will reduce their working hours."],"answer":2,"type":"세부 사항","explanation":"'retrain about three hundred existing employees as equipment technicians'라고 했으므로 새 역할을 위해 재교육한다. 정규직 해고는 없다고 했다."},{"q":"What concern do some economists raise?","choices":["Robots may be too expensive.","The college lacks instructors.","Temporary job losses could affect certain groups.","The town may lose tax revenue."],"answer":2,"type":"세부 사항","explanation":"일부 경제학자들은 'the loss of seasonal jobs could still hit students and part-time workers hard'라고 지적했다. 계절직 감소가 학생·시간제 근로자에게 타격을 줄 수 있다는 우려다."}],"translation":"경제 소식으로 넘어가겠습니다. 코반트 로지스틱스는 페어몬트 외곽 물류센터를 내년 말까지 대부분 자동화해 현재 사람 손으로 하는 분류와 포장 작업 상당 부분을 로봇 시스템이 맡게 될 것이라고 오늘 아침 확인했습니다. 이 발표는 물류센터가 지역 최대 민간 고용주인 이 도시에서 우려를 낳았습니다. 그러나 회사는 정규직 직원은 한 명도 해고하지 않을 것이라고 강조합니다. 대신 계절성 임시직 의존도를 줄이고, 페어몬트 커뮤니티 칼리지와 협력해 기존 직원 약 300명을 장비 기술자로 재교육할 계획입니다. 지역 관계자들은 이 계획을 조심스럽게 환영했지만, 일부 경제학자들은 계절직 일자리가 사라지면 여전히 학생과 시간제 근로자가 큰 타격을 받을 수 있다고 지적합니다. 이 소식은 6시에 자세히 전해 드리겠습니다.","part":4},{"id":"p4-120","level":5,"topic":"콜센터 위탁업체 재계약 검토 회의","talk_type":"회의 발췌","voice":"female","script":"As you know, our contract with our current call center provider expires in June, so we asked three firms, including the current one, to submit proposals. I've summarized the key figures on this slide. On cost alone, the choice is obvious. But cost isn't the only factor. Our customer satisfaction scores dropped last year, and the main complaint was that agents couldn't resolve problems on the first call. With that in mind, I'm recommending the firm with the highest first-call resolution rate, even though it's not the cheapest option. Its satisfaction score is also the strongest of the three. Before we take this to the board, though, I'd like Raj to contact two of that firm's current clients and ask about their experience.","graphic":{"title":"Call Center Proposals","rows":[["Provider","Annual Cost","First-Call Resolution","Satisfaction Score"],["Clearline (current)","$1.2M","68%","3.6"],["VoxAssist","$0.9M","71%","3.8"],["Nexus Support","$1.4M","84%","4.5"]]},"questions":[{"q":"What does the speaker mean when she says, \"On cost alone, the choice is obvious\"?","choices":["The current provider is the most affordable.","One provider is clearly the cheapest.","All providers charge similar prices.","The budget has already been approved."],"answer":1,"type":"의도 파악","explanation":"비용만 보면 한 업체가 분명히 가장 싸다는 뜻이며, 바로 'But cost isn't the only factor'라며 다른 기준을 꺼낸다. 표에서 가장 싼 곳은 현재 업체가 아니라 VoxAssist다."},{"q":"Look at the graphic. Which provider does the speaker recommend?","choices":["Clearline","VoxAssist","Nexus Support","None of them"],"answer":2,"type":"시각 자료 연계","explanation":"가장 싸지는 않지만 첫 통화 해결률이 가장 높은 업체를 추천했다. 표에서 해결률이 84%로 가장 높고 만족도도 4.5로 가장 높은 곳은 Nexus Support다."},{"q":"What is Raj asked to do?","choices":["Prepare a presentation for the board","Negotiate a lower price","Speak with some of the provider's clients","Extend the current contract"],"answer":2,"type":"요청·제안","explanation":"'I'd like Raj to contact two of that firm's current clients and ask about their experience'라고 했으므로 그 업체의 고객사와 이야기해 보라는 요청이다. 이사회 보고는 그 이후 단계다."}],"translation":"아시다시피 현재 콜센터 위탁업체와의 계약이 6월에 끝나서, 현재 업체를 포함한 세 회사에 제안서를 요청했습니다. 주요 수치를 이 슬라이드에 정리했습니다. 비용만 보면 선택은 뻔합니다. 하지만 비용만이 기준은 아닙니다. 작년에 고객 만족도 점수가 떨어졌는데, 가장 큰 불만은 상담원이 첫 통화에서 문제를 해결하지 못한다는 것이었습니다. 그 점을 고려해, 가장 싼 선택은 아니지만 첫 통화 해결률이 가장 높은 업체를 추천합니다. 만족도 점수도 세 곳 중 가장 높습니다. 다만 이사회에 올리기 전에 라지 씨가 그 업체의 현재 고객사 두 곳에 연락해서 경험을 물어봐 주셨으면 합니다.","part":4},{"id":"p4-121","level":5,"topic":"기업용 보안 인식 교육 프로그램 광고","talk_type":"광고","voice":"male","script":"Most data breaches don't begin with sophisticated hacking. They begin with an employee clicking a link in an e-mail that looks perfectly legitimate. Firewalls and antivirus software can only do so much; ultimately, your staff are your first line of defense. SecureMind's training platform turns that weakness into a strength. Instead of a single annual seminar that people forget by the following week, we deliver five-minute lessons each month, along with realistic simulated phishing e-mails tailored to your industry. Managers receive detailed reports showing which departments are most at risk, so you can target follow-up training where it's needed most. Clients typically see a sixty percent drop in risky clicks within the first six months. Visit securemind.com to request a free pilot for up to fifty employees.","graphic":null,"questions":[{"q":"According to the speaker, how do most data breaches start?","choices":["Through outdated software","Through employee mistakes","Through stolen laptops","Through weak passwords"],"answer":1,"type":"세부 사항","explanation":"'They begin with an employee clicking a link in an e-mail'이라고 했으므로 직원의 실수에서 시작된다. 비밀번호나 노트북 도난은 언급되지 않았다."},{"q":"How is SecureMind's approach different from traditional training?","choices":["It is delivered in short, regular sessions.","It is taught by former hackers.","It is offered only to managers.","It replaces antivirus software."],"answer":0,"type":"세부 사항","explanation":"연 1회 세미나 대신 'five-minute lessons each month'를 제공한다고 했으므로 짧고 정기적인 교육이 차별점이다. 백신 소프트웨어를 대신한다는 말은 없다."},{"q":"What does SecureMind offer potential clients?","choices":["A discount on annual plans","A free security audit","A trial for a limited number of staff","A consultation with an expert"],"answer":2,"type":"요청·제안","explanation":"'request a free pilot for up to fifty employees'라고 했으므로 최대 50명 대상 무료 시범 운영을 제공한다. 'pilot'이 'trial'로 바뀌어 표현되었다."}],"translation":"대부분의 데이터 유출은 정교한 해킹으로 시작되지 않습니다. 완벽하게 정상으로 보이는 이메일 속 링크를 직원이 클릭하는 데서 시작됩니다. 방화벽과 백신 소프트웨어가 할 수 있는 일에는 한계가 있습니다. 결국 직원이 첫 번째 방어선입니다. 시큐어마인드의 교육 플랫폼은 그 약점을 강점으로 바꿔 드립니다. 다음 주면 잊어버리는 연 1회 세미나 대신, 매달 5분짜리 강의와 함께 귀사 업종에 맞춘 실제 같은 모의 피싱 이메일을 보내 드립니다. 관리자는 어느 부서가 가장 위험한지 보여 주는 상세 보고서를 받아, 가장 필요한 곳에 후속 교육을 집중할 수 있습니다. 고객사들은 보통 처음 6개월 안에 위험한 클릭이 60퍼센트 줄어듭니다. securemind.com에서 최대 50명까지 무료 시범 운영을 신청하세요.","part":4},{"id":"p4-122","level":5,"topic":"사무실 임대차 계약 갱신 협상 관련 중개인 메시지","talk_type":"전화 메시지","voice":"female","script":"Hello, Mr. Whitaker, this is Diane Fowler from Crestview Commercial Realty. I've just finished talking with your landlord about renewing the lease on your office space. As expected, they're proposing a seven percent rent increase, which they say reflects current market rates in the area. Now, I checked recent deals in comparable buildings nearby, and frankly, they're overstating things a bit. I think there's room to push back. My suggestion is that we offer to sign a longer, five-year term in exchange for keeping the increase to around three percent. Landlords generally value that kind of stability. That said, it does commit you to the space for longer, so you'll want to consider your company's growth plans. Could we set up a call before Thursday? That's when they're expecting our response.","graphic":null,"questions":[{"q":"Who most likely is the speaker?","choices":["A property owner","A real estate agent","A company accountant","A building manager"],"answer":1,"type":"화자 정보(직업·장소)","explanation":"부동산 회사(Crestview Commercial Realty) 소속으로 청자 대신 임대인과 협상하고 있으므로 부동산 중개인이다. 건물주(landlord)는 협상 상대다."},{"q":"What does the speaker imply when she says, \"they're overstating things a bit\"?","choices":["The landlord's increase is higher than the market justifies.","The office space is smaller than advertised.","The landlord has made errors in the contract.","Nearby buildings are in better condition."],"answer":0,"type":"의도 파악","explanation":"인근 비슷한 건물의 최근 거래를 확인했다며 이 말을 하고 'there's room to push back'이라고 이어 간다. 7% 인상이 시세보다 과하다는 뜻이다."},{"q":"What does the speaker suggest the listener consider?","choices":["Moving to a different building","Paying the rent in advance","His company's plans for expansion","Hiring a lawyer to review the lease"],"answer":2,"type":"세부 사항","explanation":"5년 계약은 공간에 더 오래 묶이므로 'you'll want to consider your company's growth plans'라고 했다. 회사의 성장(확장) 계획을 고려하라는 것이다."}],"translation":"안녕하세요, 휘태커 님. 크레스트뷰 상업 부동산의 다이앤 파울러입니다. 방금 사무실 임대차 계약 갱신 건으로 임대인과 이야기를 마쳤습니다. 예상대로 임대인은 7퍼센트 임대료 인상을 제안하고 있으며, 그것이 이 지역의 현재 시세를 반영한 것이라고 말합니다. 그런데 제가 근처 비슷한 건물의 최근 거래를 확인해 보니, 솔직히 좀 부풀려 말하고 있습니다. 반박할 여지가 있다고 봅니다. 제 제안은 인상률을 3퍼센트 정도로 유지하는 대신 5년의 더 긴 계약을 맺겠다고 제시하는 것입니다. 임대인들은 대체로 그런 안정성을 중요하게 여깁니다. 다만 그렇게 하면 그 공간에 더 오래 묶이게 되니 회사의 성장 계획을 고려해 보셔야 합니다. 목요일 전에 통화할 수 있을까요? 그날 임대인이 저희 답변을 기다리고 있습니다.","part":4},{"id":"p4-123","level":5,"topic":"해상 풍력 단지 운영 센터 견학","talk_type":"관광·견학 안내","voice":"male","script":"Good morning, and welcome to the operations center for the Northgate Offshore Wind Farm. The eighty turbines you saw from the ferry this morning are located about twenty kilometers out to sea, and together they generate enough electricity for roughly three hundred thousand homes. Because the turbines are so remote, almost everything is monitored from this building. The large screen ahead of you displays real-time data from every turbine, including wind speed and output. If a component shows signs of wear, our engineers can often schedule repairs weeks before it actually fails, which means fewer costly emergency trips by boat. In a moment, we'll go upstairs to the control room. Space is limited there, so I'll split you into two groups of ten. Please keep your voices low, as the operators are on duty.","graphic":null,"questions":[{"q":"How did the listeners most likely travel earlier today?","choices":["By helicopter","By boat","By train","By bus"],"answer":1,"type":"세부 사항","explanation":"'The eighty turbines you saw from the ferry this morning'이라고 했으므로 오늘 아침 배(여객선)를 타고 왔다."},{"q":"According to the speaker, what is an advantage of the monitoring system?","choices":["It allows problems to be found early.","It increases the speed of the turbines.","It reduces the number of staff needed.","It lowers electricity prices for homes."],"answer":0,"type":"세부 사항","explanation":"부품 마모 징후가 보이면 'schedule repairs weeks before it actually fails'라고 했으므로 문제를 미리 발견할 수 있다는 것이 장점이다."},{"q":"Why will the listeners be divided into groups?","choices":["The tour has two different routes.","The control room is small.","Some visitors are leaving early.","Operators will lead each group."],"answer":1,"type":"세부 사항","explanation":"관제실은 'Space is limited there'라서 열 명씩 두 그룹으로 나눈다고 했다. 공간이 좁기 때문이다."}],"translation":"좋은 아침입니다. 노스게이트 해상 풍력 단지 운영 센터에 오신 것을 환영합니다. 오늘 아침 여객선에서 보신 터빈 80기는 바다로 약 20킬로미터 나가 있으며, 모두 합쳐 약 30만 가구가 쓸 전기를 생산합니다. 터빈이 아주 멀리 떨어져 있기 때문에 거의 모든 것을 이 건물에서 감시합니다. 앞에 있는 대형 화면에는 풍속과 발전량을 포함해 모든 터빈의 실시간 데이터가 표시됩니다. 어떤 부품에 마모 징후가 보이면 엔지니어들이 실제로 고장 나기 몇 주 전에 수리 일정을 잡을 수 있는 경우가 많아, 비용이 많이 드는 긴급 출동 배편을 줄일 수 있습니다. 잠시 후 위층 관제실로 올라가겠습니다. 그곳은 공간이 좁아서 열 명씩 두 그룹으로 나누겠습니다. 운영 요원들이 근무 중이니 목소리를 낮춰 주세요.","part":4},{"id":"p4-124","level":5,"topic":"국제공항 환승객 보안 검색 절차 변경 안내","talk_type":"안내 방송","voice":"female","script":"Attention, all connecting passengers. Due to a scheduled upgrade of the screening equipment in Terminal 2, the transfer security checkpoint near Gate B4 is temporarily closed. Passengers connecting to international flights should now use the checkpoint next to the duty-free area, while those connecting to domestic flights should proceed to the checkpoint at the end of the moving walkway. Please be aware that waiting times at both checkpoints are currently longer than usual. If your connecting flight departs within the next forty-five minutes, please don't join the regular line. Instead, speak to any staff member wearing a green vest, who can direct you to a priority lane. We apologize for the inconvenience.","graphic":{"title":"Terminal 2 Transfer Checkpoints","rows":[["Checkpoint","Location","Status"],["T1","Near Gate B4","Closed"],["T2","Next to duty-free area","Open"],["T3","End of moving walkway","Open"],["T4","Near Gate C10","Staff only"]]},"questions":[{"q":"Why is a checkpoint closed?","choices":["Equipment is being upgraded.","There are not enough staff.","A gate is being renovated.","A security problem occurred."],"answer":0,"type":"주제·목적","explanation":"'Due to a scheduled upgrade of the screening equipment'라고 했으므로 검색 장비 교체(업그레이드) 때문이다."},{"q":"Look at the graphic. Which checkpoint should a passenger connecting to a domestic flight use?","choices":["T1","T2","T3","T4"],"answer":2,"type":"시각 자료 연계","explanation":"국내선 환승객은 'the checkpoint at the end of the moving walkway'로 가라고 했다. 표에서 무빙워크 끝에 있는 곳은 T3다. T2는 국제선 환승객용이다."},{"q":"What should passengers with a flight leaving soon do?","choices":["Go directly to their gate","Talk to a staff member","Call their airline","Use the staff-only checkpoint"],"answer":1,"type":"요청·제안","explanation":"45분 안에 출발하는 승객은 'speak to any staff member wearing a green vest'라고 했다. 직원이 우선 통로로 안내해 준다. 직원 전용 검색대를 쓰라는 말은 없다."}],"translation":"환승객 여러분께 알려 드립니다. 제2터미널 검색 장비의 정기 교체로 인해 B4 게이트 근처 환승 보안 검색대가 임시로 폐쇄되었습니다. 국제선으로 환승하시는 승객은 이제 면세 구역 옆 검색대를, 국내선으로 환승하시는 승객은 무빙워크 끝에 있는 검색대를 이용해 주십시오. 현재 두 검색대 모두 대기 시간이 평소보다 길다는 점에 유의해 주십시오. 연결 항공편이 45분 안에 출발하는 경우 일반 줄에 서지 마십시오. 대신 초록색 조끼를 입은 직원에게 말씀하시면 우선 통로로 안내해 드립니다. 불편을 드려 죄송합니다.","part":4},{"id":"p4-125","level":5,"topic":"원격 근무 주제 패널 토론 사회자 개회","talk_type":"연설·소개","voice":"male","script":"Good afternoon, and welcome to the final panel of this year's Workplace Futures Conference. I'm Thomas Greer, and I'll be moderating today's discussion on the long-term effects of remote work on company culture. Our three panelists come at this question from very different angles. Priya Natarajan leads a software firm that has been fully remote for a decade. Martin Cole runs operations for a manufacturer where, for obvious reasons, most employees can't work from home. And Dr. Sofia Lindqvist has spent five years studying how hybrid teams communicate. I suspect they won't agree on everything, and frankly, I hope they don't. Each panelist will begin with a five-minute statement. After that, I'll put a few questions to them, and we'll save the last twenty minutes for questions from you. There are microphones in both aisles.","graphic":null,"questions":[{"q":"What is the topic of the panel?","choices":["Hiring software engineers","Remote work and company culture","Improving factory safety","Managing international teams"],"answer":1,"type":"주제·목적","explanation":"'the long-term effects of remote work on company culture'라고 했으므로 원격 근무가 회사 문화에 미치는 영향이 주제다."},{"q":"What does the speaker imply about Martin Cole's company?","choices":["It recently moved to remote work.","Its work must be done on-site.","It is a competitor of Ms. Natarajan's firm.","It sponsored the conference."],"answer":1,"type":"세부 사항","explanation":"제조업체이고 'for obvious reasons, most employees can't work from home'이라고 했으므로 대부분 현장에서 일해야 하는 회사다."},{"q":"Why does the speaker say, \"frankly, I hope they don't\"?","choices":["He wants the panel to end quickly.","He thinks a variety of opinions will make the discussion interesting.","He disagrees with all of the panelists.","He is worried that the panelists are not prepared."],"answer":1,"type":"의도 파악","explanation":"패널들이 모든 점에 동의하지 않을 것 같다는 말에 이어 '솔직히 그러지 않기를 바란다'고 했다. 서로 다른 관점이 토론을 더 흥미롭게 만들기를 기대한다는 뜻이다."}],"translation":"안녕하십니까, 올해 워크플레이스 퓨처스 콘퍼런스의 마지막 패널 토론에 오신 것을 환영합니다. 저는 토머스 그리어이고, 오늘 원격 근무가 회사 문화에 미치는 장기적 영향에 관한 토론의 사회를 맡았습니다. 세 패널은 이 질문에 아주 다른 각도에서 접근합니다. 프리야 나타라잔 씨는 10년째 완전 원격으로 운영되는 소프트웨어 회사를 이끌고 있습니다. 마틴 콜 씨는 당연한 이유로 대부분의 직원이 재택근무를 할 수 없는 제조업체의 운영을 책임지고 있습니다. 그리고 소피아 린드크비스트 박사는 하이브리드 팀이 어떻게 소통하는지를 5년 동안 연구해 왔습니다. 세 분이 모든 점에 동의하지는 않을 것 같은데, 솔직히 그러지 않기를 바랍니다. 각 패널이 먼저 5분씩 발언하겠습니다. 그 후 제가 몇 가지 질문을 드리고, 마지막 20분은 여러분의 질문을 받겠습니다. 양쪽 통로에 마이크가 있습니다.","part":4}];
